} from '@jini-ai/agent-runtime';
import { createApiError, type ApiError } from '@jini-ai/protocol';
import type { AdapterContext } from '@jini-ai/http-kit';
import { validationError } from '@jini-ai/http-kit';
import { sendApiError } from '@jini-ai/http-kit';
import { guardSameOrigin } from '@jini-ai/http-kit';
import { createSseChannel, type SseChannel, type SseEvent } from '@jini-ai/http-kit';
import { err, ok, type Result } from '@jini-ai/http-kit';
import {
  firstOptionalFieldError,
  isArray,
  isNumber,
  isRecord,
  isString,
  nonEmptyString,
  pickDefined,
  requiredFieldError,
  type OptionalFieldCheck,
} from './model-proxy-fields.js';

/** The union of every recognized provider's `run{Provider}ToolTurn` event type — what the `/api/proxy/:provider/stream` catch-all's registry (and, transitively, every fixed-path route) can emit. */
type AnyProxyTurnEvent = AnthropicTurnEvent | OpenAiTurnEvent | AzureTurnEvent | GoogleTurnEvent | OllamaTurnEvent;

/** Diagnostic detail for an internal-error response this route deliberately does not disclose to the client (SEC-005, matching `runs.ts#RunInternalErrorContext`). Only reached if a turn-runner's promise itself rejects — every turn-runner already converts every provider/network failure into an `'error'`+`'end'` event pair internally, so this is a genuinely unexpected-exception path (e.g. a caller-supplied `executeTool` throwing). */
export interface ModelProxyInternalErrorContext {
  readonly provider: 'anthropic' | 'openai' | 'azure' | 'google' | 'ollama';
  readonly correlationId: string;
  readonly error: unknown;
}

function defaultInternalErrorSink(context: ModelProxyInternalErrorContext): void {
  // eslint-disable-next-line no-console
  console.error(`[@jini-ai/http-kit] internal error (model-proxy/${context.provider}, correlationId=${context.correlationId})`, redactSecrets({ input: inspect(context.error) }, { redactPii: false }));
}

export interface ModelProxyHttpDeps {
  /** Host-owned tool execution for the Anthropic proxy route. Omit to stream `tool_use` events without running a server-side tool loop (see module doc). */
  readonly anthropicExecuteTool?: AnthropicToolExecutor;
  /** Host-owned tool execution for the OpenAI proxy route. Same default-unset behavior as `anthropicExecuteTool`. */
  readonly openaiExecuteTool?: OpenAiToolExecutor;
  /** Host-owned tool execution for the Azure OpenAI proxy route. Same default-unset behavior as `anthropicExecuteTool`. */
  readonly azureExecuteTool?: AzureToolExecutor;
  /** Host-owned tool execution for the Google (Gemini) proxy route. Same default-unset behavior as `anthropicExecuteTool`. */
  readonly googleExecuteTool?: GoogleToolExecutor;
  /** Host-owned tool execution for the Ollama proxy route. Same default-unset behavior as `anthropicExecuteTool`. */
  readonly ollamaExecuteTool?: OllamaToolExecutor;
  /** Host-owned sink for the real exception behind a generic internal-error SSE event (SEC-005). Defaults to `console.error`. */
  readonly onInternalError?: (context: ModelProxyInternalErrorContext) => void;
  /**
   * Injectable HTTP transport, forwarded verbatim to every provider turn-runner as its own
   * `fetchImpl` option (`@jini-ai/agent-runtime`'s `AnthropicTurnOptions.fetchImpl`, etc.), which
   * itself defaults to that package's SSRF-guarded, DNS-pinned `pinnedFetch`. This is the
   * dependency-injection seam `__tests__/model-proxy.test.ts` uses to supply a fake transport
   * directly, instead of module-mocking `@jini-ai/agent-runtime`'s `connection-guard.ts` (or, worse,
   * its compiled `dist/` output, since this package only ever imports that package's single public
   * barrel). Defaults to unset, i.e. every route keeps using the real, guarded transport — **never
   * set this in production wiring**; doing so bypasses the SSRF guard entirely for whatever
   * transport is supplied.
   */
  readonly fetchImpl?: PinnedFetch;
  /**
   * Injectable DNS resolver, forwarded verbatim to every provider turn-runner as its own
   * `dnsLookup` option, which itself defaults to `@jini-ai/agent-runtime`'s `node:dns`-backed
   * `defaultDnsLookup`. Same test-only override rationale as `fetchImpl` — pairs with it so a test
   * never needs to mock `node:dns` either.
   */
  readonly dnsLookup?: DnsLookupFn;
}

const TOOLS_CHECK: OptionalFieldCheck = ['tools', isArray, 'tools must be an array when provided'];
const SYSTEM_CHECK: OptionalFieldCheck = ['system', isString, 'system must be a string when provided'];

/** The shared optional fields, in the order `parseCommon` reports them. */
const COMMON_OPTIONAL_CHECKS: readonly OptionalFieldCheck[] = [
  ['baseUrl', isString, 'baseUrl must be a string when provided'],
  ['temperature', isNumber, 'temperature must be a number when provided'],
  ['maxTokens', isNumber, 'maxTokens must be a number when provided'],
  ['maxToolTurns', isNumber, 'maxToolTurns must be a number when provided'],
  ['extraHeaders', isRecord, 'extraHeaders must be an object when provided'],
];

interface ParsedProxyCommon {
  readonly apiKey: string;
  readonly baseUrl?: string;
  readonly model: string;
  readonly messages: unknown[];
  readonly temperature?: number;
  /** Optional here; individual providers narrow to required where their real API demands it (see `ParsedAnthropicProxyRequest`). OpenAI/Azure/Ollama all default to 8192 in their turn-runner when omitted — see each module's doc. */
  readonly maxTokens?: number;
  readonly maxToolTurns?: number;
  readonly extraHeaders?: Record<string, string>;
}

/** The required shared fields, in the order `parseCommon` reports them. */
function firstRequiredFieldError(body: Record<string, unknown>): ApiError | undefined {
  if (!nonEmptyString(body.apiKey)) return requiredFieldError('apiKey', 'apiKey must be a non-empty string', 'required non-empty string');
  if (!nonEmptyString(body.model)) return requiredFieldError('model', 'model must be a non-empty string', 'required non-empty string');
  if (!Array.isArray(body.messages) || body.messages.length === 0) {
    return requiredFieldError('messages', 'messages must be a non-empty array', 'required non-empty array');
  }
  return undefined;
}

/**
 * Validates only the transport-level shape every proxied request shares
 * (non-empty `apiKey`/`model`, a `messages` array, and the optional numeric/
 * record fields' primitive types) — never the *contents* of `messages` or
 * `tools`, which is provider wire-protocol knowledge this package does not
 * have (see module doc). A malformed message/tool shape is instead rejected
 * by the real provider API and surfaces as a normal `'error'` SSE event,
 * exactly like any other upstream rejection.
 *
 * SECURITY: `apiKey` travels in this JSON body, not an `Authorization` header
 * — a deliberate BYOK design choice (see module doc), not an oversight, but
 * one that only stays safe because every caller of this function is reached
 * through `runProxyStream`/`registerGenericProxyStreamRoute`, both of which
 * call `guardSameOrigin` before this parser ever runs (confirmed 2026-08-23;
 * see the "rejects a cross-origin request with 403 before touching fetch"
 * regression test per provider, plus the catch-all's own, in
 * `__tests__/model-proxy.test.ts` — each proves the credential is never
 * forwarded to `fetch` for a rejected cross-origin request). Do not loosen or
 * remove that same-origin enforcement without first moving `apiKey` to a
 * header — a body-carried credential is not safe to accept cross-origin.
 */
function parseCommon(body: unknown): Result<ParsedProxyCommon> {
  if (!isRecord(body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });
  const error = firstRequiredFieldError(body) ?? firstOptionalFieldError(body, COMMON_OPTIONAL_CHECKS);
  if (error) return err({ error });
  return ok({
    value: {
      apiKey: body.apiKey as string,
      model: body.model as string,
      messages: body.messages as unknown[],
      ...(pickDefined(body, COMMON_OPTIONAL_CHECKS.map(([field]) => field)) as Partial<ParsedProxyCommon>),
    },
  });
}

/** Shared tail of every provider parser: rejects the first badly-typed provider-specific optional field, otherwise returns `base` plus `required` plus whichever of those optional fields are present. */
function extendParsed<Parsed extends ParsedProxyCommon>(
  { base, record, checks }: { readonly base: ParsedProxyCommon; readonly record: Record<string, unknown>; readonly checks: readonly OptionalFieldCheck[] },
  { required = {} }: { readonly required?: Partial<Parsed> } = {},
): Result<Parsed> {
  const error = firstOptionalFieldError(record, checks);
  if (error) return err({ error });
  const optional = pickDefined(record, checks.map(([field]) => field)) as Partial<Parsed>;
  return ok({ value: { ...base, ...required, ...optional } as Parsed });
}

interface ParsedAnthropicProxyRequest extends ParsedProxyCommon {
  readonly apiVersion?: string;
  readonly system?: string;
  readonly tools?: unknown[];
  readonly maxTokens: number;
}

const ANTHROPIC_OPTIONAL_CHECKS: readonly OptionalFieldCheck[] = [
  ['apiVersion', isString, 'apiVersion must be a string when provided'],
  SYSTEM_CHECK,
  TOOLS_CHECK,
];

function isPositiveFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

function parseAnthropicProxyRequest(body: unknown): Result<ParsedAnthropicProxyRequest> {
  const common = parseCommon(body);
  if (!common.ok) return common;
  const record = body as Record<string, unknown>;
  if (!isPositiveFiniteNumber(record.maxTokens)) {
    return err({ error: requiredFieldError('maxTokens', 'maxTokens must be a positive number', 'required positive number') });
  }
  return extendParsed<ParsedAnthropicProxyRequest>({ base: common.value, record, checks: ANTHROPIC_OPTIONAL_CHECKS }, { required: { maxTokens: record.maxTokens } });
}

/**
 * OpenAI and Ollama accept the identical request shape: the shared fields plus optional `tools`.
 *
 * Ollama is built on `parseCommon` like every other provider — `apiKey` is required, matching Open
 * Design's real `/api/proxy/ollama/stream` handler (`apps/daemon/src/routes/chat.ts:1298`'s
 * `if (!apiKey || !model)`), confirmed by a live side-by-side comparison against a running OD
 * daemon. An earlier version of this function made `apiKey` optional for a "local Ollama needs no
 * auth" rationale that turned out not to match OD's actual behavior — OD's default target is
 * Ollama Cloud (`https://ollama.com`), which does require a key; see `ollama-chat.ts`'s module doc
 * for the full corrected design.
 */
interface ParsedToolsProxyRequest extends ParsedProxyCommon {
  readonly tools?: unknown[];
}

function parseToolsProxyRequest(body: unknown): Result<ParsedToolsProxyRequest> {
  const common = parseCommon(body);
  if (!common.ok) return common;
  return extendParsed<ParsedToolsProxyRequest>({ base: common.value, record: body as Record<string, unknown>, checks: [TOOLS_CHECK] });
}

interface ParsedAzureProxyRequest extends ParsedProxyCommon {
  /** Required for Azure, unlike the other four providers — every Azure OpenAI resource has its own endpoint (see `@jini-ai/agent-runtime`'s `azure-chat.ts`). */
  readonly baseUrl: string;
  /** Required for Azure — no sane global default exists at the HTTP-request-shape level either (the turn-runner itself does have a `'2024-10-21'` fallback, but this route requires the caller be explicit). */
  readonly apiVersion: string;
  readonly tools?: unknown[];
}

function parseAzureProxyRequest(body: unknown): Result<ParsedAzureProxyRequest> {
  const common = parseCommon(body);
  if (!common.ok) return common;
  const record = body as Record<string, unknown>;
  const { baseUrl } = common.value;
  // Truthiness only, unlike `apiVersion`'s trim check: a whitespace-only baseUrl passes here and
  // fails inside the turn-runner instead (pinned as "reported, not fixed").
  if (!baseUrl) {
    return err({ error: requiredFieldError('baseUrl', 'baseUrl must be a non-empty string', 'required non-empty string') });
  }
  const apiVersion = nonEmptyString(record.apiVersion);
  if (!apiVersion) {
    return err({ error: requiredFieldError('apiVersion', 'apiVersion must be a non-empty string', 'required non-empty string') });
  }
  return extendParsed<ParsedAzureProxyRequest>({ base: common.value, record, checks: [TOOLS_CHECK] }, { required: { baseUrl, apiVersion } });
}

interface ParsedGoogleProxyRequest extends ParsedProxyCommon {
  readonly system?: string;
  readonly tools?: unknown[];
  readonly maxOutputTokens?: number;
}

const GOOGLE_OPTIONAL_CHECKS: readonly OptionalFieldCheck[] = [
  SYSTEM_CHECK,
  TOOLS_CHECK,
  ['maxOutputTokens', isNumber, 'maxOutputTokens must be a number when provided'],
];

/** `parsed.messages` carries Gemini's own `contents: [{role, parts}]` shape at the call site below (cast, same convention as `parsed.messages as unknown as readonly AnthropicMessageParam[]`) — the HTTP JSON body schema stays uniform across all five providers; only each turn-runner's own field name differs. */
function parseGoogleProxyRequest(body: unknown): Result<ParsedGoogleProxyRequest> {
  const common = parseCommon(body);
  if (!common.ok) return common;
  return extendParsed<ParsedGoogleProxyRequest>({ base: common.value, record: body as Record<string, unknown>, checks: GOOGLE_OPTIONAL_CHECKS });
}

interface ModelProxyStreamEvent extends SseEvent {
  readonly data: AnyProxyTurnEvent;
}

/** Wraps a raw turn-runner event for `sse.ts`'s generic channel: `kind` drives both the wire `event:` field and `createSseChannel`'s `isEndEvent` auto-close, `data` preserves the exact event shape agent-runtime produced. */
function toStreamEvent(seq: number, event: AnyProxyTurnEvent): ModelProxyStreamEvent {
  return { opaqueCursor: String(seq), kind: event.type, data: event };
}

/** Answers a failure that happened before any SSE stream existed: a redacted JSON 500 if nothing was sent yet, otherwise just end the response (matching `mountJsonRoute`'s own SEC-005 catch). */
function respondInternalError(res: Response, correlationId: string): void {
  if (res.headersSent) {
    if (!res.writableEnded) res.end();
    return;
  }
  sendApiError({ res, status: 500, error: createApiError({ code: 'INTERNAL_ERROR', message: 'The assistant response stopped. Review any completed actions before starting another turn. Copy the request ID and report this problem.' }, { requestId: correlationId }) });
}

type ProxyProvider = ModelProxyInternalErrorContext['provider'];
type InternalErrorSink = (context: ModelProxyInternalErrorContext) => void;

/** Type-erased registry entry: one provider's request parser plus its turn-runner call. See {@link buildProxyProviderRegistry}. */
interface ProxyProviderRegistryEntry {
  readonly parse: (body: unknown) => Result<unknown>;
  readonly run: (parsed: unknown, onEvent: (event: { type: string }) => void) => Promise<unknown>;
}

/**
 * The actual request handler body, shared by every fixed-path route and the `:provider`
 * catch-all: same-origin guard, request parsing, SSE channel lifecycle, and the SEC-005 catch-all
 * for a turn-runner promise that rejects outright (see module doc). Provider-specific pieces
 * (`provider`, `entry.parse`, `entry.run`) are injected, so the generic catch-all route below can
 * invoke the identical logic with a `provider` value read from `req.params` instead of a fixed
 * string, without duplicating the SSE-wiring/error-handling code a second time.
 */
async function runProxyStream({ req, res, adapter, provider, onInternalError, entry }: {
  readonly req: Request;
  readonly res: Response;
  readonly adapter: AdapterContext;
  readonly provider: ProxyProvider;
  readonly onInternalError: InternalErrorSink;
  readonly entry: ProxyProviderRegistryEntry;
}): Promise<void> {
  // Both `channel` and `seq` are declared ahead of the try so the catch block below can still
  // reach them however far execution got — including a throw from `guardSameOrigin`/`parse`,
  // before either exists yet.
  let seq = 0;
  const nextSeq = () => {
    const current = seq;
    seq += 1;
    return current;
  };
  let channel: SseChannel<ModelProxyStreamEvent> | undefined;
  try {
    const origin = guardSameOrigin({ req, origin: adapter });
    if (!origin.ok) {
      sendApiError({ res, status: 403, error: origin.error });
      return;
    }
    const parsed = entry.parse(req.body);
    if (!parsed.ok) {
      sendApiError({ res, status: 400, error: parsed.error });
      return;
    }

    const openChannel = createSseChannel<ModelProxyStreamEvent>({ res }, { isEndEvent: ({ event }) => event.kind === 'end' });
    channel = openChannel;
    openChannel.open();

    await entry.run(parsed.value, (event) => openChannel.enqueue({ event: toStreamEvent(nextSeq(), event as AnyProxyTurnEvent) }));
    // No `channel.end()` call here: every reachable exit path inside every turn-runner emits
    // exactly one `'end'`-kind event before its promise resolves (the duplicate-end-event fix —
    // see each provider module's own `turn-end-guard.ts` usage, and each function's own
    // `while (true)` loop, which cannot exit without first calling `emitEnd`), and `isEndEvent`
    // above already auto-closed the channel the instant that event was enqueued.
  } catch (error) {
    // This catch now covers the whole handler, not just `run(...)`: neither caller of this
    // function (the fixed routes, `registerGenericProxyStreamRoute`'s catch-all) awaits or
    // `.catch()`s the promise this function returns — exactly how Express itself invokes every
    // handler. `guardSameOrigin`/`parse` are Result-returning by contract and don't throw today,
    // but nothing enforces that; if either ever did, the throw used to become an unhandled
    // rejection with no process-level guard anywhere in this package's path, which is Node's
    // documented crash-the-process default. See the paired regression test in
    // `__tests__/model-proxy.test.ts`.
    const correlationId = randomUUID();
    onInternalError({ provider, correlationId, error });
    if (!channel) {
      // The SSE channel was never opened (the throw happened before it), so no stream headers
      // were ever committed — a normal JSON error response is still possible here, matching how
      // `mountJsonRoute`'s own SEC-005 catch responds to a pre-response failure.
      respondInternalError(res, correlationId);
      return;
    }
    // `enqueue` is a documented no-op once the channel is already closed (`sse.ts`), so these
    // two synthetic events are safe to send unconditionally: normally the channel is still open
    // here (an exception escaping `run` — e.g. a caller-supplied `executeTool` throwing — means
    // no `'end'` event was ever emitted for this connection), and the synthetic `'end'`-kind
    // event's own `isEndEvent` match closes the channel via the same path as a real one.
    channel.enqueue({ event: toStreamEvent(nextSeq(), { type: 'error', message: 'The assistant response stopped. Review any completed actions before starting another turn. Copy the request ID and report this problem.', code: correlationId } as AnyProxyTurnEvent) });
    channel.enqueue({ event: toStreamEvent(nextSeq(), { type: 'end', reason: 'error' } as AnyProxyTurnEvent) });
  }
}

/** Erases one provider's concrete parse/run types into the registry's shared entry shape — the single cast every entry needs. */
function defineProvider<Parsed, TurnEvent extends { type: string }>(entry: {
  readonly parse: (body: unknown) => Result<Parsed>;
  readonly run: (parsed: Parsed, onEvent: (event: TurnEvent) => void) => Promise<unknown>;
}): ProxyProviderRegistryEntry {
  return entry as unknown as ProxyProviderRegistryEntry;
}

/** The test-seam transport options every turn-runner accepts; each is forwarded only when the host supplied it (see `ModelProxyHttpDeps.fetchImpl`). */
function transportOptions(deps: ModelProxyHttpDeps): { fetchImpl?: PinnedFetch; dnsLookup?: DnsLookupFn } {
  return {
    ...(deps.fetchImpl ? { fetchImpl: deps.fetchImpl } : {}),
    ...(deps.dnsLookup ? { dnsLookup: deps.dnsLookup } : {}),
  };
}

/** `tools` cast to the turn-runner's own tool-definition type, forwarded only when present (the parser never inspects tool contents — see `parseCommon`). */
function toolsOption<ToolDef>(tools: unknown[] | undefined): { tools?: readonly ToolDef[] } {
  return tools !== undefined ? { tools: tools as unknown as readonly ToolDef[] } : {};
}

/**
 * Builds the `provider name -> {parse, run}` table that both the five fixed routes and the generic
 * catch-all dispatch through. Each entry's `run` closure captures `deps` for the optional
 * `executeTool` wiring and the transport test seams. `executeTool` is a fresh wrapper that calls
 * `deps.<provider>ExecuteTool` as a method at call time, so the host function sees exactly one
 * argument.
 */
function buildProxyProviderRegistry(deps: ModelProxyHttpDeps): Record<string, ProxyProviderRegistryEntry> {
  return {
    anthropic: defineProvider({
      parse: parseAnthropicProxyRequest,
      run: (parsed, onEvent: (event: AnthropicTurnEvent) => void) =>
        runAnthropicToolTurn(
          { apiKey: parsed.apiKey, model: parsed.model, maxTokens: parsed.maxTokens, messages: parsed.messages as unknown as readonly AnthropicMessageParam[], onEvent },
          {
            ...pickDefined(parsed, ['baseUrl', 'apiVersion', 'system', 'temperature', 'maxToolTurns', 'extraHeaders']),
            ...toolsOption<AnthropicToolDef>(parsed.tools),
            ...transportOptions(deps),
            ...(deps.anthropicExecuteTool ? { executeTool: (call: AnthropicToolCall): Promise<AnthropicToolResult> => deps.anthropicExecuteTool!(call) } : {}),
          },
        ),
    }),
    openai: defineProvider({
      parse: parseToolsProxyRequest,
      run: (parsed, onEvent: (event: OpenAiTurnEvent) => void) =>
        runOpenAiToolTurn(
          { apiKey: parsed.apiKey, model: parsed.model, messages: parsed.messages as unknown as readonly OpenAiMessageParam[], onEvent },
          {
            ...pickDefined(parsed, ['baseUrl', 'temperature', 'maxTokens', 'maxToolTurns', 'extraHeaders']),
            ...toolsOption<OpenAiFunctionToolDef>(parsed.tools),
            ...transportOptions(deps),
            ...(deps.openaiExecuteTool ? { executeTool: (call: OpenAiToolCall): Promise<OpenAiToolResult> => deps.openaiExecuteTool!(call) } : {}),
          },
        ),
    }),
    azure: defineProvider({
      parse: parseAzureProxyRequest,
      run: (parsed, onEvent: (event: AzureTurnEvent) => void) =>
        runAzureToolTurn(
          { apiKey: parsed.apiKey, baseUrl: parsed.baseUrl, model: parsed.model, messages: parsed.messages as unknown as readonly AzureMessageParam[], onEvent },
          {
            apiVersion: parsed.apiVersion,
            ...pickDefined(parsed, ['temperature', 'maxTokens', 'maxToolTurns', 'extraHeaders']),
            ...toolsOption<AzureFunctionToolDef>(parsed.tools),
            ...transportOptions(deps),
            ...(deps.azureExecuteTool ? { executeTool: (call: AzureToolCall): Promise<AzureToolResult> => deps.azureExecuteTool!(call) } : {}),
          },
        ),
    }),
    google: defineProvider({
      parse: parseGoogleProxyRequest,
      run: (parsed, onEvent: (event: GoogleTurnEvent) => void) =>
        runGoogleToolTurn(
          { apiKey: parsed.apiKey, model: parsed.model, contents: parsed.messages as unknown as readonly GoogleContent[], onEvent },
          {
            ...pickDefined(parsed, ['baseUrl', 'system', 'temperature', 'maxOutputTokens', 'maxToolTurns', 'extraHeaders']),
            ...toolsOption<GoogleToolDef>(parsed.tools),
            ...transportOptions(deps),
            ...(deps.googleExecuteTool ? { executeTool: (call: GoogleToolCall): Promise<GoogleToolResult> => deps.googleExecuteTool!(call) } : {}),
          },
        ),
    }),
    ollama: defineProvider({
      parse: parseToolsProxyRequest,
      run: (parsed, onEvent: (event: OllamaTurnEvent) => void) =>
        runOllamaToolTurn(
          { apiKey: parsed.apiKey, model: parsed.model, messages: parsed.messages as unknown as readonly OllamaMessageParam[], onEvent },
          {
            ...pickDefined(parsed, ['baseUrl', 'temperature', 'maxTokens', 'maxToolTurns', 'extraHeaders']),
            ...toolsOption<OllamaFunctionToolDef>(parsed.tools),
            ...transportOptions(deps),
            ...(deps.ollamaExecuteTool ? { executeTool: (call: OllamaToolCall): Promise<OllamaToolResult> => deps.ollamaExecuteTool!(call) } : {}),
          },
        ),
    }),
  };
}

/** Fixed-route registration order; load-bearing, since Express matches in registration order and the catch-all must come after all five. */
const PROXY_PROVIDERS: readonly ProxyProvider[] = ['anthropic', 'openai', 'azure', 'google', 'ollama'];

const RECOGNIZED_PROVIDERS: ReadonlySet<ProxyProvider> = new Set(PROXY_PROVIDERS);

function isRecognizedProvider(value: string): value is ProxyProvider {
  return RECOGNIZED_PROVIDERS.has(value as ProxyProvider);
}

/** Reports a throw from the catch-all before `runProxyStream` took over. */
function reportCatchAllError(providerParam: string, onInternalError: InternalErrorSink, error: unknown): string {
  const correlationId = randomUUID();
  // `onInternalError`'s contract only accepts the 5 recognized provider literals; a throw
  // this early (e.g. `guardSameOrigin`) may have happened before the provider name was even
  // validated, so an unrecognized/empty `providerParam` logs directly instead of lying to
  // that typed contract with a provider that was never actually confirmed.
  if (isRecognizedProvider(providerParam)) {
    onInternalError({ provider: providerParam, correlationId, error });
  } else {
    // eslint-disable-next-line no-console
    console.error(`[@jini-ai/http-kit] internal error (model-proxy/${providerParam || 'unknown'}, correlationId=${correlationId})`, redactSecrets({ input: inspect(error) }, { redactPii: false }));
  }
  return correlationId;
}

/**
 * Mounts `POST /api/proxy/:provider/stream` — see module doc's "the `:provider` catch-all's
 * relationship to the five fixed routes" section for why an unrecognized-but-registry-present
 * provider name is the only branch of this handler real HTTP traffic can reach for the five known
 * provider ids.
 */
function registerGenericProxyStreamRoute({ app, adapter, onInternalError, registry }: {
  readonly app: Express;
  readonly adapter: AdapterContext;
  readonly onInternalError: InternalErrorSink;
  readonly registry: Record<string, ProxyProviderRegistryEntry>;
}): void {
  app.post('/api/proxy/:provider/stream', async (req: Request, res: Response) => {
    // Unlike the five fixed routes, this catch-all's own `guardSameOrigin` call sits ahead of
    // `runProxyStream` (the registry lookup below has to happen first, to even know which
    // `provider` string to hand `onInternalError`) — so it needs its own guard against the same
    // failure class `runProxyStream`'s catch already documents: `guardSameOrigin` is
    // Result-returning by contract but not guaranteed never to throw (`isLocalSameOrigin` really
    // does throw on a malformed `JINI_ALLOWED_ORIGINS` entry — see `origin-validation.ts`), and
    // this handler's returned promise is never awaited or `.catch()`-ed by Express, so an
    // uncaught throw here becomes an unhandled rejection with no process-level guard. See the
    // paired regression test in `__tests__/model-proxy.test.ts`.
    //
    // Read ahead of the try: plain property/index access on `req.params`/`registry`, never
    // throws, and the catch below needs it regardless of how far execution got.
    const providerParam = req.params.provider ?? '';
    try {
      const origin = guardSameOrigin({ req, origin: adapter });
      if (!origin.ok) {
        sendApiError({ res, status: 403, error: origin.error });
        return;
      }
      // Both checks are needed: `registry` is a plain object, so an inherited key such as
      // `constructor` yields a truthy `entry` that only the recognized-provider set rejects.
      const entry = registry[providerParam];
      if (!entry || !isRecognizedProvider(providerParam)) {
        sendApiError({ res, status: 400, error: createApiError({ code: 'BAD_REQUEST', message: `unknown provider: ${providerParam}` }) });
        return;
      }
      await runProxyStream({ req, res, adapter, provider: providerParam, onInternalError, entry });
    } catch (error) {
      // No SSE channel can exist yet at this point — `runProxyStream` owns opening one, and this
      // catch only reaches errors thrown before that call. A plain JSON error response is always
      // still possible, matching `runProxyStream`'s own "channel never opened" branch.
      respondInternalError(res, reportCatchAllError(providerParam, onInternalError, error));
    }
  });
}

/** Mounts `POST /api/proxy/{anthropic,openai,azure,google,ollama}/stream` and the generic `POST /api/proxy/:provider/stream` catch-all. */
export function registerModelProxyRoutes({ app, deps, adapter }: { readonly app: Express; readonly deps: ModelProxyHttpDeps; readonly adapter: AdapterContext }, _optional: Record<string, never> = {}): void {
  const onInternalError = deps.onInternalError ?? defaultInternalErrorSink;
  const registry = buildProxyProviderRegistry(deps);

  // Each fixed route is a thin wrapper over `runProxyStream` with `provider` fixed, not read from
  // `req.params`.
  for (const provider of PROXY_PROVIDERS) {
    const entry = registry[provider]!;
    app.post(`/api/proxy/${provider}/stream`, (req: Request, res: Response) =>
      runProxyStream({ req, res, adapter, provider, onInternalError, entry }),
    );
  }

  registerGenericProxyStreamRoute({ app, adapter, onInternalError, registry });
}

/**
 * @module remote-run-events
 *
 * `POST /api/runs/:runId/tool-use` and `POST /api/runs/:runId/tool-result` — lets a tool call that
 * executed in a DIFFERENT OS process from the one holding this run's `RunLifecycle` report its
 * outcome back into the run's own event log, so SSE subscribers (a chat UI, a reattaching client)
 * see it exactly as they would a locally-executed delegated tool call.
 *
 * This exists to relax `@jini-ai/daemon`'s co-location requirement (`RunLifecycle`/`ToolExecutor`
 * previously had to live in one process per run, because `DelegatedToolBridge.execute()` calls
 * `lifecycle.emit()` in-process with no remote reporting path).
 * It does not remove any authorization: whatever executed the tool remotely already ran it through
 * its OWN `ToolExecutor`/`ToolPolicy` gate before calling here. This route only lets that outcome
 * be recorded into a run it does not own the process of.
 *
 * **Deliberately a separate trust boundary from `registerApiBearerAuthMiddleware`'s general API
 * token** (`api-security-middleware.ts`): that token may reach browser-adjacent callers depending
 * on deployment. This route is meant only for a host's own trusted backend-to-backend delegation
 * (e.g. a sidecar tool-execution process reporting back to the process that owns the run), so its
 * token has no "disabled" escape hatch and does not exempt loopback peers the way the general
 * bearer gate does — a loopback bind is exactly the shape a same-machine but lower-trust process
 * would also present, and this route grants direct run-event-injection, a materially different
 * capability from what the general API token was designed to gate.
 */
import { inspect } from 'node:util';
import { redactSecrets } from '@jini-ai/core';
import { randomUUID } from 'node:crypto';
import type { Express, NextFunction, Request, Response } from 'express';
import { createApiError, isTerminalRunState } from '@jini-ai/protocol';
import type { RemoteToolEventRecorder, RunLifecycle } from '../index.js';
import { defineJsonRoute, mountJsonRoute, type AdapterContext } from '@jini-ai/http-kit';
import { bearerTokenFromHeader, timingSafeTokenMatch } from '@jini-ai/http-kit';
import { validationError } from '@jini-ai/http-kit';
import { sendApiError, statusForError } from '@jini-ai/http-kit';
import { err, ok, type Result, type RouteInputContext } from '@jini-ai/http-kit';

export interface RemoteToolBridgeTokenConfig {
  /** Env var name for the required shared secret. Defaults to `JINI_REMOTE_TOOL_BRIDGE_TOKEN`. */
  readonly tokenEnvVar?: string;
}

export interface RemoteRunEventInternalErrorContext {
  readonly source: 'tool-use' | 'tool-result';
  readonly correlationId: string;
  readonly error: unknown;
}

export interface RemoteRunEventHttpDeps {
  /** Used to distinguish "unknown run" (404) from other outcomes before recording — same precedent as `delegated-tools.ts`'s `delegatedToolExecuteRoute` — and again afterwards to classify a recorder failure (see {@link toRemoteEventError}). */
  readonly lifecycle: RunLifecycle;
  readonly recorder: RemoteToolEventRecorder;
  readonly tokenConfig?: RemoteToolBridgeTokenConfig;
  /** Defaults to `process.env`. Threaded through so tests never have to mutate real process env. */
  readonly env?: NodeJS.ProcessEnv;
  /** Host-owned sink for the real exception behind a generic `INTERNAL_ERROR` response (SEC-005). Defaults to `console.error`. */
  readonly onInternalError?: (context: RemoteRunEventInternalErrorContext) => void;
}

function defaultInternalErrorSink(context: RemoteRunEventInternalErrorContext): void {
  // eslint-disable-next-line no-console
  console.error(`[@jini-ai/http-kit] internal error (remote-run-events/${context.source}, correlationId=${context.correlationId})`, redactSecrets({ input: inspect(context.error) }, { redactPii: false }));
}

const DEFAULT_TOKEN_ENV_VAR = 'JINI_REMOTE_TOOL_BRIDGE_TOKEN';

/**
 * Gates both remote-run-event routes behind a dedicated shared secret. Unlike
 * `registerApiBearerAuthMiddleware`, there is no "unset means open" or "disabled" mode: a route
 * that lets a caller inject events into someone else's run must never silently run unauthenticated
 * just because a host forgot to configure the token. If the token isn't configured, the route
 * fails closed with 503, not 200.
 *
 * Kept as its own middleware rather than folded into `api-security-middleware.ts`'s
 * `requireStrictBearerToken` (which has the identical fail-closed/no-loopback-exemption posture)
 * because these two routes own their own error codes — `REMOTE_TOOL_BRIDGE_*`, distinct from the
 * general API token's, so an operator can tell which secret is missing from the response alone.
 * The *decision* logic is shared: header parsing and the constant-time comparison both come from
 * that module, so the two gates cannot drift on what counts as a well-formed header or on
 * comparison safety.
 */
export function requireRemoteToolBridgeToken(_required: Record<string, never>, deps: {
  readonly tokenConfig?: RemoteToolBridgeTokenConfig | undefined;
  readonly env?: NodeJS.ProcessEnv | undefined;
} = {}) {
  const tokenEnvVar = deps.tokenConfig?.tokenEnvVar ?? DEFAULT_TOKEN_ENV_VAR;
  const env = deps.env ?? process.env;
  return (req: Request, res: Response, next: NextFunction): void => {
    const token = env[tokenEnvVar];
    if (!token) {
      const error = createApiError({ code: 'REMOTE_TOOL_BRIDGE_NOT_CONFIGURED', message: `${tokenEnvVar} is not set — remote run-event ingestion is disabled` });
      sendApiError({ res, status: statusForError({ error }), error });
      return;
    }
    const presented = bearerTokenFromHeader({ header: req.get('authorization') });
    if (presented === null || !timingSafeTokenMatch({ presented, expected: token })) {
      const error = createApiError({ code: 'REMOTE_TOOL_BRIDGE_TOKEN_REQUIRED', message: `Authorization: Bearer <${tokenEnvVar}> required` });
      sendApiError({ res, status: statusForError({ error }), error });
      return;
    }
    next();
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function requireNonEmptyString(body: Record<string, unknown>, key: string): string | undefined {
  const value = body[key];
  return typeof value === 'string' && value.trim().length > 0 ? value : undefined;
}

/**
 * Like {@link requireNonEmptyString} but accepts `''`, for the one field where empty is a real
 * value rather than a missing one: a tool's result `content`.
 *
 * The local path already produces empty content legitimately — `serializeDelegatedToolOutput`
 * (`@jini-ai/daemon`'s `delegated-tool-bridge.ts`) maps a handler returning `undefined` to `''`,
 * and `DelegatedToolBridge.execute()` emits that verbatim as the `tool_result` event's `content`.
 * Rejecting `''` here would mean a tool that legitimately produces no output can be reported
 * in-process but **not** remotely — a silent semantic divergence between the two paths that would
 * surface as a 400 on the one tool call a host least expects to fail. Identifiers (`runId`,
 * `toolUseId`, `toolId`) keep the non-empty check: for those, empty really is missing.
 */
function requireString(body: Record<string, unknown>, key: string): string | undefined {
  const value = body[key];
  return typeof value === 'string' ? value : undefined;
}

function parseRunId(input: RouteInputContext): Result<string> {
  const runId = input.params.runId;
  return typeof runId === 'string' && runId.length > 0
    ? ok({ value: runId })
    : err({ error: validationError({ message: 'runId must be a non-empty path parameter' }) });
}

export interface RemoteToolUseRequest {
  readonly runId: string;
  readonly toolUseId: string;
  readonly toolId: string;
  readonly input?: unknown;
}

export interface RemoteToolResultRequest {
  readonly runId: string;
  readonly toolUseId: string;
  readonly content: string;
  readonly isError?: boolean;
}

export interface RemoteRunEventResponse {
  readonly recorded: true;
}

function parseRemoteToolUse(input: RouteInputContext): Result<RemoteToolUseRequest> {
  const parsedRunId = parseRunId(input);
  if (!parsedRunId.ok) return parsedRunId;
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });

  const toolUseId = requireNonEmptyString(input.body, 'toolUseId');
  if (toolUseId === undefined) {
    return err({ error: validationError({ message: 'toolUseId must be a non-empty string' }, { issues: [{ path: 'toolUseId', message: 'required non-empty string' }] }) });
  }
  const toolId = requireNonEmptyString(input.body, 'toolId');
  if (toolId === undefined) {
    return err({ error: validationError({ message: 'toolId must be a non-empty string' }, { issues: [{ path: 'toolId', message: 'required non-empty string' }] }) });
  }
  return ok({ value: { runId: parsedRunId.value, toolUseId, toolId, input: input.body.input } });
}

function parseRemoteToolResult(input: RouteInputContext): Result<RemoteToolResultRequest> {
  const parsedRunId = parseRunId(input);
  if (!parsedRunId.ok) return parsedRunId;
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });

  const toolUseId = requireNonEmptyString(input.body, 'toolUseId');
  if (toolUseId === undefined) {
    return err({ error: validationError({ message: 'toolUseId must be a non-empty string' }, { issues: [{ path: 'toolUseId', message: 'required non-empty string' }] }) });
  }
  // Empty is allowed here, deliberately — see `requireString`'s own doc for the local-path parity
  // this preserves. Only a non-string (or absent) `content` is a validation failure.
  const content = requireString(input.body, 'content');
  if (content === undefined) {
    return err({ error: validationError({ message: 'content must be a string' }, { issues: [{ path: 'content', message: 'required string' }] }) });
  }
  const isError = input.body.isError;
  if (isError !== undefined && typeof isError !== 'boolean') {
    return err({ error: validationError({ message: 'isError must be a boolean when provided' }, { issues: [{ path: 'isError', message: 'boolean when provided' }] }) });
  }
  return ok({ value: { runId: parsedRunId.value, toolUseId, content, ...(isError === undefined ? {} : { isError }) } });
}

/**
 * Records a caught `recordToolUse`/`recordToolResult` throw as the right HTTP outcome.
 *
 * `RunLifecycle.emit()` throws for two documented reasons (see `run-lifecycle.ts`'s own `emit`) —
 * unknown `runId` and "already terminal" — but the recorder call it sits behind can also fail for
 * reasons that are nobody's business but the operator's: an event-log write hitting a full disk, a
 * SQLite error naming its own file path, a driver fault carrying a credential in its message.
 *
 * This previously reported *every* one of those as `CONFLICT` carrying `error.message` verbatim,
 * which turned any such fault into an unauthenticated-adjacent information leak and mislabelled a
 * server fault as a client-resolvable conflict. So the outcome is now decided by the run's actual
 * state rather than by whatever the exception happened to say:
 *
 * - run is gone -> `NOT_FOUND` (it was there for the pre-check; it isn't now).
 * - run is terminal -> `CONFLICT`, the one legitimate business conflict. The message is
 *   *constructed here* from data this module already owns rather than forwarded from the
 *   exception, so even a misattributed error cannot smuggle its text out through this branch.
 * - anything else -> SEC-005: a generic `INTERNAL_ERROR` plus a correlation id, with the real
 *   error handed to the host's sink so it is diagnosable server-side but never echoed.
 *
 * Residual, deliberately accepted: a genuine storage fault that happens to coincide with an
 * already-terminal run is reported as `CONFLICT` rather than `INTERNAL_ERROR`. Distinguishing those
 * would require matching on `emit`'s message text, trading a rare wrong status code for a check
 * that breaks silently the next time that string is reworded. Either way nothing leaks, which is
 * the property that mattered.
 */
async function toRemoteEventError(
  error: unknown,
  runId: string,
  deps: RemoteRunEventHttpDeps,
  source: RemoteRunEventInternalErrorContext['source'],
): Promise<ReturnType<typeof createApiError>> {
  const status = await deps.lifecycle.get({ runId }).catch(() => undefined);
  if (status === undefined) {
    return createApiError({ code: 'NOT_FOUND', message: `run "${runId}" was not found` });
  }
  if (isTerminalRunState({ state: status.state })) {
    return createApiError({ code: 'CONFLICT', message: `run "${runId}" is already terminal — no further events can be recorded` }, {
      details: { runId },
    });
  }
  const correlationId = randomUUID();
  const sink = deps.onInternalError ?? defaultInternalErrorSink;
  sink({ source, correlationId, error });
  return createApiError({ code: 'INTERNAL_ERROR', message: 'an internal error occurred' }, { requestId: correlationId });
}

export const remoteToolUseRoute = defineJsonRoute<RemoteToolUseRequest, RemoteRunEventResponse, RemoteRunEventHttpDeps>({
  method: 'post', path: '/api/runs/:runId/tool-use', parse: parseRemoteToolUse, handle: async ({ input: input, deps: deps }) => {
    const run = await deps.lifecycle.get({ runId: input.runId });
    if (run === undefined) return err({ error: createApiError({ code: 'NOT_FOUND', message: `run "${input.runId}" was not found` }) });
    try {
      await deps.recorder.recordToolUse({ runId: input.runId, record: { toolUseId: input.toolUseId, toolId: input.toolId, input: input.input } });
      return ok({ value: { recorded: true } });
    } catch (error) {
      return err({ error: await toRemoteEventError(error, input.runId, deps, 'tool-use') });
    }
  }
});

export const remoteToolResultRoute = defineJsonRoute<RemoteToolResultRequest, RemoteRunEventResponse, RemoteRunEventHttpDeps>({
  method: 'post', path: '/api/runs/:runId/tool-result', parse: parseRemoteToolResult, handle: async ({ input: input, deps: deps }) => {
    const run = await deps.lifecycle.get({ runId: input.runId });
    if (run === undefined) return err({ error: createApiError({ code: 'NOT_FOUND', message: `run "${input.runId}" was not found` }) });
    try {
      await deps.recorder.recordToolResult({ runId: input.runId, record: {
        toolUseId: input.toolUseId,
        content: input.content,
        ...(input.isError === undefined ? {} : { isError: input.isError }),
      } });
      return ok({ value: { recorded: true } });
    } catch (error) {
      return err({ error: await toRemoteEventError(error, input.runId, deps, 'tool-result') });
    }
  }
});

/**
 * Mounts both remote-run-event routes on `app`, gated by {@link requireRemoteToolBridgeToken}.
 * Unlike `registerRunRoutes`/`registerDelegatedToolRoutes`, these routes do not use
 * `requireSameOrigin` — they are not meant to be called from a browser at all, only from a host's
 * own trusted backend process, so the dedicated bearer token above is the sole gate.
 */
export function registerRemoteRunEventRoutes({ app, deps, adapter }: { readonly app: Express; readonly deps: RemoteRunEventHttpDeps; readonly adapter: AdapterContext }, _optional: Record<string, never> = {}): void {
  const gate = requireRemoteToolBridgeToken({}, deps);
  app.use('/api/runs/:runId/tool-use', gate);
  app.use('/api/runs/:runId/tool-result', gate);
  mountJsonRoute({ app, spec: remoteToolUseRoute, deps, adapter });
  mountJsonRoute({ app, spec: remoteToolResultRoute, deps, adapter });
}

/**
 * @module research
 *
 * `POST /api/research/search` — a thin route wrapper over Tavily's real Search API
 * (`POST {baseUrl}/search`), ported from OD's `apps/daemon/src/research/tavily.ts` (the low-level
 * Tavily client) **and** `apps/daemon/src/research/index.ts#searchResearch` (the findings-assembly
 * wrapper the real `/api/research/search` route in `apps/daemon/src/routes/media.ts` actually
 * calls). Verified against a **live** boot of OD's real daemon (`apps/daemon/bin/od.mjs`, from the
 * sibling `/Users/la/Desktop/Programming/OSS-Repos/open-design` checkout on this machine) hitting
 * the real route with a mock Tavily backend, not just static reading — see the field-by-field notes
 * below for what that live diff actually found. The request/response shape and defaults are ported
 * (`search_depth: 'basic'`, `include_answer: true`, `include_raw_content: false`, a 20-result hard
 * cap, the `results[]` -> `ResearchSource[]` mapping, the 1000-char query cap, the
 * `Math.floor`+clamp-to-`[1,20]` `maxSources` normalization, and the `NO_RESEARCH_SOURCES`-style
 * "zero sources is a failure, not an empty success" behavior) — OD's own `TavilyError`/
 * `ResearchError` classes and `requestInit.dispatcher` passthrough are not carried over; this route
 * pack's own SEC-005 error-handling convention (a generic `INTERNAL_ERROR` + correlation id,
 * matching every other route pack in this package) replaces the origin's thrown-error shape for
 * genuinely unexpected failures. OD's `AbortController`-based 30s timeout **is** carried over
 * (added after an external audit flagged its absence — a stalled/malicious upstream could otherwise
 * hold a request indefinitely, since bare `fetch` has no default timeout): `tavilySearch` aborts
 * the request after `DEFAULT_TAVILY_TIMEOUT_MS` and clears the timer in a `finally` regardless of
 * outcome. No other request-level knobs (connection pooling, `dispatcher`) are exposed yet — a
 * future pass can add them the same way `media.ts#MediaGenerationRequestInit` optionally threads a
 * `dispatcher` through, if a real need for one shows up.
 *
 * **`ResearchSource` field names match OD's real `@open-design/contracts/api/research.ts`
 * `ResearchSource` shape** (`title`/`url`/`snippet`/`publishedAt?`/`provider`). **`ResearchSearchResponse`
 * matches that same contract file's `ResearchFindings` shape** (`query`/`summary`/`sources`/
 * `provider`/`depth`/`fetchedAt`) — an earlier version of this port conflated the *raw Tavily
 * client's* return shape (`tavily.ts`'s `{ answer, sources }`) with the *route's actual HTTP
 * response* shape (`research/index.ts#searchResearch`'s `ResearchFindings`), which the live daemon
 * diff caught: hitting the real `/api/research/search` with a mock Tavily backend returned
 * `{"query":"...","summary":"...","sources":[...],"provider":"tavily","depth":"shallow",
 * "fetchedAt":<ms>}`, never `{answer, sources}`. `depth` is hardcoded to the `'shallow'` literal
 * (rather than OD's full `'shallow' | 'medium' | 'deep'` `ResearchDepth` union) since this port, like
 * OD's real Phase-1 `searchResearch`, only ever produces `'shallow'` — there is no depth-selection
 * request field on either side yet.
 *
 * **`providers` request field**: OD's real route accepts an optional `providers: string[]` and only
 * inspects `providers[0]` (defaulting to `'tavily'` when absent/empty); a non-array value is treated
 * as absent (not rejected), and a first element other than `'tavily'` is rejected with a 400 before
 * credentials are even resolved (`UNSUPPORTED_RESEARCH_PROVIDER` in OD; this port's own generic
 * `BAD_REQUEST` validation-error convention here, same as every other `parse`-time rejection in this
 * file). Confirmed live: `providers: ["bing"]` 400s on the real daemon, `providers: ["tavily"]`
 * succeeds identically to omitting the field.
 *
 * **Credential resolution**: `resolveCredentials` defaults to this transport's narrow
 * `TAVILY_API_KEY` environment seam. A host with its own secrets layer supplies its own resolver
 * instead; this daemon route pack deliberately does not depend on the incubating media implementation
 * package. Note OD's real env-var precedence is
 * `['OD_TAVILY_API_KEY', 'TAVILY_API_KEY']` (checked live via `apps/daemon/tests/research.test.ts`'s
 * `TAVILY_ENV_KEYS`) — this package's own `@jini-ai/media#PROVIDER_CREDENTIAL_ENV_VARS.tavily` only
 * lists `['TAVILY_API_KEY']`, deliberately dropping the `OD_`-prefixed variant: this repo's own
 * `AGENTS.md` boundary rule bans product-identity strings (including the `OD_` prefix) inside
 * `packages/@jini-ai/**`, so that omission is a hard constraint, not a port gap.
 *
 * **Missing credentials is a clean `NOT_CONFIGURED` (503), not an `INTERNAL_ERROR`.** No API key
 * configured is an expected, non-exceptional state (matching `connectors.ts`'s "capability exists,
 * reachable, inert until configured" shape) — it never reaches the SEC-005 sink, since there is no
 * real exception or secret to hide, just an honest "not set up yet" answer. OD's real behavior here
 * (confirmed live) is a 400 `TAVILY_API_KEY_MISSING`, not a 503 — this is a deliberate, documented
 * divergence from OD (this package's own generic-error-code convention, applied consistently across
 * every route pack) rather than an oversight, so it is intentionally **not** changed to match OD's
 * 400.
 *
 * **Zero sources is a `NOT_FOUND` (404), not a `200` with an empty array.** OD's real
 * `searchResearch` throws `ResearchError('no sources found', 404, 'NO_RESEARCH_SOURCES')` when
 * Tavily's `results[]` maps to zero usable sources (confirmed live against a mock Tavily backend
 * that returns `results: []`) — this port matches that with the package's own generic `NOT_FOUND`
 * code (mapped to 404 by `response.ts#ERROR_STATUS_BY_CODE`) rather than inventing a
 * research-specific code, same rationale as the `NOT_CONFIGURED` choice above.
 *
 * **Query normalization**: OD's real `searchResearch` trims the query and caps it at 1000 characters
 * before ever calling Tavily (`(input.query?.trim() || '').slice(0, 1000)`) — confirmed live by
 * sending a padded, 1112-char query and observing the daemon forward exactly 1000 trimmed
 * characters to the mock Tavily backend. This port replicates both the trim and the cap in
 * `parseResearchSearch`.
 *
 * **`maxSources` normalization**: OD's real `clampMaxSources` is `Math.max(1, Math.min(Math.floor(value),
 * 20))` — confirmed live by sending `maxSources: 2.7` and observing `max_results: 2` (not `2.7`) on
 * the wire to the mock Tavily backend. An earlier version of this port only clamped the range
 * (`Math.max(0, Math.min(value, 20))`) without flooring, which could forward a fractional
 * `max_results` straight to Tavily's real API for any non-integer input (e.g. `maxSources: 0.5`
 * would have clamped to `0.5`, not `1`); this port now floors first, matching OD.
 *
 * **SEC-005 for everything else**: a genuine Tavily request/response failure is caught, reported
 * through `onInternalError` (defaults to `console.error`, matching every other route pack), and
 * surfaced to the caller as a generic `INTERNAL_ERROR` — the raw error message (which can echo
 * request details) is never sent to the HTTP caller directly. `redactSecrets` (reused from
 * `@jini-ai/core`'s `connection-guard.ts`, already reachable via this package's existing
 * `@jini-ai/agent-runtime` dependency — the same "shared primitive, one implementation" reuse this
 * task's agent-runtime work applied to `sse-decode.ts`/`turn-end-guard.ts`) strips the bearer
 * token out of any upstream error text before it is even logged, belt-and-braces alongside the
 * generic-message substitution.
 */
import { inspect } from 'node:util';
import { redactSecrets } from '@jini-ai/core';
import { randomUUID } from 'node:crypto';
import type { Express } from 'express';
import { createTavilyResearchProvider } from './research-tavily.adapter.js';
import { createApiError } from '@jini-ai/protocol';
import { defineJsonRoute, err, mountJsonRoute, ok, validationError, type AdapterContext, type Result, type RouteInputContext } from '@jini-ai/http-kit';

/** Matches OD's real `research/index.ts#searchResearch` query cap — see module doc. */
const MAX_QUERY_LENGTH = 1000;

export interface ResearchSource {
  readonly title: string;
  readonly url: string;
  readonly snippet: string;
  readonly publishedAt?: string;
  readonly provider: string;
}

/** Matches OD's real `@open-design/contracts/api/research.ts` `ResearchFindings` shape — see module doc. */
export interface ResearchSearchResponse {
  readonly query: string;
  readonly summary: string;
  readonly sources: readonly ResearchSource[];
  readonly provider: string;
  readonly depth: 'shallow';
  readonly fetchedAt: number;
}

export interface ResearchInternalErrorContext {
  readonly correlationId: string;
  readonly error: unknown;
}

export interface ResearchProviderCredentials {
  readonly apiKey?: string;
  readonly baseUrl?: string;
  readonly model?: string;
}

/** Research transport contract: the route owns validation/HTTP errors; adapters own vendor I/O. */
export interface ResearchProvider {
  readonly id: string;
  search(required: { apiKey: string; credentials: ResearchProviderCredentials; request: ResearchSearchRequest }, optional: Record<string, never>): Promise<{ readonly answer: string; readonly sources: readonly ResearchSource[] }>;
}

export interface ResearchHttpDeps {
  readonly provider?: ResearchProvider;
  readonly fetch?: typeof globalThis.fetch;
  readonly env?: Readonly<Record<string, string | undefined>>;
  /** Resolves per-provider credentials. Defaults to `TAVILY_API_KEY` for the built-in Tavily transport. */
  readonly resolveCredentials?: ({ providerId }: { providerId: string }) => Promise<ResearchProviderCredentials>;
  /** Host-owned sink for the real exception behind a generic `INTERNAL_ERROR` response (SEC-005). Defaults to `console.error`. */
  readonly onInternalError?: (context: ResearchInternalErrorContext) => void;
}

function defaultInternalErrorSink(context: ResearchInternalErrorContext): void {
  // eslint-disable-next-line no-console
  console.error(`[@jini-ai/http-kit] internal error (research/search, correlationId=${context.correlationId})`, redactSecrets({ input: inspect(context.error) }, { redactPii: false }));
}

/**
 * Default `ResearchHttpDeps.resolveCredentials`: reads `TAVILY_API_KEY` from the environment.
 *
 * Takes no `providerId` even though the `resolveCredentials` dep type supplies one (a function of
 * fewer parameters is assignable, so this still satisfies the interface). It used to accept one and
 * return `{}` for anything other than `'tavily'`, but that arm was unreachable twice over: the only
 * call site below passes the literal `'tavily'`, and `validateRequestedProvider` already rejects any
 * other provider name at parse time. A host that supports a second provider injects its own
 * `resolveCredentials` rather than reaching this function with a different id.
 */
async function defaultResolveCredentials({ env }: { env: Readonly<Record<string, string | undefined>> }): Promise<ResearchProviderCredentials> {
  const apiKey = env.TAVILY_API_KEY?.trim();
  return apiKey ? { apiKey } : {};
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function nonEmptyString(value: unknown): string | null {
  return typeof value === 'string' && value.trim().length > 0 ? value : null;
}

export interface ResearchSearchRequest {
  readonly query: string;
  readonly maxSources?: number;
}

/**
 * Only `'tavily'` is a supported provider (matches OD's real Phase-1 `searchResearch` — see module
 * doc). OD only inspects `providers[0]` and treats a non-array `providers` value as absent rather
 * than rejecting it; this mirrors both.
 */
function validateRequestedProvider(rawProviders: unknown, providerId: string): Result<null> {
  if (!Array.isArray(rawProviders)) return ok({ value: null });
  const filtered = rawProviders.filter((p): p is string => typeof p === 'string' && p.length > 0);
  const requested = filtered[0];
  if (requested !== undefined && requested !== providerId) {
    return err({ error: validationError({ message: `provider "${requested}" is not supported — only "${providerId}" is available` }) });
  }
  return ok({ value: null });
}

function parseResearchSearch(input: RouteInputContext, providerId: string): Result<ResearchSearchRequest> {
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });
  const rawQuery = nonEmptyString(input.body.query);
  if (!rawQuery) return err({ error: validationError({ message: 'query must be a non-empty string' }, { issues: [{ path: 'query', message: 'required non-empty string' }] }) });
  const query = rawQuery.trim().slice(0, MAX_QUERY_LENGTH);
  const maxSources = input.body.maxSources;
  if (maxSources !== undefined && (typeof maxSources !== 'number' || !Number.isFinite(maxSources) || maxSources <= 0)) {
    return err({ error: validationError({ message: 'maxSources must be a positive number when provided' }) });
  }
  const providerCheck = validateRequestedProvider(input.body.providers, providerId);
  if (!providerCheck.ok) return providerCheck;
  return ok({ value: { query, ...(maxSources !== undefined ? { maxSources: maxSources as number } : {}) } });
}

/** Ported verbatim from OD's real `research/index.ts#synthesizeFallbackSummary` — see module doc. Used when Tavily returns no `answer` text so the caller still gets a usable `summary`. */
function synthesizeFallbackSummary(sources: readonly ResearchSource[]): string {
  const lead = sources
    .slice(0, 5)
    .map((s, i) => `- [${i + 1}] ${s.title}: ${s.snippet.slice(0, 200)}`)
    .join('\n');
  return `(No provider summary; top snippets follow.)\n${lead}`;
}

/** The route-bound provider, else the host's `deps.provider`, else the built-in Tavily transport over `deps.fetch`. */
function selectProvider(bound: ResearchProvider | undefined, deps: ResearchHttpDeps): ResearchProvider {
  return bound ?? deps.provider ?? createTavilyResearchProvider({}, deps.fetch ? { fetch: deps.fetch } : {});
}

/** The host's resolver, else `TAVILY_API_KEY` for a `'tavily'` provider and no credentials for any other. */
function credentialResolver(provider: ResearchProvider, deps: ResearchHttpDeps): NonNullable<ResearchHttpDeps['resolveCredentials']> {
  return deps.resolveCredentials ?? (() => provider.id === 'tavily' ? defaultResolveCredentials({ env: deps.env ?? process.env }) : Promise.resolve({}));
}

/** Reports `error` to the host sink under a fresh correlation id and returns the generic SEC-005 public error. */
function reportInternalError(deps: ResearchHttpDeps, error: unknown): ReturnType<typeof createApiError> {
  const correlationId = randomUUID();
  (deps.onInternalError ?? defaultInternalErrorSink)({ correlationId, error });
  return createApiError({ code: 'INTERNAL_ERROR', message: 'an internal error occurred' }, { requestId: correlationId });
}

/** A copy of a provider failure with `apiKey` redacted from its message, name and stack, safe for the error sink. */
function redactProviderError(error: unknown, apiKey: string): Error {
  const redact = (input: string): string => redactSecrets({ input }, { exactSecrets: [apiKey] });
  const safeError = new Error(redact(error instanceof Error ? error.message : String(error)));
  if (error instanceof Error) {
    safeError.name = redact(error.name);
    if (error.stack === undefined) delete safeError.stack;
    else safeError.stack = redact(error.stack);
  }
  return safeError;
}

/** Builds one route over a host-selected provider, preserving the default Tavily validation contract. */
export function createResearchSearchRoute({ provider }: { provider?: ResearchProvider }, _optional: Record<string, never> = {}) {
  const providerId = provider?.id ?? 'tavily';
  return defineJsonRoute<ResearchSearchRequest, ResearchSearchResponse, ResearchHttpDeps>({
    method: 'post', path: '/api/research/search', parse: (input) => parseResearchSearch(input, providerId), handle: async ({ input: request, deps }) => {
      const selectedProvider = selectProvider(provider, deps);

      let credentials: ResearchProviderCredentials;
      try {
        credentials = await credentialResolver(selectedProvider, deps)({ providerId: selectedProvider.id });
      } catch (error) {
        return err({ error: reportInternalError(deps, error) });
      }

      const apiKey = credentials.apiKey;
      if (!apiKey) {
        return err({ error: createApiError({ code: 'NOT_CONFIGURED', message: `${selectedProvider.id} provider not configured` }) });
      }

      try {
        const raw = await selectedProvider.search({ apiKey, credentials, request }, {});
        // Matches OD's real `NO_RESEARCH_SOURCES` (404) — see module doc. Zero usable sources is a
        // failure, not an empty success, even when the upstream Tavily call itself succeeded.
        if (raw.sources.length === 0) {
          return err({ error: createApiError({ code: 'NOT_FOUND', message: 'no sources found' }) });
        }
        const result: ResearchSearchResponse = {
          query: request.query,
          summary: raw.answer || synthesizeFallbackSummary(raw.sources),
          sources: raw.sources,
          provider: selectedProvider.id,
          depth: 'shallow',
          fetchedAt: Date.now(),
        };
        return ok({ value: result });
      } catch (error) {
        // A host provider can throw transport text too; keep its configured key out of the sink.
        return err({ error: reportInternalError(deps, redactProviderError(error, apiKey)) });
      }
    }
  }, { requireSameOrigin: true });
}

export const researchSearchRoute = createResearchSearchRoute({});

/** Mounts `POST /api/research/search` on `app`. A pack's `http(app, services)` calls this directly. */
export function registerResearchRoutes({ app, deps, adapter }: { readonly app: Express; readonly deps: ResearchHttpDeps; readonly adapter: AdapterContext }, _optional: Record<string, never> = {}): void {
  mountJsonRoute({ app, spec: deps.provider ? createResearchSearchRoute({ provider: deps.provider }) : researchSearchRoute, deps, adapter });
}

import type { RequestHandler } from 'express';

/** Structural result of the daemon's transport-independent credential/ownership policies. */
export type RunAccessDecision =
  | { readonly allowed: true; readonly principalHeader?: { readonly name: string; readonly value: string } }
  | { readonly allowed: false; readonly status: 400 | 401 | 403 | 404 | 503; readonly body: unknown };

export interface DaemonAuthRequired {
  readonly authorizationHeaderName: string;
  /** Bind the daemon policy's environment, crypto, route and credential ports at composition. */
  readonly authorize: (required: {
    request: { method: string; path: string; headers: Readonly<Record<string, string | undefined>>; body?: unknown };
  }, optional: { validateDelegatedRunId: boolean }) => RunAccessDecision;
}

/** Mount before JSON parsing, then again on delegated calls after parsing with body validation.
 * Only the allowed policy result may replace the principal header; trusted proxy headers remain intact.
 * Policy exceptions go to Express's error boundary. No request body is accessed in the first gate.
 * @complexity O(1) adapter work, excluding the injected authorization policy.
 */
export function createDaemonAuthMiddleware(
  { authorize, authorizationHeaderName }: DaemonAuthRequired,
  { validateDelegatedRunId = false }: { validateDelegatedRunId?: boolean } = {},
): RequestHandler {
  return (req, res, next) => {
    try {
      const decision = authorize({ request: {
        method: req.method, path: req.path,
        headers: { [authorizationHeaderName]: req.get(authorizationHeaderName) },
        ...(validateDelegatedRunId ? { body: req.body } : {}),
      } }, { validateDelegatedRunId });
      if (!decision.allowed) { res.status(decision.status).json(decision.body); return; }
      if (decision.principalHeader) req.headers[decision.principalHeader.name.toLowerCase()] = decision.principalHeader.value;
      next();
    } catch (error) { next(error); }
  };
}

export interface RunOwnershipRequired {
  readonly principalHeaderName: string;
  readonly isEventStream: (required: { path: string }) => boolean;
  /** Bind authorizeRunOwnership's registry, run lookup and header policy at composition. */
  readonly authorize: (required: { runId: string | undefined; principalId: string | undefined; eventStream: boolean }) => Promise<RunAccessDecision>;
}

/** Mount after authentication on routes with a runId parameter. Denial envelopes pass through intact.
 * @complexity O(1) adapter work plus the injected ownership lookup; no storage or identity defaults.
 */
export function createRunOwnershipMiddleware({ authorize, principalHeaderName, isEventStream }: RunOwnershipRequired, _optional: Record<string, never> = {}): RequestHandler {
  return async (req, res, next) => {
    try {
      const decision = await authorize({ runId: req.params.runId || undefined, principalId: req.get(principalHeaderName) || undefined, eventStream: isEventStream({ path: req.path }) });
      if (!decision.allowed) { res.status(decision.status).json(decision.body); return; }
      next();
    } catch (error) { next(error); }
  };
}

export interface OwnedRunListRequired<Run> {
  readonly principalHeaderName: string;
  readonly listRuns: (required: Record<string, never>, optional: { contextRef?: string }) => Promise<readonly Run[]>;
  /** Bind listOwnedRuns's registry and principal-header policy at composition. */
  readonly filterOwnedRuns: (required: { runs: readonly Run[]; principalId: string | undefined }) =>
    { allowed: true; runs: Run[] } | Extract<RunAccessDecision, { allowed: false }>;
}

/** List only the authenticated principal's runs, after the host's context filter.
 * Missing principals receive the existing 401 envelope before the list port is called.
 * @complexity O(n) policy filtering for n listed runs; O(1) adapter space excluding results.
 */
export function createOwnedRunListHandler<Run>({ listRuns, filterOwnedRuns, principalHeaderName }: OwnedRunListRequired<Run>, _optional: Record<string, never> = {}): RequestHandler {
  return async (req, res, next) => {
    try {
      const principalId = req.get(principalHeaderName) || undefined;
      if (!principalId) { res.status(401).json({ error: { code: 'UNAUTHENTICATED', message: `${principalHeaderName} is required on run-scoped requests` } }); return; }
      const contextRef = typeof req.query.contextRef === 'string' ? req.query.contextRef : undefined;
      const runs = await listRuns({}, contextRef === undefined ? {} : { contextRef });
      const decision = filterOwnedRuns({ runs, principalId });
      if (!decision.allowed) { res.status(decision.status).json(decision.body); return; }
      res.json({ runs: decision.runs });
    } catch (error) { next(error); }
  };
}

/**
 * Generic HTTP/SSE projection of the kernel RunLifecycle. The routes own no
 * agent, tool, or product vocabulary: a host optionally supplies `onStarted`
 * to attach its chosen driver after the lifecycle has durably recorded start.
 */
import { inspect } from 'node:util';
import { redactSecrets } from '@jini-ai/core';
import { randomUUID } from 'node:crypto';
import type { Express, Request, Response } from 'express';
import { createApiError, type RunProtocolEvent, type RunStatus } from '@jini-ai/protocol';
import type { RunLifecycle, StartRunInput, Unsubscribe, UserMessageDelivery } from '../index.js';
import {
  createSseChannel,
  defineJsonRoute,
  err,
  mountJsonRoute,
  ok,
  requestedAfterCursor,
  sendApiError,
  sendRawApiError,
  validationError,
  type AdapterContext,
  type Result,
  type RouteInputContext,
} from '@jini-ai/http-kit';
import type { ServerResponse } from 'node:http';

/**
 * Diagnostic detail for an internal-error response the public API deliberately does not
 * disclose (SEC-005): spawn/storage/adapter failures can embed executable paths, working
 * directories, hostnames, or third-party provider text. The correlation id is the only thing
 * that crosses the boundary; the real `error` goes only to this host-owned sink so an operator
 * can still find and act on it.
 */
export interface RunInternalErrorContext {
  readonly source: 'run-start' | 'run-stream';
  readonly runId: string;
  readonly correlationId: string;
  readonly error: unknown;
}

/** Default sink when a host does not supply `onInternalError`: still observable, never silent. */
function defaultInternalErrorSink(context: RunInternalErrorContext): void {
  // eslint-disable-next-line no-console
  console.error(`[@jini-ai/http-kit] internal error (${context.source}, correlationId=${context.correlationId})`, redactSecrets({ input: inspect(context.error) }, { redactPii: false }));
}

export interface RunCreateRequest {
  readonly contextRef: string;
  readonly agentId?: string;
  readonly idempotencyKey?: string;
}

export interface RunStartContext {
  readonly request: RunCreateRequest;
  readonly run: RunStatus;
  /** The lifecycle this driver must use for emitted events, cancellation observation, and terminal completion. */
  readonly lifecycle: RunLifecycle;
}

/** Host-owned execution hook. It attaches a driver only after a durable run has been created. */
export type RunStartHandler = (context: RunStartContext) => Promise<void> | void;

export interface RunHttpDeps {
  readonly lifecycle: RunLifecycle;
  readonly onStarted?: RunStartHandler;
  /** Host-owned sink for the real exception behind a generic `INTERNAL_ERROR` response (SEC-005). Defaults to `console.error`. */
  readonly onInternalError?: (context: RunInternalErrorContext) => void;
  /**
   * Delivers a message the human sent mid-run into that run's live agent — a host passes its
   * `AgentExecutor.sendUserMessage`. Omitted, every such message reports `'unsupported'`, so the
   * client falls back to interrupting the run and sending the text as the next turn. Attachment
   * turns use the explicit hook below, or report unsupported without sending anything.
   */
  readonly deliverUserMessage?: (input: RunMessageRequest) => UserMessageDelivery | Promise<UserMessageDelivery>;
  /** Explicit opt-in: legacy text-only hosts must never acknowledge a turn while discarding its files. */
  readonly deliverUserMessageWithAttachments?: (input: RunMessageRequest) => UserMessageDelivery | Promise<UserMessageDelivery>;
}

/**
 * Logs the real failure server-side and returns a stage-specific, correlation-id-bearing public error
 * (SEC-005: never the raw exception). `runId` is mandatory — both real call sites (`run-start`,
 * after a durably-created run's id is already known; `run-stream`, against an already-parsed path
 * parameter) always have one in hand, so an optional field with an unreachable "no runId" branch
 * was speculative flexibility no caller ever exercised.
 * @complexity O(1) time and space besides the injected diagnostic sink.
 */
function reportInternalError(
  deps: RunHttpDeps,
  source: RunInternalErrorContext['source'],
  error: unknown,
  runId: string,
): ReturnType<typeof createApiError> {
  const correlationId = randomUUID();
  const sink = deps.onInternalError ?? defaultInternalErrorSink;
  sink({ source, runId, correlationId, error });
  const message = source === 'run-start'
    ? 'The agent could not be started. Check the run status before starting another task. Copy the request ID and report this problem.'
    : 'The connection to run updates could not be opened. Check the run status before starting another task. Copy the request ID and report this problem.';
  return createApiError({ code: 'INTERNAL_ERROR', message }, { requestId: correlationId });
}

export interface RunStartResponse {
  readonly run: RunStatus;
  readonly started: boolean;
}

export interface RunStatusResponse {
  readonly run: RunStatus;
}

export interface RunCancelResponse {
  readonly run: RunStatus;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function optionalString(body: Record<string, unknown>, key: string): string | undefined | null {
  const value = body[key];
  if (value === undefined) return undefined;
  return typeof value === 'string' && value.trim().length > 0 ? value : null;
}

function parseRunCreate(input: RouteInputContext): Result<RunCreateRequest> {
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });
  const contextRef = optionalString(input.body, 'contextRef');
  if (contextRef === undefined || contextRef === null) {
    return err({ error: validationError({ message: 'contextRef must be a non-empty string' }, { issues: [{ path: 'contextRef', message: 'required non-empty string' }] }) });
  }
  const agentId = optionalString(input.body, 'agentId');
  const idempotencyKey = optionalString(input.body, 'idempotencyKey');
  if (agentId === null || idempotencyKey === null) {
    return err({ error: validationError({ message: 'optional string fields must be non-empty when provided' }) });
  }
  return ok({
    value: {
      contextRef,
      ...(agentId === undefined ? {} : { agentId }),
      ...(idempotencyKey === undefined ? {} : { idempotencyKey }),
    }
  });
}

export interface RunMessageRequest {
  /** Generated at intake and passed unchanged to the executor's queue/consumption events. */
  readonly id?: string;
  readonly runId: string;
  readonly text: string;
  /** Opaque upload capabilities; the host must authorize and prepare every ref before delivery. */
  readonly attachmentIds?: readonly string[];
}

export interface RunMessageResponse {
  readonly id: string;
  readonly delivery: 'delivered';
}

/** Ceiling on one mid-run message, matching what a person can reasonably type or paste into a composer. */
export const RUN_MESSAGE_MAX_CHARS = 100_000;

/** Most attachment refs one mid-run message may carry. */
const MAX_ATTACHMENTS_PER_MESSAGE = 10;

/** An opaque upload capability: `attachment:` then 1-128 word characters or dashes, nothing path-shaped. */
function isAttachmentRef(ref: unknown): ref is string {
  return typeof ref === 'string' && /^attachment:[\w-]{1,128}$/u.test(ref);
}

/** `attachmentIds` is optional; when present it must be an array of at most ten well-formed refs, or the whole message is refused. */
function parseAttachmentIds(value: unknown): Result<readonly string[] | undefined> {
  if (value === undefined) return ok({ value: undefined });
  if (Array.isArray(value) && value.length <= MAX_ATTACHMENTS_PER_MESSAGE && value.every(isAttachmentRef)) return ok({ value });
  return err({ error: validationError({ message: 'attachmentIds must contain at most 10 opaque attachment refs' }) });
}

function parseRunMessage(input: RouteInputContext): Result<RunMessageRequest> {
  const parsedRunId = parseRunId(input);
  if (!parsedRunId.ok) return parsedRunId;
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });
  const text = optionalString(input.body, 'text');
  if (text === undefined || text === null) {
    return err({ error: validationError({ message: 'text must be a non-empty string' }, { issues: [{ path: 'text', message: 'required non-empty string' }] }) });
  }
  if (text.length > RUN_MESSAGE_MAX_CHARS) {
    return err({ error: validationError({ message: `text must be at most ${RUN_MESSAGE_MAX_CHARS} characters` }, { issues: [{ path: 'text', message: 'too long' }] }) });
  }
  const attachmentIds = parseAttachmentIds(input.body.attachmentIds);
  if (!attachmentIds.ok) return attachmentIds;
  return ok({ value: { runId: parsedRunId.value, text, ...(attachmentIds.value === undefined ? {} : { attachmentIds: attachmentIds.value }) } });
}

export interface RunListResponse {
  readonly runs: readonly RunStatus[];
}

function parseRunList(input: RouteInputContext): Result<{ contextRef?: string }> {
  const value = input.query.contextRef;
  if (value === undefined) return ok({ value: {} });
  if (typeof value !== 'string' || value.length === 0) {
    return err({ error: validationError({ message: 'contextRef must be a non-empty string when provided' }, { issues: [{ path: 'contextRef', message: 'non-empty string when provided' }] }) });
  }
  return ok({ value: { contextRef: value } });
}

function parseRunId(input: RouteInputContext): Result<string> {
  const runId = input.params.runId;
  return typeof runId === 'string' && runId.length > 0
    ? ok({ value: runId })
    : err({ error: validationError({ message: 'runId must be a non-empty path parameter' }) });
}

function parseRunCancel(input: RouteInputContext): Result<{ runId: string; reason?: string }> {
  const parsedRunId = parseRunId(input);
  if (!parsedRunId.ok) return parsedRunId;
  if (input.body === undefined || input.body === null) return ok({ value: { runId: parsedRunId.value } });
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object when provided' }) });
  const reason = optionalString(input.body, 'reason');
  if (reason === null) return err({ error: validationError({ message: 'reason must be a non-empty string when provided' }) });
  return ok({ value: { runId: parsedRunId.value, ...(reason === undefined ? {} : { reason }) } });
}

export const runStartRoute = defineJsonRoute<RunCreateRequest, RunStartResponse, RunHttpDeps>({
  method: 'post', path: '/api/runs', parse: parseRunCreate, handle: async ({ input, deps }) => {
    const startInput: StartRunInput = input;
    const started = await deps.lifecycle.start({ contextRef: startInput.contextRef }, { ...startInput });
    if (started.started && deps.onStarted) {
      try {
        await deps.onStarted({ request: input, run: started.run, lifecycle: deps.lifecycle });
      } catch (error) {
        await deps.lifecycle.finish({ runId: started.run.id, status: 'failed', code: null, signal: null, resumable: false });
        return err({ error: reportInternalError(deps, 'run-start', error, started.run.id) });
      }
    }
    // A host-owned driver may finish immediately (for example, a single-step
    // run). Return the lifecycle's current view rather than the snapshot
    // captured before invoking that driver.
    const run = (await deps.lifecycle.get({ runId: started.run.id })) ?? started.run;
    return ok({ value: { run, started: started.started } });
  }
}, { requireSameOrigin: true, successStatus: 201 });

/** `GET /api/runs` — lists runs, optionally scoped to a `contextRef` query parameter. */
export const runListRoute = defineJsonRoute<{ contextRef?: string }, RunListResponse, RunHttpDeps>({ method: 'get', path: '/api/runs', parse: parseRunList, handle: async ({ input, deps }) => ok({ value: { runs: await deps.lifecycle.list({}, input.contextRef === undefined ? {} : { contextRef: input.contextRef }) } }) });

export const runStatusRoute = defineJsonRoute<string, RunStatusResponse, RunHttpDeps>({
  method: 'get', path: '/api/runs/:runId', parse: parseRunId, handle: async ({ input: runId, deps }) => {
    const run = await deps.lifecycle.get({ runId });
    return run === undefined ? err({ error: createApiError({ code: 'NOT_FOUND', message: `run "${runId}" was not found` }) }) : ok({ value: { run } });
  }
});

export const runCancelRoute = defineJsonRoute<{ runId: string; reason?: string }, RunCancelResponse, RunHttpDeps>({
  method: 'post', path: '/api/runs/:runId/cancel', parse: parseRunCancel, handle: async ({ input, deps }) => {
    const run = await deps.lifecycle.get({ runId: input.runId });
    if (run === undefined) return err({ error: createApiError({ code: 'NOT_FOUND', message: `run "${input.runId}" was not found` }) });
    return ok({ value: { run: await deps.lifecycle.cancel(input) } });
  }
}, { requireSameOrigin: true });

/**
 * `POST /api/runs/:runId/messages` — a message the human sent while the run is going. `202` when it
 * reached the live agent; `409 CONFLICT` with `details.delivery` (`'unsupported'` or
 * `'not-running'`) when it did not, which tells the client to retain the next-turn queue without canceling live work.
 * Acceptance is distinct from the UUID-attributed consumption receipt in the run stream.
 */
export const runMessageRoute = defineJsonRoute<RunMessageRequest, RunMessageResponse, RunHttpDeps>({
  method: 'post', path: '/api/runs/:runId/messages', parse: parseRunMessage, handle: async ({ input, deps }) => {
    const run = await deps.lifecycle.get({ runId: input.runId });
    if (run === undefined) return err({ error: createApiError({ code: 'NOT_FOUND', message: `run "${input.runId}" was not found` }) });
    const deliver = input.attachmentIds?.length ? deps.deliverUserMessageWithAttachments : deps.deliverUserMessage;
    const id = randomUUID();
    const delivery = deliver ? await deliver({ ...input, id }) : 'unsupported';
    if (delivery === 'delivered') return ok({ value: { delivery, id } });
    return err({ error: createApiError({ code: 'CONFLICT', message: `run "${input.runId}" did not take the message` }, { details: { delivery } }) });
  }
}, { requireSameOrigin: true, successStatus: 202 });

function sendStreamFailure(res: ServerResponse, kind: Exclude<Awaited<ReturnType<RunLifecycle['stream']>>, { kind: 'ok' }>): void {
  if (kind.kind === 'unknown-run') {
    sendRawApiError({ res, status: 404, error: createApiError({ code: 'NOT_FOUND', message: 'run was not found' }) });
    return;
  }
  if (kind.kind === 'invalid-cursor') {
    sendRawApiError({ res, status: 400, error: createApiError({ code: 'BAD_REQUEST', message: `invalid replay cursor "${kind.requestedCursor}"` }) });
    return;
  }
  sendRawApiError({
    res, status: 409, error: createApiError({ code: 'CONFLICT', message: `replay gap after cursor "${kind.requestedCursor}"` }, {
      details: { oldestAvailableCursor: kind.oldestAvailableCursor },
    })
  }
  );
}

/**
 * The core of `GET /api/runs/:runId/events` — canonical events as SSE, with Last-Event-ID
 * reconnect support. Takes `runId`/`afterCursor` already resolved by the caller. `res` is typed
 * against the raw `node:http` `ServerResponse` rather than Express's own `Response` type — Express's
 * `Response` extends it directly, so this is a no-op widening, the same pattern `run-stream.ts`'s
 * AG-UI handler already established.
 */
export async function handleRunEventStreamRequest({ res, runId, afterCursor, deps }: { readonly res: ServerResponse; readonly runId: string; readonly afterCursor: string | null; readonly deps: RunHttpDeps }, _optional: Record<string, never> = {}
): Promise<void> {
  if (runId.length === 0) {
    sendRawApiError({ res, status: 400, error: createApiError({ code: 'BAD_REQUEST', message: 'runId must be a non-empty path parameter' }) });
    return;
  }

  // `createSseChannel` (`sse.ts`) owns the bounded queue, backpressure, and client-disconnect
  // handling that used to be inlined here — see that module's doc for the generalization.
  const channel = createSseChannel<RunProtocolEvent>({ res }, { isEndEvent: ({ event }) => event.kind === 'end' });

  let unsubscribeFn: Unsubscribe | null = null;
  channel.onClose({
    callback: () => {
      const stop = unsubscribeFn;
      unsubscribeFn = null;
      stop?.();
    }
  });

  try {
    const subscribed = await deps.lifecycle.stream({ runId, onEvent: (event) => {
      // RunLifecycle validates the run/cursor before replay callbacks. Open before enqueueing
      // history so a healthy response drains replay instead of overflowing the unopened queue.
      channel.open();
      channel.enqueue({ event });
    } }, { afterCursor });
    if (subscribed.kind !== 'ok') {
      // Nothing was ever subscribed, so `abandon()` has nothing to unsubscribe — it only marks
      // the channel closed. `res` itself is untouched, leaving `sendStreamFailure` free to send
      // a normal JSON error response instead of an SSE stream.
      channel.abandon();
      sendStreamFailure(res, subscribed);
      return;
    }
    if (channel.isClosed()) {
      // The client already disconnected (or the bounded queue already gave up) while
      // `stream()` was resolving — unsubscribe immediately instead of leaking it.
      subscribed.unsubscribe();
      return;
    }
    unsubscribeFn = subscribed.unsubscribe;
    channel.open();
  } catch (error) {
    if (!res.headersSent) {
      // `channel.open()` never ran (or never got past `flushHeaders`) — abandon without
      // touching `res`, so the JSON error response below is the only thing written.
      // Using `channel.end()` here instead would end the response before this write, turning
      // it into a write-after-end failure.
      channel.abandon();
      sendRawApiError({ res, status: 500, error: reportInternalError(deps, 'run-stream', error, runId) });
      return;
    }
    // Headers were already sent (the stream had started, or `open()` partially ran before
    // throwing) — end the stream itself rather than attempting a second, incompatible response.
    channel.end();
  }
}

/**
 * Path {@link registerRunEventStream} mounts. Exported as a constant so a caller that needs to know
 * this route exists — a reverse proxy's forward list, `route-manifest.ts` — references it rather than
 * restating the literal and later drifting from it.
 */
export const RUN_EVENTS_ROUTE_PATH = '/api/runs/:runId/events';

/** Express mounting glue for {@link handleRunEventStreamRequest} — resolves `runId`/`afterCursor` from an Express `Request` and hands the request straight through. */
export function registerRunEventStream({ app, deps }: { readonly app: Express; readonly deps: RunHttpDeps }, _optional: Record<string, never> = {}): void {
  app.get(RUN_EVENTS_ROUTE_PATH, async (req: Request, res: Response) => {
    const runId = req.params.runId;
    if (typeof runId !== 'string' || runId.length === 0) {
      sendApiError({ res, status: 400, error: createApiError({ code: 'BAD_REQUEST', message: 'runId must be a non-empty path parameter' }) });
      return;
    }
    await handleRunEventStreamRequest({ res, runId, afterCursor: requestedAfterCursor(req), deps });
  });
}

/** Mounts create/status/cancel/message JSON endpoints and the SSE event stream as one run transport. */
export function registerRunRoutes({ app, deps, adapter }: { readonly app: Express; readonly deps: RunHttpDeps; readonly adapter: AdapterContext }, _optional: Record<string, never> = {}): void {
  mountJsonRoute({ app, spec: runStartRoute, deps, adapter });
  mountJsonRoute({ app, spec: runListRoute, deps, adapter });
  mountJsonRoute({ app, spec: runStatusRoute, deps, adapter });
  mountJsonRoute({ app, spec: runCancelRoute, deps, adapter });
  mountJsonRoute({ app, spec: runMessageRoute, deps, adapter });
  registerRunEventStream({ app, deps });
}

/**
 * @module terminals
 *
 * Interactive-terminal HTTP surface, mirroring OD's
 * `apps/daemon/src/routes/terminal.ts` (`/api/projects/:id/terminals` +
 * `.../:tid/{stream,stdin,resize,kill}`) generalized under `/api/terminals`.
 * See `ADS-memory/reports/proposals/PROP-http-route-packs-terminal-pty-2026-07-21.md`
 * for the design discussion and `@jini-ai/daemon`'s `terminal-session.ts` module
 * doc for the session-ownership/gating decisions this route pack calls into.
 *
 * This file is deliberately thin — no PTY spawning, no session registry, no
 * ownership logic lives here (that is `@jini-ai/daemon`'s `TerminalSessionManager`,
 * injected as `deps.manager`). This package only:
 *
 * - Resolves a `POST /api/terminals` request's `resourceRef` to a spawn `cwd`
 *   via `workspace-root.ts` (the same port `host-tools.ts`'s open-in route
 *   uses), then routes creation through `deps.toolExecutor.execute(...,
 *   'terminal.create', ...)` — the one call `@jini-ai/daemon`'s module gates by
 *   policy (matching `db-ops.ts`'s tool-execution-boundary precedent).
 * - Routes `stdin`/`resize`/`kill`/`stream` directly to `deps.manager`'s
 *   lighter, session-ownership-checked methods — deliberately **not** through
 *   `ToolExecutor` again (see the daemon module's doc for why a full
 *   authorize/confirm round-trip per keystroke would make a terminal
 *   unusable).
 * - Adapts `deps.manager.attach`'s push/end sink to `sse.ts`'s generic SSE
 *   channel, the same way `runs.ts` adapts `RunLifecycle.stream`.
 */
import { inspect } from 'node:util';
import { redactSecrets } from '@jini-ai/core';
import { randomUUID } from 'node:crypto';
import type { Express, Request, Response } from 'express';
import type { Principal } from '@jini-ai/core';
import type {
  TerminalSessionActionResult,
  TerminalSessionInfo,
  TerminalSessionManager,
  TerminalSseSink,
} from '../index.js';
import { TERMINAL_CREATE_TOOL_ID } from '../index.js';
import type { ToolExecutionResult, ToolExecutor } from '../index.js';
import { createApiError } from '@jini-ai/protocol';
import { defineJsonRoute, mountJsonRoute, type AdapterContext } from '@jini-ai/http-kit';
import { guardSameOrigin } from '@jini-ai/http-kit';
import { validationError } from '@jini-ai/http-kit';
import { sendApiError, statusForError } from '@jini-ai/http-kit';
import { createSseChannel, requestedAfterCursor, type SseEvent } from '@jini-ai/http-kit';
import { denyAllWorkspaceRoots, type WorkspaceRootResolver } from './workspace-root.js';
import { isRecord, readOptionalNonEmptyString, readOptionalNumber, resolveResourceRoot, withoutUndefined } from './resource-request.js';
import { err, ok, type Result, type RouteInputContext } from '@jini-ai/http-kit';

/** Diagnostic detail for an internal-error response the public API deliberately does not disclose (SEC-005, matching `runs.ts`/`db-ops.ts`): a spawn failure (e.g. a missing/uncompiled native addon) can embed executable paths or host detail. */
export interface TerminalsInternalErrorContext {
  readonly source: 'terminal-create';
  readonly correlationId: string;
  readonly error: unknown;
}

function defaultTerminalsInternalErrorSink(context: TerminalsInternalErrorContext): void {
  // eslint-disable-next-line no-console
  console.error(`[@jini-ai/http-kit] internal error (${context.source}, correlationId=${context.correlationId})`, redactSecrets({ input: inspect(context.error) }, { redactPii: false }));
}

/** Everything this route pack needs from the host. */
export interface TerminalsHttpDeps {
  readonly manager: TerminalSessionManager;
  readonly toolExecutor: ToolExecutor;
  /** The identity these routes act as — same fixed, host-supplied-value shape as `db-ops.ts`'s `DaemonDbHttpDeps.principal` (this transport has no session/identity subsystem of its own). */
  readonly principal: Principal;
  /** Resolves a `resourceRef` to a spawn working directory. Defaults to {@link denyAllWorkspaceRoots} — a host that never wires a real resolver gets a 404 on every create call, never a guessed path (see `workspace-root.ts`). */
  readonly resolveRoot?: WorkspaceRootResolver;
  /** Host-owned sink for the real exception behind a generic `INTERNAL_ERROR` response (SEC-005). Defaults to `console.error`. */
  readonly onInternalError?: (context: TerminalsInternalErrorContext) => void;
}

/** Every one-off `terminal.create` tool call gets its own opaque `RunRef` — matching `db-ops.ts`'s `freshRun()`: these are single requests, not steps of a longer-lived agent run. */
function freshRun(): { readonly id: string } {
  return { id: randomUUID() };
}

function toolResultToApiResult(deps: TerminalsHttpDeps, result: ToolExecutionResult): Result<TerminalSessionInfo> {
  switch (result.status) {
    case 'completed':
      return ok({ value: result.output as TerminalSessionInfo });
    case 'denied':
      return err({ error: createApiError({ code: 'TOOL_OPERATION_DENIED', message: 'this operation was denied by policy' }) });
    case 'confirmation-denied':
      return err({ error: createApiError({ code: 'TOOL_OPERATION_DENIED', message: 'this operation was denied during confirmation' }) });
    case 'timed-out':
    case 'cancelled':
    case 'failed': {
      const correlationId = randomUUID();
      const sink = deps.onInternalError ?? defaultTerminalsInternalErrorSink;
      sink({ source: 'terminal-create', correlationId, error: result.status === 'failed' ? result.error : result.status });
      return err({ error: createApiError({ code: 'INTERNAL_ERROR', message: 'an internal error occurred' }, { requestId: correlationId }) });
    }
    default: {
      // Unreachable: every tool result status has a case above, and a new one fails typecheck here.
      const unhandled: never = result.status;
      throw new TypeError(`Unhandled tool result status: ${String(unhandled)}`);
    }
  }
}

export interface TerminalCreateRequest {
  readonly resourceRef: string;
  readonly detail?: string;
  readonly cols?: number;
  readonly rows?: number;
  readonly shell?: string;
}

function parseTerminalCreate(input: RouteInputContext): Result<TerminalCreateRequest> {
  const body = input.body;
  if (!isRecord(body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });
  const resourceRef = body.resourceRef;
  if (typeof resourceRef !== 'string' || resourceRef.length === 0) {
    return err({ error: validationError({ message: 'resourceRef is required' }, { issues: [{ path: 'resourceRef', message: 'required non-empty string' }] }) });
  }
  // Checked in this fixed order: the first invalid field is the one reported.
  const detail = readOptionalNonEmptyString({ body, field: 'detail' });
  if (!detail.ok) return detail;
  const cols = readOptionalNumber({ body, field: 'cols' });
  if (!cols.ok) return cols;
  const rows = readOptionalNumber({ body, field: 'rows' });
  if (!rows.ok) return rows;
  const shell = readOptionalNonEmptyString({ body, field: 'shell' });
  if (!shell.ok) return shell;
  return ok({ value: { resourceRef, ...withoutUndefined({ detail: detail.value, cols: cols.value, rows: rows.value, shell: shell.value }) } });
}

/**
 * `POST /api/terminals` — the one gated call (see module doc). Resolves
 * `resourceRef` to a working directory the same way `host-tools.ts`'s
 * open-in route does, then authorizes+spawns the session through
 * `ToolExecutor.execute(..., 'terminal.create', ...)`.
 */
export const terminalCreateRoute = defineJsonRoute<TerminalCreateRequest, TerminalSessionInfo, TerminalsHttpDeps>({
  method: 'post', path: '/api/terminals', parse: parseTerminalCreate, handle: async ({ input, deps }) => {
    const root = await resolveResourceRoot({ resourceRef: input.resourceRef, detail: input.detail }, { resolver: deps.resolveRoot ?? denyAllWorkspaceRoots });
    if (!root.ok) return root;
    const toolInput = { resourceRef: input.resourceRef, cwd: root.value, ...withoutUndefined({ cols: input.cols, rows: input.rows, shell: input.shell }) };
    const result = await deps.toolExecutor.execute({ principal: deps.principal, run: freshRun(), toolId: TERMINAL_CREATE_TOOL_ID, input: toolInput });
    return toolResultToApiResult(deps, result);
  }
}, { requireSameOrigin: true, successStatus: 201 });

export interface TerminalListResponse {
  readonly terminals: readonly TerminalSessionInfo[];
}

function parseTerminalList(input: RouteInputContext): Result<{ resourceRef?: string }> {
  const value = input.query.resourceRef;
  if (value === undefined) return ok({ value: {} });
  if (typeof value !== 'string' || value.length === 0) {
    return err({ error: validationError({ message: 'resourceRef must be a non-empty string when provided' }) });
  }
  return ok({ value: { resourceRef: value } });
}

/** `GET /api/terminals` — sessions the calling principal owns, optionally narrowed by `resourceRef`. Never gated through `ToolExecutor` — a read scoped to the caller's own sessions, matching `runs.ts`'s `runListRoute` precedent. */
export const terminalListRoute = defineJsonRoute<{ resourceRef?: string }, TerminalListResponse, TerminalsHttpDeps>({
  method: 'get', path: '/api/terminals', parse: parseTerminalList, handle: ({ input, deps }) =>
    ok({ value: { terminals: deps.manager.list({ principal: deps.principal }, { filter: input.resourceRef === undefined ? {} : { resourceRef: input.resourceRef } }) } })
});

function parseTerminalId(input: RouteInputContext): Result<string> {
  const id = input.params.id;
  return typeof id === 'string' && id.length > 0 ? ok({ value: id }) : err({ error: validationError({ message: 'id must be a non-empty path parameter' }) });
}

export interface TerminalActionResponse {
  readonly ok: boolean;
  readonly terminal?: TerminalSessionInfo;
}

/**
 * Exported (not just internal) so the `result.session === null` branch — a real race
 * (`write`/`resize`/`kill` finding metadata for an id whose underlying session was concurrently
 * killed between the ownership check and the critical section, per `@jini-ai/daemon`'s
 * `terminal-session.ts` `currentSnapshot`) — is directly unit-testable against a synthetic
 * `TerminalSessionActionResult` rather than requiring a real, hard-to-deterministically-force race
 * through the full `TerminalSessionManager`. Matches this file's own `createDeferredEndGate`
 * precedent for the same "extract into a directly-testable pure function" shape.
 */
export function actionResultToApiResult({ result, notFoundMessage }: { readonly result: TerminalSessionActionResult; readonly notFoundMessage: string }, _optional: Record<string, never> = {}): Result<TerminalActionResponse> {
  if (result.status === 'not-found') return err({ error: createApiError({ code: 'NOT_FOUND', message: notFoundMessage }) });
  return ok({ value: { ok: result.ok, ...(result.session ? { terminal: result.session } : {}) } });
}

function parseStdinInput(input: RouteInputContext): Result<{ id: string; data: string }> {
  const parsedId = parseTerminalId(input);
  if (!parsedId.ok) return parsedId;
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });
  const data = input.body.data;
  if (typeof data !== 'string') {
    return err({ error: validationError({ message: 'data (string) is required' }, { issues: [{ path: 'data', message: 'required string' }] }) });
  }
  return ok({ value: { id: parsedId.value, data } });
}

/** `POST /api/terminals/:id/stdin` — writes `data` to the session's pty. Ownership-checked by `deps.manager.write` directly, not re-gated through `ToolExecutor` (see module doc). */
export const terminalStdinRoute = defineJsonRoute<{ id: string; data: string }, TerminalActionResponse, TerminalsHttpDeps>({
  method: 'post', path: '/api/terminals/:id/stdin', parse: parseStdinInput, handle: async ({ input, deps }) => {
    const result = await deps.manager.write({ principal: deps.principal, id: input.id, input: input.data });
    return actionResultToApiResult({ result, notFoundMessage: `terminal "${input.id}" was not found` });
  }
}, { requireSameOrigin: true });

function parseResizeInput(input: RouteInputContext): Result<{ id: string; cols: number; rows: number }> {
  const parsedId = parseTerminalId(input);
  if (!parsedId.ok) return parsedId;
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });
  const cols = Number(input.body.cols);
  const rows = Number(input.body.rows);
  if (!Number.isFinite(cols) || !Number.isFinite(rows)) {
    return err({ error: validationError({ message: 'cols and rows (numbers) are required' }) });
  }
  return ok({ value: { id: parsedId.value, cols, rows } });
}

/** `POST /api/terminals/:id/resize` — resizes the session's pty. */
export const terminalResizeRoute = defineJsonRoute<{ id: string; cols: number; rows: number }, TerminalActionResponse, TerminalsHttpDeps>({
  method: 'post', path: '/api/terminals/:id/resize', parse: parseResizeInput, handle: async ({ input, deps }) => {
    const result = await deps.manager.resize({ principal: deps.principal, id: input.id, cols: input.cols, rows: input.rows });
    return actionResultToApiResult({ result, notFoundMessage: `terminal "${input.id}" was not found` });
  }
}, { requireSameOrigin: true });

function handleKill(id: string, deps: TerminalsHttpDeps): Promise<Result<TerminalActionResponse>> {
  return deps.manager.kill({ principal: deps.principal, id }, { signal: 'SIGTERM' }).then((result) => actionResultToApiResult({ result, notFoundMessage: `terminal "${id}" was not found` }));
}

/** `POST /api/terminals/:id/kill` — sends `SIGTERM` to the session's pty. */
export const terminalKillRoute = defineJsonRoute<string, TerminalActionResponse, TerminalsHttpDeps>({ method: 'post', path: '/api/terminals/:id/kill', parse: parseTerminalId, handle: ({ input: id, deps }) => handleKill(id, deps) }, { requireSameOrigin: true });

/** `DELETE /api/terminals/:id` — alias for `kill`, matching OD's dual `POST .../kill` / `DELETE` routes. */
export const terminalDeleteRoute = defineJsonRoute<string, TerminalActionResponse, TerminalsHttpDeps>({ method: 'delete', path: '/api/terminals/:id', parse: parseTerminalId, handle: ({ input: id, deps }) => handleKill(id, deps) }, { requireSameOrigin: true });

/** The wire shape `sse.ts`'s generic channel streams for a terminal — the underlying `@jini-ai/platform` event's `id`/`event`/`data` triple, reshaped to `SseEvent`'s `opaqueCursor`/`kind` naming. */
interface TerminalWireEvent extends SseEvent {
  readonly data: unknown;
}

/** The one method {@link createDeferredEndGate} needs from `sse.ts`'s channel — narrowed so the gate is unit-testable against a bare fake, not a real `SseChannel`. */
interface DeferredEndChannel {
  end(): void;
}

/**
 * The `channelOpened`/`endRequestedBeforeOpen` state machine `registerTerminalEventStream`'s
 * `TerminalSseSink.end()` needs, extracted into its own directly-testable unit — see that
 * function's inline comment for *why* the deferral exists (an already-exited session's replay
 * path can call `end()` before `open()` has ever run).
 *
 * **On the `markOpened()`-then-`end()` ordering (opened=true when `end()` runs):** this is the
 * ordering every *currently reachable* production call graph in this repo takes for a live
 * session that exits while already streaming — but it is unreachable through that graph, not
 * unreachable in principle. `@jini-ai/platform`'s `TerminalService.finish()` (`packages/platform/src/
 * terminal.ts`) calls `sink.send('exit', ...)` immediately before `sink.end()` for every live
 * client; `send()` here forwards straight to `channel.enqueue()`, whose `isEndEvent: (e) => e.kind
 * === 'exit'` match auto-closes the channel *synchronously inside that same `enqueue()` call* —
 * which synchronously runs `registerTerminalEventStream`'s own `channel.onClose` callback, which
 * detaches this sink from `TerminalService`'s `session.clients` before `finish()`'s own, separate
 * `sink.end()` loop ever runs. That loop iterates `session.clients` fresh at call time (not a
 * snapshot taken before `emit()`), so by the time it runs, this sink has already removed itself —
 * `sink.end()` is consequently never invoked while `channelOpened` is `true` via any call graph
 * this repo's own `@jini-ai/platform` + `@jini-ai/daemon/http` composition can currently produce (confirmed by
 * instrumenting the real call path directly, not inferred from reading the source — a synchronous
 * console probe in `end()` never fired across this file's full "live-exit-while-streaming" test).
 * That is a fact about today's specific `TerminalService`/`SseChannel` wiring, not a proof that no
 * future caller of `TerminalSseSink` could ever call `end()` post-open (a hypothetical non-SSE
 * sink, or a future `TerminalService` exit reason not preceded by a matching `send()`, would hit
 * exactly this branch) — so the branch stays as real, intentional defensive code, tested directly
 * here rather than deleted for being unreachable *today* or left silently uncovered.
 */
export function createDeferredEndGate({ channel }: { readonly channel: DeferredEndChannel }, _optional: Record<string, never> = {}): { markOpened(): void; end(): void } {
  let opened = false;
  let endRequestedBeforeOpen = false;
  return {
    markOpened(): void {
      opened = true;
      // Idempotent-safe even if the queued 'exit' event already auto-closed the channel via
      // `isEndEvent` during `open()`'s own drain (`channel.end()` is documented safe to call twice).
      if (endRequestedBeforeOpen) channel.end();
    },
    end(): void {
      if (opened) {
        channel.end();
      } else {
        endRequestedBeforeOpen = true;
      }
    },
  };
}

/**
 * `GET /api/terminals/:id/stream` — SSE, with `Last-Event-ID`/`afterCursor`
 * reconnect replay (via `sse.ts`'s `requestedAfterCursor`, the same helper
 * `runs.ts` uses). Adapts `deps.manager.attach`'s push/end
 * `TerminalSseSink` to `sse.ts`'s generic channel, mirroring
 * `registerRunEventStream`'s adaptation of `RunLifecycle.stream`.
 *
 * Bypasses `mountJsonRoute` (raw `app.get`, for the SSE response shape), so it does not get
 * `requireSameOrigin` for free the way the JSON routes above do — the guard is applied here
 * directly, before the SSE channel is opened, so a cross-origin request never gets a stream.
 */
export function registerTerminalEventStream({ app, deps, adapter }: { readonly app: Express; readonly deps: TerminalsHttpDeps; readonly adapter: AdapterContext }, _optional: Record<string, never> = {}): void {
  app.get('/api/terminals/:id/stream', (req: Request, res: Response) => {
    const origin = guardSameOrigin({ req, origin: adapter });
    if (!origin.ok) {
      sendApiError({ res, status: statusForError({ error: origin.error }), error: origin.error });
      return;
    }
    const id = req.params.id;
    if (typeof id !== 'string' || id.length === 0) {
      sendApiError({ res, status: 400, error: createApiError({ code: 'BAD_REQUEST', message: 'id must be a non-empty path parameter' }) });
      return;
    }
    const cursor = requestedAfterCursor(req);
    const lastEventId = cursor === null ? 0 : Number(cursor);

    const channel = createSseChannel<TerminalWireEvent>({ res }, { isEndEvent: ({ event }) => event.kind === 'exit' });

    // `deps.manager.attach` can call `sink.end()` synchronously, from inside the very call below
    // (an already-exited session's replay path) — before the channel has ever been `open()`ed. If
    // `end()` mapped straight to `channel.end()`, that would end the response with the queued
    // backlog never flushed (headers never even sent). `createDeferredEndGate` defers the actual
    // `channel.end()` call until after `open()` has drained whatever `send()` already queued — see
    // that function's own doc for the full reachability analysis of its other branch.
    const deferredEnd = createDeferredEndGate({ channel });
    const sink: TerminalSseSink = {
      send(event, data, eventId) {
        channel.enqueue({ event: { opaqueCursor: String(eventId), kind: event, data } });
      },
      end() {
        deferredEnd.end();
      },
    };

    let attachedSink: TerminalSseSink | null = null;
    channel.onClose({
      callback: () => {
        if (attachedSink) deps.manager.detach({ id, sink: attachedSink });
      }
    });

    const result = deps.manager.attach({ principal: deps.principal, id, lastEventId, sink });
    if (result === 'not-found') {
      channel.abandon();
      sendApiError({ res, status: 404, error: createApiError({ code: 'NOT_FOUND', message: `terminal "${id}" was not found` }) });
      return;
    }
    if (result === 'attached') {
      attachedSink = sink;
    }
    channel.open();
    deferredEnd.markOpened();
  });
}

/** Mounts every terminal route (`list`/`create`/`stdin`/`resize`/`kill`/`delete`/`stream`) on `app`. A pack's `http(app, services)` calls this directly. */
export function registerTerminalRoutes({ app, deps, adapter }: { readonly app: Express; readonly deps: TerminalsHttpDeps; readonly adapter: AdapterContext }, _optional: Record<string, never> = {}): void {
  mountJsonRoute({ app, spec: terminalListRoute, deps, adapter });
  mountJsonRoute({ app, spec: terminalCreateRoute, deps, adapter });
  mountJsonRoute({ app, spec: terminalStdinRoute, deps, adapter });
  mountJsonRoute({ app, spec: terminalResizeRoute, deps, adapter });
  mountJsonRoute({ app, spec: terminalKillRoute, deps, adapter });
  mountJsonRoute({ app, spec: terminalDeleteRoute, deps, adapter });
  registerTerminalEventStream({ app, deps, adapter });
}

/**
 * @module tool-execution-routes
 *
 * `POST /internal/tool-executions` and `GET /internal/tool-catalog` — the server end of
 * `createRemoteToolExecutor`. A host whose agent runtime runs in another local process mounts these
 * over its own gated `ToolExecutor`, so that process can run tools without loading them. The wire
 * protocol and the at-most-once rules are documented on `remote-tool-executor.ts`.
 *
 * Trust boundary, checked before any body byte is parsed:
 * - a dedicated per-boot secret read from `tokenEnvVar`, compared in constant time; unset → 503 (the
 *   route fails closed, there is no "open" mode), wrong or missing → 401;
 * - the TCP peer (`req.socket.remoteAddress`, never a forwarded header) must be loopback → else 403.
 * Only then does the route's own `express.json({ limit: maxBodyBytes })` run, so an unauthenticated
 * caller cannot make the host buffer a large body, and an app-level parser with a smaller limit
 * mounted after this route never sees these requests. Over the limit → 413.
 *
 * The executor below is the host's full gate (authorize, confirm, audit); this route adds no
 * authority of its own and the serialized principal is passed through untouched for it to judge.
 *
 * Cancellation: the 200 headers are flushed before the executor runs, and the executor's signal
 * aborts when the response closes before it finished (the caller destroyed its request). A request
 * body that never completed never reaches the executor. Listeners are detached once the call
 * settles, so a long-lived keep-alive socket never accumulates them.
 */
import express, { type ErrorRequestHandler, type NextFunction, type Request, type RequestHandler, type Response } from 'express';
import { createApiError, type ApiError } from '@jini-ai/protocol';
import type { Principal, SurfaceEmitter, ToolDescriptor } from '@jini-ai/core';
import { bearerTokenFromHeader, isLoopbackPeerAddress, sendApiError, statusForError, timingSafeTokenMatch } from '@jini-ai/http-kit';
import type { ToolExecutionResult, ToolExecutor } from '../tool-executor.js';
import { TOOL_EXECUTIONS_ROUTE_PATH, type ToolExecutionWireError, type ToolExecutionWireLine, type ToolExecutionWireRequest } from '../remote-tool-executor.js';

export { TOOL_EXECUTIONS_ROUTE_PATH };
export const TOOL_CATALOG_ROUTE_PATH = '/internal/tool-catalog';
export const DEFAULT_TOOL_EXEC_TOKEN_ENV_VAR = 'JINI_TOOL_EXEC_TOKEN';
/** Tool inputs carry whole documents; 16 MiB matches the largest the agent side sends. */
export const DEFAULT_TOOL_EXEC_MAX_BODY_BYTES = 16 * 1024 * 1024;

/** Anything routes can be mounted on: an Express app or a `Router`. */
export interface ToolExecutionRouteTarget {
  post(path: string, ...handlers: Array<RequestHandler | ErrorRequestHandler>): unknown;
  get(path: string, ...handlers: RequestHandler[]): unknown;
}

/** Runs one call inside host context (e.g. an AsyncLocalStorage scope) built from the wire `context`. */
export type RunWithToolContext = <T>(required: { readonly context: unknown; readonly fn: () => Promise<T> }, optional?: Record<string, never>) => Promise<T>;

export interface ToolExecutionRoutesRequired {
  readonly app: ToolExecutionRouteTarget;
  readonly executor: ToolExecutor;
  /** Built fresh on every catalog request; the route never caches it. */
  readonly listToolsFor: (required: { readonly principalId: string }, optional?: Record<string, never>) => readonly ToolDescriptor[] | Promise<readonly ToolDescriptor[]>;
}

export interface ToolExecutionRoutesOptional {
  /** Env var holding the shared secret. Defaults to {@link DEFAULT_TOOL_EXEC_TOKEN_ENV_VAR}. */
  readonly tokenEnvVar?: string;
  /** Defaults to `process.env`; injectable so tests never mutate the real env. */
  readonly env?: NodeJS.ProcessEnv;
  /** Defaults to {@link DEFAULT_TOOL_EXEC_MAX_BODY_BYTES}. */
  readonly maxBodyBytes?: number;
  readonly runWithContext?: RunWithToolContext;
  /** Host-owned live-run/identity gate, after parsing and before either route dispatches. */
  readonly authorizeRun?: RequestHandler;
}

function refusalFor({ req, expected, tokenEnvVar }: { readonly req: Request; readonly expected: string | undefined; readonly tokenEnvVar: string }): ApiError | null {
  if (!expected) return createApiError({ code: 'NOT_CONFIGURED', message: `${tokenEnvVar} is not set — remote tool execution is disabled` });
  if (!isLoopbackPeerAddress({ address: req.socket?.remoteAddress })) {
    return createApiError({ code: 'FORBIDDEN', message: 'remote tool execution accepts loopback callers only' });
  }
  const presented = bearerTokenFromHeader({ header: req.get('authorization') });
  if (presented === null || !timingSafeTokenMatch({ presented, expected })) {
    return createApiError({ code: 'UNAUTHORIZED', message: `Authorization: Bearer <${tokenEnvVar}> required` });
  }
  return null;
}

/** The token + loopback gate; mounted before any body parser. Exported for hosts that need it on another path. */
export function requireToolExecutionCaller(
  _required: Record<string, never>,
  { tokenEnvVar = DEFAULT_TOOL_EXEC_TOKEN_ENV_VAR, env = process.env }: Pick<ToolExecutionRoutesOptional, 'tokenEnvVar' | 'env'> = {},
): RequestHandler {
  return (req, res, next) => {
    const refusal = refusalFor({ req, expected: env[tokenEnvVar], tokenEnvVar });
    if (refusal === null) { next(); return; }
    sendApiError({ res, status: statusForError({ error: refusal }), error: refusal });
  };
}

/** Maps a body-parser failure (too large, malformed, aborted mid-body) to a refusal; the executor never runs. */
const bodyParserFailure: ErrorRequestHandler = (error: { status?: number }, _req: Request, res: Response, next: NextFunction) => {
  if (res.headersSent) { next(error); return; }
  const tooLarge = error.status === 413;
  const apiError = createApiError({ code: tooLarge ? 'PAYLOAD_TOO_LARGE' : 'BAD_REQUEST', message: tooLarge ? 'request body too large' : 'request body must be valid JSON' });
  sendApiError({ res, status: tooLarge ? 413 : 400, error: apiError });
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function hasStringId(value: unknown): boolean {
  return isRecord(value) && typeof value.id === 'string' && value.id.length > 0;
}

function nonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0;
}

/** Validates the wire body; `null` → 400. The principal object is kept whole for the host's gate. */
function parseExecutionRequest(body: unknown): ToolExecutionWireRequest | null {
  if (!isRecord(body) || !nonEmptyString(body.executionId) || !nonEmptyString(body.toolId)) return null;
  if (!hasStringId(body.principal) || !hasStringId(body.run)) return null;
  const run = body.run as { id: string };
  return {
    executionId: body.executionId,
    principal: body.principal as unknown as Principal,
    run: { id: run.id },
    toolId: body.toolId,
    input: body.input,
    ...(body.context === undefined ? {} : { context: body.context }),
  };
}

function wireError(error: unknown): ToolExecutionWireError {
  if (!(error instanceof Error)) return { name: 'Error', message: String(error) };
  const code = (error as { code?: unknown }).code;
  return { name: error.name, message: error.message, ...(typeof code === 'string' ? { code } : {}) };
}

/**
 * Streams one execution as NDJSON. Headers go out first; surfaces are written as they are emitted
 * and are dropped once the call settled; exactly one terminal line follows.
 */
export async function streamToolExecution(
  { req, res, call, executor }: { readonly req: Request; readonly res: Response; readonly call: ToolExecutionWireRequest; readonly executor: Pick<ToolExecutor, 'execute'> },
  { runWithContext, keepalive = false }: Pick<ToolExecutionRoutesOptional, 'runWithContext'> & { keepalive?: boolean },
): Promise<void> {
  if (res.destroyed) return;
  const controller = new AbortController();
  // `res` 'close' (not `req` 'close', which fires as soon as a completed body was read) means the
  // caller went away; after a normal end `writableFinished` is already true and nothing aborts.
  const onClose = (): void => { if (!res.writableFinished) controller.abort(); };
  const onRequestError = (): void => controller.abort();
  res.on('close', onClose);
  req.on('error', onRequestError);
  res.status(200).setHeader('content-type', 'application/x-ndjson');
  res.setHeader('cache-control', 'no-store');
  res.flushHeaders();
  let settled = false;
  const writeLine = (line: ToolExecutionWireLine | { type: 'keepalive' }): void => { if (!res.writableEnded) res.write(`${JSON.stringify(line)}\n`); };
  const emitSurface: SurfaceEmitter = async (emission) => { if (!settled) writeLine({ type: 'surface', emission }); };
  // Human confirmation may outlive the proxy's idle-body timeout; never poll for an answer.
  const heartbeat = keepalive ? setInterval(() => writeLine({ type: 'keepalive' }), 15_000) : undefined;
  heartbeat?.unref();
  const run = (): Promise<ToolExecutionResult> => executor.execute(
    { principal: call.principal, run: call.run, toolId: call.toolId, input: call.input },
    { signal: controller.signal, emitSurface },
  );
  try {
    if (!req.complete || controller.signal.aborted) return;
    const result = runWithContext ? await runWithContext({ context: call.context, fn: run }) : await run();
    writeLine({ type: 'result', result });
  } catch (error) {
    writeLine({ type: 'throw', error: wireError(error) });
  } finally {
    settled = true;
    if (heartbeat) clearInterval(heartbeat);
    res.off('close', onClose);
    req.off('error', onRequestError);
    res.end();
  }
}

function executionHandler(
  { executor }: Pick<ToolExecutionRoutesRequired, 'executor'>,
  optional: Pick<ToolExecutionRoutesOptional, 'runWithContext'>,
): RequestHandler {
  return (req, res) => {
    const call = parseExecutionRequest(req.body);
    if (call === null) {
      const error = createApiError({ code: 'BAD_REQUEST', message: 'body must be { executionId, principal: { id }, run: { id }, toolId, input, context? }' });
      sendApiError({ res, status: 400, error });
      return;
    }
    void streamToolExecution({ req, res, call, executor }, optional);
  };
}

/**
 * Catalog for one principal. Written with `res.end` rather than `res.json` because Express adds a
 * weak ETag to `json` GET responses, and this answer must never be served from a validator cache:
 * plugin state and delete policy can change between two runs.
 */
function catalogHandler({ listToolsFor }: Pick<ToolExecutionRoutesRequired, 'listToolsFor'>): RequestHandler {
  return async (req, res) => {
    const principalId = req.query.principalId;
    if (!nonEmptyString(principalId)) {
      sendApiError({ res, status: 400, error: createApiError({ code: 'BAD_REQUEST', message: 'principalId query parameter is required' }) });
      return;
    }
    try {
      const tools = await listToolsFor({ principalId });
      res.status(200).setHeader('content-type', 'application/json; charset=utf-8');
      res.setHeader('cache-control', 'no-store');
      res.end(JSON.stringify({ tools }));
    } catch {
      sendApiError({ res, status: 500, error: createApiError({ code: 'INTERNAL_ERROR', message: 'an internal error occurred' }) });
    }
  };
}

/**
 * Mounts both routes on `app` (an Express app or a `Router`). Mount it BEFORE any app-level
 * `express.json()` with a smaller limit: this route parses its own body after its gate, and an
 * earlier parser would both buffer unauthenticated bodies and cap tool inputs at its own limit.
 */
export function registerToolExecutionRoutes(
  { app, executor, listToolsFor }: ToolExecutionRoutesRequired,
  { tokenEnvVar, env, maxBodyBytes = DEFAULT_TOOL_EXEC_MAX_BODY_BYTES, runWithContext, authorizeRun }: ToolExecutionRoutesOptional = {},
): void {
  const gate = requireToolExecutionCaller({}, { ...(tokenEnvVar === undefined ? {} : { tokenEnvVar }), ...(env === undefined ? {} : { env }) });
  const parser = express.json({ limit: maxBodyBytes });
  const runGate = authorizeRun ? [authorizeRun] : [];
  app.post(TOOL_EXECUTIONS_ROUTE_PATH, gate, parser, ...runGate, executionHandler({ executor }, runWithContext === undefined ? {} : { runWithContext }), bodyParserFailure);
  app.get(TOOL_CATALOG_ROUTE_PATH, gate, ...runGate, catalogHandler({ listToolsFor }));
}

