/** The redacted message every internal failure answers with; details go to the error sink. */
const INTERNAL_ERROR_MESSAGE = 'an internal error occurred';

const DEFAULT_TOKEN_FILE_NAME = 'xai-oauth-token.json';
/** Matches the loopback listener's own 30-minute self-close timeout (OD's real comment: keeps the
 * PKCE state, the open socket, and any paste-back UI expiring together). */
const DEFAULT_PENDING_AUTH_TTL_MS = 30 * 60 * 1000;
const DEFAULT_SEARCH_BASE_URL = 'https://api.x.ai/v1';
/** xAI's real Responses-API model id for `x_search`, per OD's origin `X_SEARCH_DEFAULT_MODEL`. */
const DEFAULT_SEARCH_MODEL = 'grok-4.20-reasoning';

/** Deadline for one xAI search request, covering the response body as well as the request. Matches `research.ts`'s `DEFAULT_TAVILY_TIMEOUT_MS` — the two outbound-provider paths in this package should not disagree about how long a stalled upstream may pin a handler. */
const DEFAULT_SEARCH_TIMEOUT_MS = 30_000;

export interface XaiInternalErrorContext {
  readonly source: 'oauth-start' | 'oauth-complete' | 'oauth-disconnect' | 'auth-status' | 'search';
  readonly correlationId: string;
  readonly error: unknown;
}

export interface XaiHttpDeps {
  /** Directory the xAI OAuth token is persisted under (`<dataDir>/<tokenFileName>`). Defaults to `process.cwd()` — a host with a real dataDir should override this (matching `create-local-node-daemon.ts`'s `memoryRoutesDeps.dataDir` pattern). */
  readonly dataDir?: string;
  /** On-disk file name for the stored token, scoped under `dataDir`. Defaults to `xai-oauth-token.json`. */
  readonly tokenFileName?: string;
  /** The OAuth+PKCE provider config to drive the dance against. Defaults to `@jini-ai/agent-runtime`'s real `XAI_OAUTH_PROVIDER_CONFIG` preset — override only to point at a different client_id/issuer (e.g. once a non-PoC xAI client_id is provisioned). */
  readonly providerConfig?: OAuthPkceProviderConfig;
  /** Loopback callback host `providerConfig.clientId` is registered against. Defaults to `XAI_OAUTH_REDIRECT_HOST` (`127.0.0.1`) — see module doc on why this is fixed for xAI's PoC client_id. */
  readonly callbackHost?: string;
  /** Loopback callback port `providerConfig.clientId` is registered against. Defaults to `XAI_OAUTH_REDIRECT_PORT` (`56121`). */
  readonly callbackPort?: number;
  /** Loopback callback path `providerConfig.clientId` is registered against. Defaults to `XAI_OAUTH_REDIRECT_PATH` (`/callback`). */
  readonly callbackPath?: string;
  /** In-memory pending-authorization cache backing the begin/complete dance. Defaults to a fresh 30-minute `PendingAuthCache`, shared across every request `registerXaiRoutes` mounts — see module doc on why this must be resolved once, not per-call. */
  readonly pending?: PendingAuthCache;
  /** Mutable slot holding the in-flight loopback listener, if any (only one OAuth dance can be in flight at a time — the port is a singleton). Shared the same way `pending` is. Defaults to `{ current: null }`. */
  readonly listenerRef?: { current: OAuthCallbackListener | null };
  /** Opens the loopback callback listener. Defaults to `@jini-ai/agent-runtime`'s `startOAuthCallbackListener`. Overridable so tests never bind a real socket. */
  readonly startCallbackListener?: typeof startOAuthCallbackListener;
  /** Base URL for xAI's Responses API (`POST {searchBaseUrl}/responses`). Defaults to `https://api.x.ai/v1`. */
  readonly searchBaseUrl?: string;
  /** Model id sent to the Responses API when a search request doesn't supply its own. Defaults to xAI's real `grok-4.20-reasoning`. */
  readonly searchDefaultModel?: string;
  readonly fetchImpl?: typeof fetch;
  /** Deadline for one search request *and* its response body, in milliseconds. Defaults to {@link DEFAULT_SEARCH_TIMEOUT_MS}. */
  readonly searchTimeoutMs?: number;
  /** Host-owned sink for the real exception behind a generic `INTERNAL_ERROR` response (SEC-005). Defaults to `console.error`. */
  readonly onInternalError?: (context: XaiInternalErrorContext) => void;
}

interface ResolvedXaiHttpDeps {
  dataDir: string;
  tokenFileName: string;
  providerConfig: OAuthPkceProviderConfig;
  callbackHost: string;
  callbackPort: number;
  callbackPath: string;
  pending: PendingAuthCache;
  listenerRef: { current: OAuthCallbackListener | null };
  startCallbackListener: typeof startOAuthCallbackListener;
  searchBaseUrl: string;
  searchDefaultModel: string;
  fetchImpl: typeof fetch;
  searchTimeoutMs: number;
  onInternalError: (context: XaiInternalErrorContext) => void;
}

function defaultInternalErrorSink(context: XaiInternalErrorContext): void {
  // eslint-disable-next-line no-console
  console.error(`[@jini-ai/http-kit] internal error (xai/${context.source}, correlationId=${context.correlationId})`, redactSecrets({ input: inspect(context.error) }, { redactPii: false }));
}

/** Resolves every optional `XaiHttpDeps` field to a concrete value. Idempotent — calling this again on an already-resolved object (e.g. `registerXaiRoutes`'s own single resolution, passed through to each route's `handle`) is a harmless pass-through. See module doc on why stateful fields (`pending`/`listenerRef`) must be resolved once per registration, not once per request. */
function resolveXaiHttpDeps(deps: XaiHttpDeps): ResolvedXaiHttpDeps {
  return { ...resolveOAuthFlowDeps(deps), ...resolveStorageAndSearchDeps(deps) };
}

/** The OAuth dance's provider, loopback-callback and in-flight state defaults. */
function resolveOAuthFlowDeps(deps: XaiHttpDeps): Pick<ResolvedXaiHttpDeps, 'providerConfig' | 'callbackHost' | 'callbackPort' | 'callbackPath' | 'pending' | 'listenerRef' | 'startCallbackListener'> {
  return {
    providerConfig: deps.providerConfig ?? XAI_OAUTH_PROVIDER_CONFIG,
    callbackHost: deps.callbackHost ?? XAI_OAUTH_REDIRECT_HOST,
    callbackPort: deps.callbackPort ?? XAI_OAUTH_REDIRECT_PORT,
    callbackPath: deps.callbackPath ?? XAI_OAUTH_REDIRECT_PATH,
    pending: deps.pending ?? new PendingAuthCache({}, { ttlMs: DEFAULT_PENDING_AUTH_TTL_MS }),
    listenerRef: deps.listenerRef ?? { current: null },
    startCallbackListener: deps.startCallbackListener ?? startOAuthCallbackListener,
  };
}

/** Token storage, search transport and error-sink defaults. */
function resolveStorageAndSearchDeps(deps: XaiHttpDeps): Pick<ResolvedXaiHttpDeps, 'dataDir' | 'tokenFileName' | 'searchBaseUrl' | 'searchDefaultModel' | 'fetchImpl' | 'searchTimeoutMs' | 'onInternalError'> {
  return {
    dataDir: deps.dataDir ?? process.cwd(),
    tokenFileName: deps.tokenFileName ?? DEFAULT_TOKEN_FILE_NAME,
    searchBaseUrl: deps.searchBaseUrl ?? DEFAULT_SEARCH_BASE_URL,
    searchDefaultModel: deps.searchDefaultModel ?? DEFAULT_SEARCH_MODEL,
    fetchImpl: deps.fetchImpl ?? fetch,
    searchTimeoutMs: deps.searchTimeoutMs ?? DEFAULT_SEARCH_TIMEOUT_MS,
    onInternalError: deps.onInternalError ?? defaultInternalErrorSink,
  };
}

function xaiRedirectUri(resolved: ResolvedXaiHttpDeps): string {
  return `http://${resolved.callbackHost}:${resolved.callbackPort}${resolved.callbackPath}`;
}

/** Tracks only the state's lookup key; `PendingAuthCache` remains the single-use authorization owner.
 * Keying by the shared listener slot keeps cancellation scoped to one mounted route pack. */
const pendingOAuthStates = new WeakMap<object, string>();

/** Revokes the pending state before stopping and clearing its listener. Listener shutdown is
 * best-effort — the listener self-closes on completion/timeout anyway, matching OD's origin
 * `stopActiveListener`. Revocation must precede the await so a late paste-back cannot reconnect. */
async function stopListener({ listenerRef, pending }: Pick<ResolvedXaiHttpDeps, 'listenerRef' | 'pending'>, _optional: Record<string, never> = {}): Promise<void> {
  const state = pendingOAuthStates.get(listenerRef);
  pendingOAuthStates.delete(listenerRef);
  if (state !== undefined) pending.consume({ state });
  const current = listenerRef.current;
  listenerRef.current = null;
  if (!current) return;
  try {
    await current.stop();
  } catch {
    // Best-effort only — see this function's own doc.
  }
}

/**
 * Serializes OAuth starts that share one `listenerRef`, keyed by the ref object itself (a
 * `WeakMap`, so a host that discards a registration's deps does not leak an entry here).
 *
 * The loopback callback port is a singleton, and `oauth/start` both checks and claims it
 * (`listenerRef.current`) across two `await`s (`beginOAuthPkce` then `startCallbackListener`).
 * Without serializing, two concurrent starts could both observe `listenerRef.current === null`
 * before either claimed it, both proceed to open a listener, and the second's write would
 * silently clobber the first's — the first caller would already have been handed an
 * `authorizeUrl` whose callback endpoint just died, with no error ever surfaced to it. That is
 * the exact race `xaiOauthStartRoute`'s own `OAUTH_FLOW_IN_PROGRESS` conflict check exists to
 * reject instead of silently losing. Serializing makes "check the slot, then claim it" the single
 * indivisible step it always needed to be, so that check can never race with itself.
 */
const oauthStartQueues = new WeakMap<object, Promise<unknown>>();

function serializeOauthStart<T>(key: object, task: () => Promise<T>): Promise<T> {
  const previous = oauthStartQueues.get(key) ?? Promise.resolve();
  // `then(task, task)` so a rejected predecessor still lets the next start run — this is a mutex,
  // not a dependency chain.
  const next = previous.then(task, task);
  // The stored link must never reject, or an unhandled rejection escapes and every later start
  // inherits it. Only the returned promise carries the outcome.
  oauthStartQueues.set(key, next.then(() => undefined, () => undefined));
  return next;
}

/** Redacts any Bearer/api-key/`key=`-shaped secret out of a thrown value's message before it reaches the internal-error sink — belt-and-braces even on paths (token exchange/refresh) that don't send a bearer header of our own, since the upstream error body is otherwise passed through verbatim. Matches `callXaiSearch`'s own redaction; kept as a separate helper since those two paths have no exact-secret value in common to pass as `redactSecrets`' second argument. */
function redactError(error: unknown): Error {
  const message = error instanceof Error ? error.message : String(error);
  return new Error(redactSecrets({ input: message }));
}

/**
 * Maps a token-endpoint response onto the persisted record. Pure (the save instant is a parameter)
 * so the mapping is testable on its own. `token_type` is optional on the wire type; today's
 * exchange path always supplies it (openid-client rejects a response without one), and an absent
 * value is stored as RFC 6750's `Bearer`. Exported for this module's tests; not re-exported.
 */
export function toStoredOAuthToken({ tokenResp, nowMs }: { tokenResp: OAuthTokenResponse; nowMs: number }): StoredOAuthToken {
  const stored: StoredOAuthToken = {
    accessToken: tokenResp.access_token,
    tokenType: tokenResp.token_type ?? 'Bearer',
    savedAt: nowMs,
  };
  if (tokenResp.refresh_token) stored.refreshToken = tokenResp.refresh_token;
  if (tokenResp.scope) stored.scope = tokenResp.scope;
  if (typeof tokenResp.expires_in === 'number') {
    stored.expiresAt = nowMs + tokenResp.expires_in * 1000;
  }
  return stored;
}

async function persistToken(resolved: ResolvedXaiHttpDeps, tokenResp: OAuthTokenResponse): Promise<void> {
  const stored = toStoredOAuthToken({ tokenResp, nowMs: Date.now() });
  await setStoredOAuthToken({ dataDir: resolved.dataDir, fileName: resolved.tokenFileName, token: stored });
}

/** Invoked when the loopback listener actually receives xAI's redirect (the real-browser path, as opposed to `oauth/complete`'s manual paste-back path — xAI's own docs note the loopback redirect commonly shows the user a code to paste rather than following the redirect). No HTTP response to write here; failures are only reported through the internal-error sink. */
async function handleListenerCallback(resolved: ResolvedXaiHttpDeps, outcome: OAuthCallbackOutcome): Promise<void> {
  resolved.listenerRef.current = null;
  if (outcome.kind !== 'ok') {
    resolved.onInternalError({
      source: 'oauth-start',
      correlationId: randomUUID(),
      error: new Error(`xAI OAuth callback failed: ${outcome.error}`),
    });
    return;
  }
  try {
    const tokenResp = await completeOAuthPkce({
config: resolved.providerConfig,
pending: resolved.pending,
state: outcome.state,
code: outcome.code
}, {
fetchImpl: resolved.fetchImpl
});
    await persistToken(resolved, tokenResp);
  } catch (error) {
    resolved.onInternalError({ source: 'oauth-start', correlationId: randomUUID(), error: redactError(error) });
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Trims before checking/returning — matches OD's real route handlers, which trim `state`/`code`
 * (`routes/xai.ts:154-157`) and `query` (`routes/xai.ts:258`) before ever using them, so a
 * paste-back value with incidental leading/trailing whitespace (the common case for xAI's own
 * loopback-redirect UX, which shows the user a code to copy rather than following a redirect — see
 * this file's own `xaiOauthCompleteRoute` doc) still matches the exact state string the pending-auth
 * cache stored it under. Live-verified against the real OD daemon (2026-07-22 live-parity pass):
 * `POST /oauth/complete` with a state padded in extra spaces around a real, still-pending state
 * proceeded straight to the token exchange (reaching `auth.x.ai`'s real "invalid_grant" response)
 * instead of failing with "state not found or expired" — proving OD's server-side trim, not just its
 * request-body parsing, is load-bearing. This file's own three `nonEmptyString` call sites
 * (`state`/`code` in `parseXaiOauthComplete`, `query` in `parseXaiSearch`) are exactly OD's three
 * trimmed fields — `fromDate`/`toDate`/`model` deliberately go through `parseOptionalString` instead,
 * which does not trim, matching OD's own untrimmed `from_date`/`to_date`/`model` handling. */
function nonEmptyString(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function parseOptionalString(body: Record<string, unknown>, key: string): Result<string | undefined> {
  const value = body[key];
  if (value === undefined) return ok({ value: undefined });
  if (typeof value !== 'string') return err({ error: validationError({ message: `${key} must be a string when provided` }) });
  return ok({ value });
}

function parseOptionalBoolean(body: Record<string, unknown>, key: string): Result<boolean | undefined> {
  const value = body[key];
  if (value === undefined) return ok({ value: undefined });
  if (typeof value !== 'boolean') return err({ error: validationError({ message: `${key} must be a boolean when provided` }) });
  return ok({ value });
}

function parseOptionalStringArray(body: Record<string, unknown>, key: string): Result<readonly string[] | undefined> {
  const value = body[key];
  if (value === undefined) return ok({ value: undefined });
  if (!Array.isArray(value) || !value.every((v) => typeof v === 'string')) {
    return err({ error: validationError({ message: `${key} must be an array of strings when provided` }) });
  }
  return ok({ value: value as string[] });
}

// ---------------------------------------------------------------------------
// POST /api/xai/oauth/start
// ---------------------------------------------------------------------------

export interface XaiOauthStartResponse {
  readonly authorizeUrl: string;
  readonly state: string;
  readonly callback: { readonly host: string; readonly port: number };
}

export const xaiOauthStartRoute = defineJsonRoute<void, XaiOauthStartResponse, XaiHttpDeps>({
  method: 'post', path: '/api/xai/oauth/start', parse: () => ok({ value: undefined }), handle: async ({ input: _input, deps }) => {
    const resolved = resolveXaiHttpDeps(deps);
    // Only one OAuth dance can be in flight at a time — the loopback port is a singleton. A
    // second `start` arriving while a listener from a prior `start` is still bound/waiting used
    // to silently stop that listener and open a new one: the first caller's already-returned
    // `authorizeUrl` would point at a now-dead callback endpoint with no error ever surfaced to
    // it. Fail loud instead: reject with a conflict and require the caller to finish
    // (`oauth/complete`) or explicitly cancel (`POST /api/xai/oauth/cancel`) the in-flight flow
    // first. The check-then-claim runs under `serializeOauthStart` so two concurrent starts can't
    // both observe an empty slot — see that function's doc.
    return serializeOauthStart(resolved.listenerRef, async () => {
      if (resolved.listenerRef.current !== null) {
        return err({
          error: createApiError({ code: 'OAUTH_FLOW_IN_PROGRESS', message: 'an xAI OAuth flow is already in progress — complete it, or cancel it via POST /api/xai/oauth/cancel, before starting a new one' }, )
        });
      }
      try {
        const { authorizeUrl, state } = beginOAuthPkce({
          config: resolved.providerConfig,
          pending: resolved.pending,
          redirectUri: xaiRedirectUri(resolved),
        });
        pendingOAuthStates.set(resolved.listenerRef, state);
        const listener = await resolved.startCallbackListener({
          host: resolved.callbackHost,
          port: resolved.callbackPort,
          path: resolved.callbackPath,
          expectedState: state,
          onCallback: (outcome) => handleListenerCallback(resolved, outcome),
        });
        resolved.listenerRef.current = listener;
        return ok({
          value: {
            authorizeUrl,
            state,
            callback: { host: listener.address.host, port: listener.address.port },
          }
        });
      } catch (error) {
        await stopListener(resolved);
        const correlationId = randomUUID();
        resolved.onInternalError({ source: 'oauth-start', correlationId, error });
        return err({ error: createApiError({ code: 'INTERNAL_ERROR', message: INTERNAL_ERROR_MESSAGE }, { requestId: correlationId }) });
      }
    });
  }
}, { requireSameOrigin: true });

// ---------------------------------------------------------------------------
// POST /api/xai/oauth/complete
// ---------------------------------------------------------------------------

export interface XaiOkResponse {
  readonly ok: true;
}

interface XaiOauthCompleteRequest {
  readonly state: string;
  readonly code: string;
}

function parseXaiOauthComplete(input: RouteInputContext): Result<XaiOauthCompleteRequest> {
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });
  const state = nonEmptyString(input.body.state);
  if (!state) return err({ error: validationError({ message: 'state must be a non-empty string' }, { issues: [{ path: 'state', message: 'required non-empty string' }] }) });
  const code = nonEmptyString(input.body.code);
  if (!code) return err({ error: validationError({ message: 'code must be a non-empty string' }, { issues: [{ path: 'code', message: 'required non-empty string' }] }) });
  return ok({ value: { state, code } });
}

export const xaiOauthCompleteRoute = defineJsonRoute<XaiOauthCompleteRequest, XaiOkResponse, XaiHttpDeps>({
  method: 'post', path: '/api/xai/oauth/complete', parse: parseXaiOauthComplete, handle: async ({ input: { state, code }, deps }) => {
    const resolved = resolveXaiHttpDeps(deps);
    try {
      const tokenResp = await completeOAuthPkce({
config: resolved.providerConfig,
pending: resolved.pending,
state,
code
}, {
fetchImpl: resolved.fetchImpl
});
      await persistToken(resolved, tokenResp);
      // We won the race against the loopback listener (or it was never going to resolve in the
      // first place); shut it down so the next `oauth/start` has a clean slate — matching OD's
      // origin behavior on a successful manual paste-back.
      await stopListener(resolved);
      return ok({ value: { ok: true } });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      // `completeOAuthPkce`'s own pre-network validation errors ("state not found or expired",
      // "state mismatch...") carry no secret and are a legitimate client-correctable failure —
      // surfaced verbatim as BAD_REQUEST rather than folded into the SEC-005 INTERNAL_ERROR path
      // below (see module doc's "SEC-005 throughout" section). Exact-prefix match, not substring:
      // pkce.ts#tokenRequest's upstream-error message ("token endpoint rejected request: ...")
      // can legitimately contain the substring "OAuth state" inside an attacker-influenced token
      // endpoint error body, which must never be reflected raw to the caller.
      if (message.startsWith(`${resolved.providerConfig.providerId} OAuth state`)) {
        return err({ error: validationError({ message }) });
      }
      const correlationId = randomUUID();
      resolved.onInternalError({ source: 'oauth-complete', correlationId, error: redactError(error) });
      return err({ error: createApiError({ code: 'INTERNAL_ERROR', message: INTERNAL_ERROR_MESSAGE }, { requestId: correlationId }) });
    }
  }
}, { requireSameOrigin: true });

// ---------------------------------------------------------------------------
// POST /api/xai/oauth/cancel
// ---------------------------------------------------------------------------

export const xaiOauthCancelRoute = defineJsonRoute<void, XaiOkResponse, XaiHttpDeps>({
  method: 'post', path: '/api/xai/oauth/cancel', parse: () => ok({ value: undefined }), handle: async ({ input: _input, deps }) => {
    const resolved = resolveXaiHttpDeps(deps);
    // Cancel revokes the pending state and stops the listener; it must never wipe a stored
    // token — a user clicking Cancel mid-reconnect would otherwise lose their existing grant. Disconnect
    // (below) is the destructive path. Preserves OD's origin `oauth/cancel` token-retention behavior.
    await stopListener(resolved);
    return ok({ value: { ok: true } });
  }
}, { requireSameOrigin: true });

// ---------------------------------------------------------------------------
// GET /api/xai/auth/status
// ---------------------------------------------------------------------------

export interface XaiAuthStatusResponse {
  readonly connected: boolean;
  readonly expiresAt: number | null;
  readonly scope: string | null;
  readonly savedAt: number | null;
  readonly listening: boolean;
}

export const xaiAuthStatusRoute = defineJsonRoute<void, XaiAuthStatusResponse, XaiHttpDeps>({
  method: 'get', path: '/api/xai/auth/status', parse: () => ok({ value: undefined }), handle: async ({ input: _input, deps }) => {
    const resolved = resolveXaiHttpDeps(deps);
    try {
      const token = await getStoredOAuthToken({ dataDir: resolved.dataDir, fileName: resolved.tokenFileName });
      const listening = resolved.listenerRef.current !== null;
      if (!token) return ok({ value: { connected: false, expiresAt: null, scope: null, savedAt: null, listening } });
      return ok({
        value: {
          connected: true,
          expiresAt: token.expiresAt ?? null,
          scope: token.scope ?? null,
          savedAt: token.savedAt,
          listening,
        }
      });
    } catch (error) {
      const correlationId = randomUUID();
      resolved.onInternalError({ source: 'auth-status', correlationId, error });
      return err({ error: createApiError({ code: 'INTERNAL_ERROR', message: INTERNAL_ERROR_MESSAGE }, { requestId: correlationId }) });
    }
  }
}, { requireSameOrigin: true });

// ---------------------------------------------------------------------------
// POST /api/xai/oauth/disconnect
// ---------------------------------------------------------------------------

export const xaiOauthDisconnectRoute = defineJsonRoute<void, XaiOkResponse, XaiHttpDeps>({
  method: 'post', path: '/api/xai/oauth/disconnect', parse: () => ok({ value: undefined }), handle: async ({ input: _input, deps }) => {
    const resolved = resolveXaiHttpDeps(deps);
    try {
      await stopListener(resolved);
      await clearStoredOAuthToken({ dataDir: resolved.dataDir, fileName: resolved.tokenFileName });
      return ok({ value: { ok: true } });
    } catch (error) {
      const correlationId = randomUUID();
      resolved.onInternalError({ source: 'oauth-disconnect', correlationId, error });
      return err({ error: createApiError({ code: 'INTERNAL_ERROR', message: INTERNAL_ERROR_MESSAGE }, { requestId: correlationId }) });
    }
  }
}, { requireSameOrigin: true });

// ---------------------------------------------------------------------------
// POST /api/xai/search
// ---------------------------------------------------------------------------

interface XaiSearchRequest {
  readonly query: string;
  readonly allowedXHandles?: readonly string[];
  readonly excludedXHandles?: readonly string[];
  readonly fromDate?: string;
  readonly toDate?: string;
  readonly enableImageUnderstanding?: boolean;
  readonly enableVideoUnderstanding?: boolean;
  readonly model?: string;
}

function parseXaiSearch(input: RouteInputContext): Result<XaiSearchRequest> {
  if (!isRecord(input.body)) return err({ error: validationError({ message: 'body must be a JSON object' }) });
  const body = input.body;
  const query = nonEmptyString(body.query);
  if (!query) return err({ error: validationError({ message: 'query must be a non-empty string' }, { issues: [{ path: 'query', message: 'required non-empty string' }] }) });

  const fields: Record<string, unknown> = {};
  for (const [key, parse] of XAI_SEARCH_OPTIONAL_FIELDS) {
    const parsed = parse(body, key);
    if (!parsed.ok) return parsed;
    if (isProvidedSearchValue(parsed.value)) fields[key] = parsed.value;
  }
  return ok({ value: { query, ...fields } });
}

/** Table order is the validation order: the first failing field is the one a caller sees. */
const XAI_SEARCH_OPTIONAL_FIELDS: ReadonlyArray<readonly [Exclude<keyof XaiSearchRequest, 'query'>, (body: Record<string, unknown>, key: string) => Result<unknown>]> = [
  ['allowedXHandles', parseOptionalStringArray],
  ['excludedXHandles', parseOptionalStringArray],
  ['fromDate', parseOptionalString],
  ['toDate', parseOptionalString],
  ['enableImageUnderstanding', parseOptionalBoolean],
  ['enableVideoUnderstanding', parseOptionalBoolean],
  ['model', parseOptionalString],
];

/** An empty string or empty handle list counts as not provided (dropped from the request); `false` is kept. */
function isProvidedSearchValue(value: unknown): boolean {
  if (Array.isArray(value)) return value.length > 0;
  return value !== undefined && value !== '';
}

export interface XaiSearchResponse {
  readonly answer: string;
  readonly citations: readonly string[];
  readonly model: string;
}

/** Every well-formed `output[].content[]` block of a Responses-API payload, skipping malformed items and blocks. */
function outputContentBlocks(data: Record<string, unknown>): Record<string, unknown>[] {
  const output = data.output;
  if (!Array.isArray(output)) return [];
  return output.filter(isRecord).flatMap((item) => (Array.isArray(item.content) ? item.content.filter(isRecord) : []));
}

/** Pulls the assistant's main text out of an xAI Responses-API payload — the convenience `output_text` field, or the structured `output[].content[].text` form. Ported from OD's `extractAnswerText` (same behaviour; the walk is shared with `extractUrlCitations` via `outputContentBlocks`). */
function extractAnswerText(data: unknown): string {
  if (!isRecord(data)) return '';
  const direct = data.output_text;
  if (typeof direct === 'string' && direct.trim()) return direct;
  const chunks = outputContentBlocks(data)
    .map((block) => block.text)
    .filter((text): text is string => typeof text === 'string' && text.length > 0);
  return chunks.join('\n').trim();
}

/** The trimmed URL of one `url_citation` annotation, or `''` for anything else. */
function urlCitationOf(annotation: unknown): string {
  if (!isRecord(annotation) || annotation.type !== 'url_citation') return '';
  return typeof annotation.url === 'string' ? annotation.url.trim() : '';
}

/** Walks every annotation in the Responses-API output and returns the unique URL citations (`type: 'url_citation'`). Ported from OD's `extractUrlCitations` (same behaviour, first-seen order). */
function extractUrlCitations(data: unknown): string[] {
  if (!isRecord(data)) return [];
  const urls = outputContentBlocks(data)
    .flatMap((block) => (Array.isArray(block.annotations) ? block.annotations : []))
    .map(urlCitationOf)
    .filter((url) => url.length > 0);
  return [...new Set(urls)];
}

/** Builds the `x_search` native tool payload, translating only the provided fields to xAI's snake_case names. */
function buildXSearchTool(request: XaiSearchRequest): Record<string, unknown> {
  const xSearchTool: Record<string, unknown> = { type: 'x_search' };
  if (request.allowedXHandles?.length) xSearchTool.allowed_x_handles = request.allowedXHandles;
  if (request.excludedXHandles?.length) xSearchTool.excluded_x_handles = request.excludedXHandles;
  if (request.fromDate) xSearchTool.from_date = request.fromDate;
  if (request.toDate) xSearchTool.to_date = request.toDate;
  if (request.enableImageUnderstanding === true) xSearchTool.enable_image_understanding = true;
  if (request.enableVideoUnderstanding === true) xSearchTool.enable_video_understanding = true;
  return xSearchTool;
}

/** One search call's deadline signal plus the secret every thrown message must be redacted of. */
interface XaiCallGuard {
  readonly signal: AbortSignal;
  readonly timedOutMessage: string;
  readonly accessToken: string;
}

/** A thrown fetch/body-read failure as the timeout message when the deadline fired, else as a `prefix: message` with `accessToken` redacted. */
function xaiCallFailure(guard: XaiCallGuard, prefix: string, error: unknown): Error {
  if (guard.signal.aborted) return new Error(guard.timedOutMessage);
  const message = error instanceof Error ? error.message : String(error);
  return new Error(redactSecrets({ input: `${prefix}: ${message}` }, { exactSecrets: [guard.accessToken] }));
}

async function postXaiResponses({ fetchImpl, url, requestBody, guard }: {
  fetchImpl: typeof fetch;
  url: string;
  requestBody: Record<string, unknown>;
  guard: XaiCallGuard;
}): Promise<Response> {
  let response: Response;
  try {
    response = await fetchImpl(url, {
      method: 'POST',
      headers: { authorization: `Bearer ${guard.accessToken}`, 'content-type': 'application/json' },
      body: JSON.stringify(requestBody),
      signal: guard.signal,
    });
  } catch (error) {
    throw xaiCallFailure(guard, 'xAI request failed', error);
  }
  if (!response.ok) {
    const text = await response.text().catch(() => '');
    throw new Error(redactSecrets({ input: `xAI ${response.status}: ${text.slice(0, 240) || 'no body'}` }, { exactSecrets: [guard.accessToken] }));
  }
  return response;
}

async function readXaiJson(response: Response, guard: XaiCallGuard): Promise<unknown> {
  try {
    return await response.json();
  } catch (error) {
    throw xaiCallFailure(guard, 'xAI response could not be read', error);
  }
}

/** Calls xAI's real `POST {searchBaseUrl}/responses` endpoint with the `x_search` native tool, using `accessToken` as the bearer credential. Throws (never a `Result`) on any failure — `xaiSearchRoute.handle` is the one place that converts a thrown error into this package's SEC-005 response shape. Any thrown message is pre-redacted of `accessToken` here so the sink never even logs it unredacted. */
async function callXaiSearch(resolved: ResolvedXaiHttpDeps, accessToken: string, request: XaiSearchRequest): Promise<XaiSearchResponse> {
  const baseUrlCheck = validateBaseUrl({ baseUrl: resolved.searchBaseUrl });
  if (baseUrlCheck.error) throw new Error(baseUrlCheck.error);
  const base = trimCharsEnd({ text: resolved.searchBaseUrl, chars: '/' });
  const model = request.model ?? resolved.searchDefaultModel;

  const requestBody = {
    model,
    input: [{ role: 'user', content: request.query }],
    tools: [buildXSearchTool(request)],
    store: false,
  };

  // One deadline covering the request *and* the body read, mirroring `research.ts`'s Tavily call.
  // Arming it only around `fetch` would leave the far more common stall unbounded: an upstream that
  // returns headers promptly and then never finishes the body still pins this handler, its socket
  // and the caller's connection forever. The timer is cleared in a `finally` so a fast response
  // does not leave one armed.
  const timeoutController = new AbortController();
  const timeoutHandle = setTimeout(() => timeoutController.abort(), resolved.searchTimeoutMs);
  const guard: XaiCallGuard = {
    signal: timeoutController.signal,
    timedOutMessage: `xAI request timed out after ${resolved.searchTimeoutMs}ms`,
    accessToken,
  };
  try {
    const response = await postXaiResponses({ fetchImpl: resolved.fetchImpl, url: `${base}/responses`, requestBody, guard });
    const data = await readXaiJson(response, guard);
    return { answer: extractAnswerText(data), citations: extractUrlCitations(data), model };
  } finally {
    clearTimeout(timeoutHandle);
  }
}

export const xaiSearchRoute = defineJsonRoute<XaiSearchRequest, XaiSearchResponse, XaiHttpDeps>({
  method: 'post', path: '/api/xai/search', parse: parseXaiSearch, handle: async ({ input: request, deps }) => {
    const resolved = resolveXaiHttpDeps(deps);

    let credential: ResolvedOAuthCredential | null;
    try {
      credential = await resolveOAuthBearer({ config: resolved.providerConfig, tokenFileName: resolved.tokenFileName, dataDir: resolved.dataDir }, { fetchImpl: resolved.fetchImpl });
    } catch (error) {
      const correlationId = randomUUID();
      resolved.onInternalError({ source: 'search', correlationId, error });
      return err({ error: createApiError({ code: 'INTERNAL_ERROR', message: INTERNAL_ERROR_MESSAGE }, { requestId: correlationId }) });
    }
    if (!credential) {
      // No entitlement gate here — see module doc's "Dropped: OD's SuperGrok subscription gate"
      // section. This is only "no connected/refreshable xAI account," an honest, non-exceptional
      // NOT_CONFIGURED (503), matching `research.ts`'s "capability exists, reachable, inert until
      // configured" shape.
      return err({ error: createApiError({ code: 'NOT_CONFIGURED', message: 'no xAI account connected — sign in via /api/xai/oauth/start first' }) });
    }

    try {
      const result = await callXaiSearch(resolved, credential.accessToken, request);
      return ok({ value: result });
    } catch (error) {
      const correlationId = randomUUID();
      resolved.onInternalError({ source: 'search', correlationId, error });
      return err({ error: createApiError({ code: 'INTERNAL_ERROR', message: INTERNAL_ERROR_MESSAGE }, { requestId: correlationId }) });
    }
  }
}, { requireSameOrigin: true });

/** Mounts every xAI route on `app`. A pack's `http(app, services)` calls this directly. */
export function registerXaiRoutes({ app, deps, adapter }: { readonly app: Express; readonly deps: XaiHttpDeps; readonly adapter: AdapterContext }, _optional: Record<string, never> = {}): void {
  const resolved = resolveXaiHttpDeps(deps);
  mountJsonRoute({ app, spec: xaiOauthStartRoute, deps: resolved, adapter });
  mountJsonRoute({ app, spec: xaiOauthCompleteRoute, deps: resolved, adapter });
  mountJsonRoute({ app, spec: xaiOauthCancelRoute, deps: resolved, adapter });
  mountJsonRoute({ app, spec: xaiAuthStatusRoute, deps: resolved, adapter });
  mountJsonRoute({ app, spec: xaiOauthDisconnectRoute, deps: resolved, adapter });
  mountJsonRoute({ app, spec: xaiSearchRoute, deps: resolved, adapter });
}

/**
 * `RunLifecycle` — start/stream/cancel/resume a run keyed on an opaque
 * `contextRef` (extraction-plan §2.1: runs key on an opaque `contextRef`,
 * never a product-record identifier), generalized from OD's `design.runs` service
 * (`apps/daemon/src/runtimes/runs.ts` + the terminal-decision half of
 * `apps/daemon/src/runtimes/start-chat-run.ts`, `arch/server-startserver-endgame`
 * branch — see `archived provenance ledger` for exact line citations).
 *
 * Scope boundary: this module owns the run *state machine* and its event
 * log — create, transition, emit, replay, cancellation-intent propagation,
 * idempotent start/finish, resume. It does not spawn or signal a subprocess;
 * that is `@jini-ai/agent-runtime`'s job (extraction-plan task 7). A driver
 * (today: this package's tests; later: agent-runtime) calls `emit()` for
 * agent/stdout/stderr/error events, observes cancellation via
 * `onCancelRequested`, and calls `finish()` once it knows the real outcome.
 */
import { inspect } from 'node:util';
import { redactSecrets } from '@jini-ai/core';
import type { DelegatedResultCorrelation } from './delegated-result-correlation.js';
import { randomUUID } from 'node:crypto';
import type {
  RunAgentPayload,
  RunCancelRequest,
  RunChunkPayload,
  RunEndPayload,
  RunErrorPayload,
  RunProtocolEvent,
  RunStartPayload,
  RunState,
  RunStatus,
} from '@jini-ai/protocol';
import { RUN_PROTOCOL_VERSION, isTerminalRunState } from '@jini-ai/protocol';
import type { EventLog, EventLogEntry, EventLogReplayResult } from './event-log.js';
import type { InactivityWatchdog, TerminalRunOutcome } from './close-status.js';
import { createInactivityWatchdog } from './close-status.js';

export interface StartRunInput {
  /** Opaque caller-supplied identity the run belongs to — never a project/conversation id (see module doc). */
  readonly contextRef: string;
  readonly agentId?: string;
  /**
   * Caller-supplied idempotency key. Starting twice with the same key
   * returns the original run (`started: false`) instead of creating a
   * second one — new behavior this port builds fresh, since OD's own
   * `clientRequestId` is threaded through but never actually deduplicated
   * against (confirmed absent upstream; see `archived provenance ledger`).
   */
  readonly idempotencyKey?: string;
  /** Override the generated run id — test/fixture hook only. */
  readonly runId?: string;
  /** When set, arms an inactivity watchdog that fails the run permanently if no `emit()` occurs within this window. */
  readonly inactivityTimeoutMs?: number;
}

export interface StartRunResult {
  readonly run: RunStatus;
  /** `false` when an existing run was returned via idempotency-key replay rather than a new one being created. */
  readonly started: boolean;
}

export interface FinishRunInput {
  readonly runId: string;
  readonly status: TerminalRunOutcome;
  readonly code: number | null;
  readonly signal: string | null;
  /**
   * True when a `'failed'`/`'cancelled'` run can be recovered by `resume()`
   * instead of requiring a fresh `start()`. Generalized from OD's
   * `run.resumable` flag (set only for a narrow, explicitly resumable
   * failure-classification subset — see `run-failure-classification.ts` in
   * the researched source).
   */
  readonly resumable: boolean;
  /** Gap 5 (session resume) — see `RunEndPayload.sessionRef`'s doc in `@jini-ai/protocol`. Threaded straight through to the durable `'end'` entry; this module has no opinion on what it means. */
  readonly sessionRef?: string;
}

export interface ResumeRunResult {
  readonly run: RunStatus;
  /** `false` when the run was not eligible (not terminal, or terminal but not `resumable`) — not an error, just a no-op. */
  readonly resumed: boolean;
}

/** The subset of `RunProtocolEvent` a driver may emit directly. `'start'`/`'end'` are kernel-managed — see `start()`/`finish()`. */
export type DriverEmittableInput =
  | { readonly event: 'agent'; readonly data: RunAgentPayload }
  | { readonly event: 'stdout'; readonly data: RunChunkPayload }
  | { readonly event: 'stderr'; readonly data: RunChunkPayload }
  | { readonly event: 'error'; readonly data: RunErrorPayload };

export type Unsubscribe = () => void;

export interface StreamOptions {
  readonly afterCursor?: string | null;
}

export type StreamSubscribeResult = { readonly kind: 'ok'; readonly unsubscribe: Unsubscribe } | Exclude<EventLogReplayResult, { kind: 'ok' }>;

export interface RunLifecycle {
  /** Rebuilds the in-memory run index from durable EventLog records. Hosts must await this once during boot before accepting run requests. */
  rehydrate(_args: Record<string, never>): Promise<void>;
  start(requiredArgs: Pick<StartRunInput, "contextRef">, optionalArgs?: Pick<StartRunInput, "agentId" | "idempotencyKey" | "runId" | "inactivityTimeoutMs">): Promise<StartRunResult>;
  get(args: { readonly runId: string }): Promise<RunStatus | undefined>;
  list(args: Record<string, never>, optionalArgs?: { readonly contextRef?: string }): Promise<readonly RunStatus[]>;
  /** Records cancellation intent. Idempotent — cancelling an already-terminal run is a no-op, not an error. */
  cancel(request: RunCancelRequest): Promise<RunStatus>;
  /** Registers a listener fired synchronously when `cancel()` is called for `runId`. Returns an unsubscribe function. */
  onCancelRequested(args: { readonly runId: string; readonly listener: (request: RunCancelRequest) => void }): Unsubscribe;
  /** Appends a driver-observed event and fans it out to live subscribers. Throws if `runId` is unknown or already terminal. */
  emit(args: { readonly runId: string; readonly input: DriverEmittableInput }): Promise<RunProtocolEvent>;
  /** Idempotent terminal transition; a second call while already terminal is a no-op that returns the existing status unchanged. */
  finish(requiredArgs: Pick<FinishRunInput, "runId" | "status" | "code" | "signal" | "resumable">, optionalArgs?: Pick<FinishRunInput, "sessionRef">): Promise<RunStatus>;
  resume(args: { readonly runId: string }): Promise<ResumeRunResult>;
  /**
   * Suspends the slow-run watchdog for `runId` while a daemon-managed operation of legitimately
   * unbounded duration is in flight (e.g. an auto-resolved tool call the daemon itself awaits) — pair
   * with {@link RunLifecycle.resumeSlowRunNotice} once that operation concludes. `emit()` of an agent event (excluding the notice itself) is the
   * *only* other reset signal the watchdog has, and it fires nothing while such an operation is
   * running (there is no output to stream), so without this call a tool that legitimately runs past
   * the threshold (an install, a build, a repo-wide scan) is indistinguishable from the exact
   * CPU-starved-and-silent condition the watchdog exists to catch, and fires a "still working" notice
   * on a run that never actually stalled. A driver that knows exactly why a run is quiet must say so
   * rather than leaving the watchdog to guess from silence alone. No-op if `runId` is unknown,
   * already terminal, or the slow-run notice is disabled kernel-wide (`slowRunThresholdMs: null`).
   * Pairs nest: the notice stays suspended until every open suspension has been resumed.
   */
  suspendSlowRunNotice(args: { readonly runId: string }): void;
  /**
   * Re-arms the slow-run watchdog for `runId` with a fresh timeout window, undoing
   * {@link RunLifecycle.suspendSlowRunNotice} once the known operation concludes — so a genuinely
   * stalled stretch starting *after* that point is still caught. No-op under the same conditions as
   * `suspendSlowRunNotice`.
   */
  resumeSlowRunNotice(args: { readonly runId: string }): void;
  /** Resolves once `runId` reaches a terminal state; resolves immediately if it already has.
   * Aborting `signal` rejects with its reason and unregisters the waiter (a caller tearing down). */
  waitForTerminal(args: { readonly runId: string }, optional?: { readonly signal?: AbortSignal }): Promise<RunStatus>;
  /**
   * Replays buffered history after `options.afterCursor` (or from the
   * beginning if omitted/null) and then subscribes `onEvent` for live
   * delivery — the reconnect-and-resume-streaming operation a transport
   * uses. Mirrors OD's own reconnect guarantee: a caller that reconnects
   * already caught up on a *terminal* run still receives one more delivery
   * of the final `'end'` event, so a client can never silently miss the
   * terminal signal (`runs.ts` `stream()`, researched source).
   */
  stream(args: { readonly runId: string; readonly onEvent: (event: RunProtocolEvent) => void }, optionalArgs?: StreamOptions): Promise<StreamSubscribeResult>;
}

interface RunRecord {
  contextRef: string | undefined;
  /** The idempotency key this run was started with, if any — retained (not just indexed) so terminal-retention eviction can clean its `idempotencyIndex` entry without a reverse lookup. */
  idempotencyKey: string | undefined;
  status: {
    id: string;
    state: RunState;
    startedAt: number;
    updatedAt: number;
    endedAt: number | undefined;
  };
  resumable: boolean;
  cancelRequested: boolean;
  /** The most recent cancellation request, if any — replayed to a listener that subscribes after `cancel()` already fired (see `onCancelRequested`). */
  lastCancelRequest: RunCancelRequest | undefined;
  cancelListeners: Set<(request: RunCancelRequest) => void>;
  subscribers: Set<(event: RunProtocolEvent) => void>;
  terminalWaiters: Array<(status: RunStatus) => void>;
  terminalEndEntry: EventLogEntry | undefined;
  watchdog: InactivityWatchdog | undefined;
  /**
   * Separate, non-terminating timer for the slow-run notice — reuses the same reset-on-activity
   * primitive as `watchdog` above, but its `onTimeout` emits a `'slow_running'` agent event instead
   * of finishing the run. Kept as its own field (not folded into `watchdog`) because the two can be
   * configured, armed, and cancelled independently: `watchdog` requires an explicit per-`start()`
   * opt-in (`StartRunInput.inactivityTimeoutMs`) and terminates the run on fire, while this one is
   * armed kernel-wide by default (`CreateRunLifecycleInput.slowRunThresholdMs`) and never terminates
   * anything. See {@link armSlowRunWatchdogIfConfigured}.
   */
  slowRunWatchdog: InactivityWatchdog | undefined;
  /**
   * How many {@link RunLifecycle.suspendSlowRunNotice} calls are still open for this run. A count,
   * not a flag: two delegated calls can be in flight at once (one parked on a human's form, one a
   * plain tool), and the first to finish must not re-arm the notice over the other's open form.
   */
  slowRunSuspensions: number;
  /** Pending durable start append; idempotent duplicates wait for it instead of observing a ghost record. */
  startPromise: Promise<void> | undefined;
  /** Serializes concurrent terminal transitions while state remains non-terminal until the end append commits. */
  finishPromise: Promise<RunStatus> | undefined;
  /** Armed while this run is terminal and retained, pending eviction from `runs`/`idempotencyIndex` — see the terminal-retention helpers below. `undefined` for a non-terminal run, or a terminal one `resume()` has reclaimed. */
  retentionTimer: ReturnType<typeof setTimeout> | undefined;
}

/** Vocabulary-firewall bridge: `RunState` uses `'cancelled'` (extraction-plan §12 C5's own cited canary), `RunEndPayload.status` uses `'canceled'`. Both live in `@jini-ai/protocol`, which is out of scope for this task — bridged here rather than fixed upstream. */
const TERMINAL_OUTCOME_TO_END_STATUS: Record<TerminalRunOutcome, NonNullable<RunEndPayload['status']>> = {
  succeeded: 'succeeded',
  failed: 'failed',
  cancelled: 'canceled',
};

function toPublicStatus(record: RunRecord): RunStatus {
  const status: RunStatus = {
    id: record.status.id,
    state: record.status.state,
    startedAt: record.status.startedAt,
    updatedAt: record.status.updatedAt,
  };
  if (record.status.endedAt !== undefined) {
    return { ...status, endedAt: record.status.endedAt };
  }
  return status;
}

/**
 * Bridges `@jini-ai/daemon`'s own `EventLogEntry` (`{id, event, data, recordedAt}`) to
 * `@jini-ai/protocol`'s canonical `RunEvent` envelope. `EventLogEntry` carries no `runId` of its
 * own (the log is already scoped by the `runId` parameter every `EventLog` method takes), so
 * this is the one place that stamps it onto the outgoing envelope.
 */
function toRunEvent(runId: string, entry: EventLogEntry): RunProtocolEvent {
  return {
    runId,
    eventId: `${runId}:${entry.id}`,
    opaqueCursor: entry.id,
    protocolVersion: RUN_PROTOCOL_VERSION,
    ts: entry.recordedAt,
    kind: entry.event,
    payload: entry.data,
    durability: 'durable',
  } as RunProtocolEvent;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Reads the two run-level fields the kernel persists on a run's `'start'` entry. Both are absent
 * on a log whose start entry carried a non-record payload (or no start entry at all).
 */
function readStartMetadata(startEntry: EventLogEntry | undefined): {
  contextRef: string | undefined;
  idempotencyKey: string | undefined;
} {
  const startData = startEntry && isRecord(startEntry.data) ? startEntry.data : null;
  return {
    contextRef: typeof startData?.contextRef === 'string' ? startData.contextRef : undefined,
    idempotencyKey: typeof startData?.idempotencyKey === 'string' ? startData.idempotencyKey : undefined,
  };
}

/** Rebuilds the public status block for a rehydrated run from its first/last/start/end log entries. */
function rehydratedStatus(
  runId: string,
  bounds: {
    startEntry: EventLogEntry | undefined;
    endEntry: EventLogEntry | undefined;
    firstEntry: EventLogEntry;
    lastEntry: EventLogEntry;
    terminal: { state: TerminalRunOutcome; resumable: boolean } | null;
  },
): RunRecord['status'] {
  return {
    id: runId,
    state: bounds.terminal?.state ?? 'running',
    startedAt: bounds.startEntry?.recordedAt ?? bounds.firstEntry.recordedAt,
    updatedAt: bounds.lastEntry.recordedAt,
    endedAt: bounds.endEntry?.recordedAt,
  };
}

/**
 * Rebuilds one in-memory `RunRecord` from a run's replayed durable entries. Volatile fields
 * (listeners, subscribers, watchdog, in-flight promises) cannot survive a restart and are reset.
 */
function rehydratedRunRecord(
  runId: string,
  entries: readonly EventLogEntry[],
): { record: RunRecord; idempotencyKey: string | undefined; terminalAt: number | undefined } {
  const startEntry = entries.find((entry) => entry.event === 'start');
  const endEntry = [...entries].reverse().find((entry) => entry.event === 'end');
  const firstEntry = entries[0]!;
  const lastEntry = entries[entries.length - 1]!;
  const terminal = endEntry === undefined ? null : terminalStateFromEndEntry(endEntry);
  const { contextRef, idempotencyKey } = readStartMetadata(startEntry);
  return {
    record: {
      contextRef,
      idempotencyKey,
      status: rehydratedStatus(runId, { startEntry, endEntry, firstEntry, lastEntry, terminal }),
      resumable: terminal?.resumable ?? false,
      cancelRequested: false,
      lastCancelRequest: undefined,
      cancelListeners: new Set(),
      subscribers: new Set(),
      terminalWaiters: [],
      terminalEndEntry: endEntry,
      watchdog: undefined,
      slowRunWatchdog: undefined,
      slowRunSuspensions: 0,
      startPromise: undefined,
      finishPromise: undefined,
      retentionTimer: undefined,
    },
    idempotencyKey,
    // Terminal exactly when the log holds an 'end' entry (`terminal` is derived from it), so the
    // end entry's own timestamp is the terminal time — never a "now" substitute.
    terminalAt: endEntry?.recordedAt,
  };
}

function terminalStateFromEndEntry(entry: EventLogEntry): { state: TerminalRunOutcome; resumable: boolean } {
  if (!isRecord(entry.data)) return { state: 'failed', resumable: false };
  const status = entry.data.status;
  const unsuccessful: TerminalRunOutcome = status === 'canceled' ? 'cancelled' : 'failed';
  const state: TerminalRunOutcome = status === 'succeeded' ? 'succeeded' : unsuccessful;
  return { state, resumable: entry.data.resumable === true };
}

// ---------------------------------------------------------------------------
// start()/stream() phase helpers
//
// `start()` and `stream()` were each over the complexity gate (cyclomatic 12/13,
// cognitive 12/12). Both are broken up the same way: pure/near-pure pieces with
// real branching extracted to named, independently-testable top-level functions
// (typed against plain object shapes rather than the private `RunRecord`, so
// they can be exported without leaking that internal type), leaving each method
// itself a flat sequence with only its two or three irreducible guard clauses.
// ---------------------------------------------------------------------------

/**
 * `start()`'s idempotency-replay lookup: the run id an existing `idempotencyKey` already maps to,
 * or `undefined` when there is no key or no existing mapping (a fresh start proceeds normally).
 * Pure.
 */
export function resolveIdempotentReplayRunId({ idempotencyIndex, idempotencyKey }: { readonly idempotencyIndex: ReadonlyMap<string, string>; readonly idempotencyKey: string | undefined }
): string | undefined {
  if (idempotencyKey === undefined) return undefined;
  return idempotencyIndex.get(idempotencyKey);
}

/** Registers `runId` under `idempotencyKey` in `idempotencyIndex` — a no-op when no key was supplied. */
export function registerIdempotencyKeyIfPresent({ idempotencyIndex, idempotencyKey, runId }: { readonly idempotencyIndex: Map<string, string>; readonly idempotencyKey: string | undefined; readonly runId: string }
): void {
  if (idempotencyKey === undefined) return;
  idempotencyIndex.set(idempotencyKey, runId);
}

/**
 * Removes `idempotencyKey`'s mapping from `idempotencyIndex`, but only when it still points at
 * `runId` — used to roll back a failed durable `'start'` append without clobbering a different
 * run that may have since claimed the same key (defensive; `start()`'s own locking makes that
 * race unreachable today, but the check costs nothing and documents the invariant).
 */
export function clearIdempotencyIndexEntryIfMatching({ idempotencyIndex, idempotencyKey, runId }: { readonly idempotencyIndex: Map<string, string>; readonly idempotencyKey: string | undefined; readonly runId: string }
): void {
  if (idempotencyKey !== undefined && idempotencyIndex.get(idempotencyKey) === runId) {
    idempotencyIndex.delete(idempotencyKey);
  }
}

/**
 * Default terminal-run retention window: how long a completed/failed/cancelled run's in-memory
 * record stays readable via `get`/`list`/`stream`/`resume` before eviction. `runs.set()` never had
 * a matching `runs.delete()` for a run that finishes normally — every terminal run's record was kept
 * for the daemon process's entire lifetime, unbounded by run volume or uptime. Terminal runs are
 * still read after they end (status polling, run-history listing, stream reconnects), so the fix
 * cannot be "delete on completion" — this bounds *how long* a terminal record survives instead of
 * deleting it immediately. 24h comfortably covers same-day polling/listing/reconnect without
 * retaining every run a long-lived daemon ever processed.
 */
export const DEFAULT_TERMINAL_RETENTION_MS = 24 * 60 * 60 * 1000;

/**
 * Default hard cap on concurrently-retained terminal run records, independent of
 * {@link DEFAULT_TERMINAL_RETENTION_MS} — the oldest terminal record is evicted once this is
 * exceeded. A TTL alone does not bound memory when runs complete faster than they age out (a burst
 * arriving within the retention window keeps growing); this cap gives a true worst-case bound
 * regardless of arrival rate.
 */
export const DEFAULT_MAX_TERMINAL_RUNS = 1000;

/**
 * Default wall-clock threshold for the slow-run notice (distinct from the crash/inactivity watchdog
 * above): how long a run may go with no agent-event `emit()` (excluding the notice itself) before a `'slow_running'` agent event tells the UI
 * "this is taking longer than usual," without ever finishing the run. See {@link armSlowRunWatchdogIfConfigured}'s
 * doc for the full "why a second, non-terminating watchdog" rationale. 45s was picked as long enough
 * that an ordinary quiet stretch (the agent thinking between tool calls, a slow but healthy model
 * response) does not trip it on every turn, and short enough that a genuinely stalled run (the
 * reported symptom: a spawned CLI process alive but starved of CPU under heavy concurrent load, so it
 * never crashes and never gets caught by anything that only reacts to process exit) is flagged well
 * before an operator gives up waiting and assumes the product is broken.
 */
export const DEFAULT_SLOW_RUN_THRESHOLD_MS = 45_000;

/**
 * How long a just-terminal run should remain retained before its eviction timer fires: `retentionMs`
 * minus however much of that window has already elapsed since `terminalAt`. Floored at `0` so a run
 * that was already past its retention window when this is computed (relevant for `rehydrate()`,
 * where a run may have gone terminal long before this process started) schedules an immediate
 * eviction rather than a negative-delay timer. Pure.
 */
export function computeRetentionDelayMs({ terminalAt, retentionMs, now }: { readonly terminalAt: number; readonly retentionMs: number; readonly now: number }): number {
  return Math.max(0, retentionMs - (now - terminalAt));
}

/** The durable `'start'` entry's payload — pure field mapping, split out of `start()` so its two optional-field spreads don't count toward that method's own complexity. */
export function buildStartPayload({ runId, startInput }: { readonly runId: string; readonly startInput: Pick<StartRunInput, 'contextRef' | 'agentId' | 'idempotencyKey'> }
): RunStartPayload {
  return {
    runId,
    contextRef: startInput.contextRef,
    ...(startInput.agentId !== undefined ? { agentId: startInput.agentId } : {}),
    ...(startInput.idempotencyKey !== undefined ? { idempotencyKey: startInput.idempotencyKey } : {}),
  };
}

/**
 * Arms `record.watchdog` when `timeoutMs` is configured — a no-op otherwise. `record` is typed as a
 * plain `{watchdog}` shape (not `Pick<RunRecord, 'watchdog'>`) purely so this function can be
 * exported without naming the private `RunRecord` type in a public signature.
 */
export function armWatchdogIfConfigured({ record, timeoutMs, onTimeout }: { readonly record: { watchdog: InactivityWatchdog | undefined }; readonly timeoutMs: number | undefined; readonly onTimeout: () => void }
): void {
  if (timeoutMs === undefined) return;
  record.watchdog = createInactivityWatchdog({ timeoutMs, onTimeout });
}

/**
 * Arms `record.slowRunWatchdog` when `timeoutMs` is configured — a no-op otherwise (the kernel-wide
 * opt-out: `CreateRunLifecycleInput.slowRunThresholdMs: null`). Deliberately a sibling of
 * {@link armWatchdogIfConfigured} rather than a shared helper: the two watchdogs are configured from
 * different inputs (a per-`start()` opt-in vs. a kernel-wide default) and their `onTimeout` callbacks
 * have opposite consequences for the run (terminates it vs. only reports a status), and folding them
 * into one parameterized function would obscure that asymmetry at every call site for the sake of a
 * three-line dedup. `record` is typed as a plain `{slowRunWatchdog}` shape for the same exportability
 * reason {@link armWatchdogIfConfigured} already documents.
 */
export function armSlowRunWatchdogIfConfigured({ record, timeoutMs, onTimeout }: { readonly record: { slowRunWatchdog: InactivityWatchdog | undefined }; readonly timeoutMs: number | undefined; readonly onTimeout: () => void }
): void {
  if (timeoutMs === undefined) return;
  record.slowRunWatchdog = createInactivityWatchdog({ timeoutMs, onTimeout });
}

/**
 * `stream()`'s replay-delivery step: sends every already-durable entry to `onEvent`, returning the
 * delivered eventIds so a caller can avoid re-delivering the same event from a different source
 * (buffered live events observed during the replay, a terminal catch-up event). Pure aside from
 * calling the injected `onEvent`.
 */
export function deliverReplayedEvents({ runId, entries, onEvent }: { readonly runId: string; readonly entries: readonly EventLogEntry[]; readonly onEvent: (event: RunProtocolEvent) => void }
): Set<string> {
  const deliveredEventIds = new Set<string>();
  for (const entry of entries) {
    const event = toRunEvent(runId, entry);
    deliveredEventIds.add(event.eventId);
    onEvent(event);
  }
  return deliveredEventIds;
}

/**
 * Delivers every event in `events` not already present in `deliveredEventIds`, marking each as
 * delivered as it goes. Reused in `stream()` for both the buffered-live-event catch-up and the
 * single terminal-event catch-up, so the "don't double-deliver" bookkeeping lives in one place.
 */
export function deliverUndeliveredEvents({ events, deliveredEventIds, onEvent }: { readonly events: readonly RunProtocolEvent[]; readonly deliveredEventIds: Set<string>; readonly onEvent: (event: RunProtocolEvent) => void }
): void {
  for (const event of events) {
    if (!deliveredEventIds.has(event.eventId)) {
      deliveredEventIds.add(event.eventId);
      onEvent(event);
    }
  }
}

/**
 * Closes out a `stream()` subscription once replay and catch-up delivery are done: a terminal run's
 * subscriber is removed immediately (no further event will ever come), a still-live run's stays
 * registered behind the returned `unsubscribe`. `record` is typed as a plain `{subscribers}` shape
 * for the same exportability reason as {@link armWatchdogIfConfigured}.
 */
export function finishStreamSubscription({ record, subscriber, terminal }: { readonly record: { subscribers: Set<(event: RunProtocolEvent) => void> }; readonly subscriber: (event: RunProtocolEvent) => void; readonly terminal: boolean }
): StreamSubscribeResult {
  if (terminal) {
    record.subscribers.delete(subscriber);
    return { kind: 'ok', unsubscribe: () => {} };
  }
  return { kind: 'ok', unsubscribe: () => record.subscribers.delete(subscriber) };
}

/**
 * Constructs a fresh in-memory `RunRecord` for a new `start()` call. Pure field mapping with no
 * branches at all — not exported (would leak the private `RunRecord` type), kept as a named
 * function purely so `start()` itself reads as "build the record, register it" rather than an
 * 11-field literal inline.
 */
function buildNewRunRecord(
  startInput: Pick<StartRunInput, 'contextRef' | 'idempotencyKey'>,
  runId: string,
  now: number,
): RunRecord {
  return {
    contextRef: startInput.contextRef,
    idempotencyKey: startInput.idempotencyKey,
    status: { id: runId, state: 'running', startedAt: now, updatedAt: now, endedAt: undefined },
    resumable: false,
    cancelRequested: false,
    lastCancelRequest: undefined,
    cancelListeners: new Set(),
    subscribers: new Set(),
    terminalWaiters: [],
    terminalEndEntry: undefined,
    watchdog: undefined,
    slowRunWatchdog: undefined,
    slowRunSuspensions: 0,
    startPromise: undefined,
    finishPromise: undefined,
    retentionTimer: undefined,
  };
}

export interface CreateRunLifecycleInput {
  /** Share the negotiated bridge/executor digest store so run eviction also releases proofs. */
  readonly delegatedResultCorrelation?: DelegatedResultCorrelation;
  readonly eventLog: EventLog;
  /** Host-owned sink for asynchronous lifecycle failures that cannot be returned to a caller. Defaults to `console.error`. */
  readonly onInternalError?: (context: RunLifecycleInternalErrorContext) => void;
  /** How long a terminal run's in-memory record is retained before eviction. See {@link DEFAULT_TERMINAL_RETENTION_MS}. Defaults to that constant. */
  readonly terminalRetentionMs?: number;
  /** Hard cap on concurrently-retained terminal run records. See {@link DEFAULT_MAX_TERMINAL_RUNS}. Defaults to that constant. */
  readonly maxTerminalRuns?: number;
  /**
   * When `true`, evicting a terminal run record (retention timer or `maxTerminalRuns` cap) also calls
   * `eventLog.drop()` for it, giving the run's events the same lifetime as its record. Off by default
   * because a durable adapter's `drop()` deletes stored rows (`@jini-ai/daemon/store/event-log/sqlite`),
   * which would turn a memory bound into data loss for a host that never asked for it; a host whose
   * log is in-memory only can opt in. A failed drop is reported through `onInternalError`
   * (`source: 'event-log-drop'`).
   */
  readonly dropEventsOnEviction?: boolean;
  /**
   * How long a run may go with no agent-event `emit()` (excluding the notice itself) before a `'slow_running'` agent event tells the UI the
   * turn is taking longer than usual — never a terminating action; see
   * {@link armSlowRunWatchdogIfConfigured}'s doc. Applies kernel-wide to every `start()`ed run, unlike
   * `StartRunInput.inactivityTimeoutMs` (which requires a per-call opt-in and none of this codebase's
   * production callers supply). Defaults to {@link DEFAULT_SLOW_RUN_THRESHOLD_MS} so this reaches
   * production without any caller change. Pass `null` to disable it entirely for this lifecycle
   * instance.
   */
  readonly slowRunThresholdMs?: number | null;
}

export interface RunLifecycleInternalErrorContext {
  readonly source: 'inactivity-timeout' | 'slow-run-notice' | 'event-log-drop';
  readonly runId: string;
  readonly error: unknown;
}

/**
 * Creates the in-process `RunLifecycle` reference implementation.
 *
 * @param input.eventLog - The durable `EventLog` port this lifecycle appends to and replays from.
 * @param input.terminalRetentionMs - See {@link CreateRunLifecycleInput.terminalRetentionMs}.
 * @param input.maxTerminalRuns - See {@link CreateRunLifecycleInput.maxTerminalRuns}.
 * @param input.dropEventsOnEviction - See {@link CreateRunLifecycleInput.dropEventsOnEviction}.
 * @returns A `RunLifecycle` backed by an in-memory run registry plus the injected `EventLog`.
 * @complexity Per-call complexities documented on each method; the registry itself is a `Map` keyed by `runId` (O(1) lookup). Memory is bounded: non-terminal runs are O(n) in concurrently-live runs, and terminal runs are capped at `maxTerminalRuns` (each additionally bounded in retention time by `terminalRetentionMs`) rather than growing for the life of the process.
 * @overallScore 100/100
 */
export function createRunLifecycle(requiredArgs: Pick<CreateRunLifecycleInput, "eventLog">, optionalArgs: Pick<CreateRunLifecycleInput, "onInternalError" | "terminalRetentionMs" | "maxTerminalRuns" | "slowRunThresholdMs" | "dropEventsOnEviction" | "delegatedResultCorrelation"> = {}): RunLifecycle {
  const input: CreateRunLifecycleInput = { ...requiredArgs, ...optionalArgs };
  const { eventLog } = input;
  const terminalRetentionMs = input.terminalRetentionMs ?? DEFAULT_TERMINAL_RETENTION_MS;
  const maxTerminalRuns = input.maxTerminalRuns ?? DEFAULT_MAX_TERMINAL_RUNS;
  // `null` is the explicit opt-out; `undefined` (the field simply omitted, true of every production
  // caller today) resolves to the default so the slow-run notice reaches production with no caller
  // change required — see `CreateRunLifecycleInput.slowRunThresholdMs`'s own doc.
  const slowRunThresholdMs = input.slowRunThresholdMs === null ? undefined : (input.slowRunThresholdMs ?? DEFAULT_SLOW_RUN_THRESHOLD_MS);
  const runs = new Map<string, RunRecord>();
  const idempotencyIndex = new Map<string, string>();
  // Terminal runIds in the order they were tracked (oldest first) — the LRU order `enforceTerminalCap`
  // trims from. A run leaves this list exactly once, either via its retention timer firing or via
  // `resume()` reclaiming it; see `evictTerminalRun`/`untrackTerminalRun`.
  const terminalRunOrder: string[] = [];
  let hydration: Promise<void> | null = null;

  function requireRun(runId: string): RunRecord {
    const record = runs.get(runId);
    if (!record) {
      throw new Error(`RunLifecycle: unknown run "${runId}"`);
    }
    return record;
  }

  /**
   * A subscriber is a transport-owned callback (e.g. an SSE writer) outside this module's
   * control. One subscriber throwing (a dead socket, a broken client) must never abort the
   * fan-out to the others, nor propagate out through `emit()`/`finish()` into driver code that
   * has nothing to do with that transport — see CR-R1 in
   * `ADS-memory/reports/code-review/CR-backend-coverage-push-2026-07-20.md`.
   */
  function notifySubscribers(record: RunRecord, event: RunProtocolEvent): void {
    for (const subscriber of record.subscribers) {
      try {
        subscriber(event);
      } catch {
        // Isolated by design — see the function doc above.
      }
    }
  }

  async function appendEvent(runId: string, record: RunRecord, event: string, data: unknown): Promise<RunProtocolEvent> {
    const entry = await eventLog.append({ runId, event, data });
    const runEvent = toRunEvent(runId, entry);
    notifySubscribers(record, runEvent);
    return runEvent;
  }

  /** `start()`'s phase 2: appends the durable `'start'` entry, rolling back the in-memory record and idempotency-index entry on failure. */
  async function appendStartOrRollback(runId: string, record: RunRecord, startInput: StartRunInput): Promise<void> {
    const startPayload = buildStartPayload({ runId: runId, startInput: startInput });
    const startPromise = appendEvent(runId, record, 'start', startPayload).then(() => undefined);
    record.startPromise = startPromise;
    try {
      await startPromise;
      record.startPromise = undefined;
    } catch (error) {
      runs.delete(runId);
      input.delegatedResultCorrelation?.clearRun({ runId });
      clearIdempotencyIndexEntryIfMatching({ idempotencyIndex: idempotencyIndex, idempotencyKey: startInput.idempotencyKey, runId: runId });
      throw error;
    }
  }

  /**
   * Waits out a record's in-flight durable `'start'` append, swallowing its failure.
   *
   * The read-only queries (`get`/`list`) use this so they never observe the window in which the
   * in-memory record exists but its durable `'start'` entry does not: a rejecting append unwinds the
   * record entirely, so anything reported from inside that window is a run that never existed. The
   * rejection itself belongs to `start()`'s own caller, which is why it is dropped here rather than
   * propagated out of a query that was only asked "what runs are there".
   */
  async function settlePendingStart(record: RunRecord | undefined): Promise<void> {
    if (record?.startPromise === undefined) return;
    try {
      await record.startPromise;
    } catch {
      // Reported to `start()`'s caller — see above.
    }
  }

  /** Settles like `promise`, or rejects with the signal's reason once it aborts; the listener is always released. */
  function abortable({ promise }: { promise: Promise<unknown> | undefined }, { signal }: { signal: AbortSignal | undefined }): Promise<unknown> {
    if (!signal) return Promise.resolve(promise);
    if (signal.aborted) return Promise.reject(signal.reason);
    return new Promise((resolve, reject) => {
      const onAbort = (): void => { reject(signal.reason); };
      signal.addEventListener('abort', onAbort, { once: true });
      Promise.resolve(promise).then(resolve, reject).finally(() => { signal.removeEventListener('abort', onAbort); });
    });
  }

  /** Registers a terminal waiter; an abort removes it again so a cancelled wait retains nothing. */
  function parkTerminalWaiter({ record }: { record: RunRecord }, { signal }: { signal: AbortSignal | undefined }): Promise<RunStatus> {
    signal?.throwIfAborted();
    return new Promise((resolve, reject) => {
      const onAbort = (): void => {
        const index = record.terminalWaiters.indexOf(waiter);
        if (index >= 0) record.terminalWaiters.splice(index, 1);
        reject(signal?.reason);
      };
      const waiter = (status: RunStatus): void => {
        signal?.removeEventListener('abort', onAbort);
        resolve(status);
      };
      record.terminalWaiters.push(waiter);
      signal?.addEventListener('abort', onAbort, { once: true });
    });
  }

  function resolveTerminalWaiters(record: RunRecord): void {
    const waiters = record.terminalWaiters.splice(0, record.terminalWaiters.length);
    const status = toPublicStatus(record);
    for (const resolve of waiters) {
      resolve(status);
    }
  }

  function removeFromTerminalOrder(runId: string): void {
    const index = terminalRunOrder.indexOf(runId);
    if (index !== -1) terminalRunOrder.splice(index, 1);
  }

  /**
   * Evicts a terminal run's in-memory record: drops it from `runs`, cleans its `idempotencyIndex`
   * entry (a stale entry would otherwise resolve `start()`'s idempotency replay to a run
   * `requireRun` can no longer find, turning a harmless re-post into a thrown error), and removes it
   * from `terminalRunOrder`. Called from a retention timer firing or from `enforceTerminalCap`. A
   * no-op if the run was already reclaimed by `resume()` (its timer is cancelled there) or evicted
   * by the other path (cap eviction can race a timer for the same run — only the first wins,
   * `runs.get` returns `undefined` for the second).
   */
  function evictTerminalRun(runId: string): void {
    removeFromTerminalOrder(runId);
    const record = runs.get(runId);
    if (!record) return;
    record.retentionTimer = undefined;
    runs.delete(runId);
    input.delegatedResultCorrelation?.clearRun({ runId });
    clearIdempotencyIndexEntryIfMatching({ idempotencyIndex: idempotencyIndex, idempotencyKey: record.idempotencyKey, runId: runId });
    if (input.dropEventsOnEviction === true) void dropEvictedRunEvents(runId);
  }

  /** `evictTerminalRun`'s opt-in event drop (see `CreateRunLifecycleInput.dropEventsOnEviction`). Runs from a timer, so a failure is reported, never thrown. */
  async function dropEvictedRunEvents(runId: string): Promise<void> {
    try {
      await eventLog.drop({ runId });
    } catch (error) {
      reportInternalError({ source: 'event-log-drop', runId, error });
    }
  }

  /** Hands `context` to `onInternalError` (or `console.error`), containing a throwing sink. */
  function reportInternalError(context: RunLifecycleInternalErrorContext): void {
    try {
      if (input.onInternalError) input.onInternalError(context);
      // eslint-disable-next-line no-console
      else console.error(`[@jini-ai/daemon] internal error (${context.source}, runId=${context.runId})`, redactSecrets({ input: inspect(context.error) }, { redactPii: false }));
    } catch (sinkError) {
      // eslint-disable-next-line no-console
      console.error(`[@jini-ai/daemon] internal error sink failed (${context.source}, runId=${context.runId})`, redactSecrets({ input: inspect(sinkError) }, { redactPii: false }));
    }
  }

  /** Trims the oldest terminal records until `terminalRunOrder` is back at or under `maxTerminalRuns`. */
  function enforceTerminalCap(): void {
    while (terminalRunOrder.length > maxTerminalRuns) {
      evictTerminalRun(terminalRunOrder[0]!);
    }
  }

  /**
   * Arms `record`'s retention timer and enrolls it in `terminalRunOrder` — called once per run,
   * right when it first becomes terminal (from `finish()`) or when an already-terminal run is
   * rehydrated (from `rehydrateOne`). `terminalAt` is the real terminal timestamp (the durable
   * `'end'` entry's `recordedAt`), not "now": a rehydrated run may have gone terminal long before
   * this process started, and its remaining retention window must account for that instead of
   * restarting the full window on every restart.
   */
  function trackTerminalRun(runId: string, record: RunRecord, terminalAt: number): void {
    terminalRunOrder.push(runId);
    const delay = computeRetentionDelayMs({ terminalAt: terminalAt, retentionMs: terminalRetentionMs, now: Date.now() });
    const timer = setTimeout(() => evictTerminalRun(runId), delay);
    if (typeof timer.unref === 'function') timer.unref();
    record.retentionTimer = timer;
    enforceTerminalCap();
  }

  /** Reverses `trackTerminalRun`: cancels the pending eviction and un-enrolls `runId`. Called from `resume()` so a reclaimed run cannot be evicted out from under its new, non-terminal life. */
  function untrackTerminalRun(runId: string, record: RunRecord): void {
    removeFromTerminalOrder(runId);
    if (record.retentionTimer) {
      clearTimeout(record.retentionTimer);
      record.retentionTimer = undefined;
    }
  }

  /**
   * Fires when a run's inactivity watchdog times out with no intervening
   * `emit()`/`finish()`. A deliberate watchdog kill is permanent: automatically restarting
   * it would undo the operator's inactivity policy. Other unexpected process failures still
   * retain their original runtime classification.
   *
   * There is deliberately no "run missing or already terminal" guard here (an earlier
   * `!record || isTerminalRunState(...)` guard was removed as unreachable through the public API,
   * and the handler needs nothing from the record — it acts through `lifecycle.emit`/`finish` by id):
   *
   * - terminal: every route to a terminal state runs through `finish()`, which
   *   calls `record.watchdog?.cancel()` and assigns `record.status.state` in the *same synchronous
   *   block* after its durable end append resolves. There is no interleaving point between the two,
   *   so "watchdog still armed" and "record already terminal" cannot both hold when this fires. (If
   *   the end append *throws*, the watchdog stays armed but the run also stays non-terminal.)
   * - missing: the only `runs.delete()` calls are `start()`'s unwind on a failed durable start
   *   append, which happens strictly before the watchdog is armed a few lines later, and terminal
   *   eviction, which only ever touches runs whose watchdog `finish()` already cancelled. And
   *   `createInactivityWatchdog` never calls `onTimeout` after `cancel()`.
   *
   * Note the "start/finish race" test below does *not* exercise this handler despite its name: by the
   * time it advances the timers, `finish()` has already cancelled the watchdog, so the callback
   * never runs at all. It still correctly asserts that no second `finish()` happens.
   */
  async function handleInactivityTimeout(runId: string): Promise<void> {
    try {
      // A deliberate inactivity kill is permanent for this attempt, not an auto-resume signal.
      await lifecycle.emit({ runId, input: { event: 'agent', data: { type: 'status', label: 'Stopped by inactivity watchdog', detail: 'inactivity-watchdog' } } });
      await lifecycle.finish({ runId, status: 'failed', code: null, signal: null, resumable: false });
    } catch (error) {
      const context: RunLifecycleInternalErrorContext = { source: 'inactivity-timeout', runId, error };
      try {
        if (input.onInternalError) {
          input.onInternalError(context);
        } else {
          // eslint-disable-next-line no-console
          console.error(`[@jini-ai/daemon] internal error (inactivity-timeout, runId=${runId})`, redactSecrets({ input: inspect(error) }, { redactPii: false }));
        }
      } catch (sinkError) {
        // A diagnostic sink must not turn a contained timer failure into another unhandled
        // rejection.
        // eslint-disable-next-line no-console
        console.error(`[@jini-ai/daemon] internal error sink failed (inactivity-timeout, runId=${runId})`, redactSecrets({ input: inspect(sinkError) }, { redactPii: false }));
      }
    }
  }

  /**
   * Fires when a run's slow-run watchdog times out with no intervening `emit()` — the non-terminating
   * counterpart to {@link handleInactivityTimeout} above. Reports a `'slow_running'` agent event
   * through the ordinary `emit()` path rather than finishing the run: the run is left exactly as it
   * was, still `'running'`, so a legitimately slow-but-working turn is never mistaken for a dead one.
   * `'slow_running'` is its own `RunAgentPayload` variant, not a reuse of the pre-existing `'status'`
   * one — see that variant's own doc in `@jini-ai/protocol`'s `events.ts` for why: nothing in this
   * codebase renders `'status'` events today, so reusing it here would have shipped an invisible fix.
   *
   * Like {@link handleInactivityTimeout}, it has no "run missing or already terminal" guard (see
   * that function's doc for why such a guard is unreachable). One more case is worth naming:
   * `finish()` cancels `record.slowRunWatchdog` synchronously before its
   * `record.status.state` write ever yields, so between this timer firing and `emit()` actually
   * running there is no window where a normal `finish()` could race it — but `emit()` itself can
   * still legitimately throw (e.g. a `finishPromise` in flight from a concurrent `cancel()`-driven
   * finish that started after this callback fired but before its `emit()` call
   * completes its internal `await record.startPromise`), which is exactly what the `try`/`catch`
   * below contains rather than letting escape as an unhandled rejection.
   */
  async function handleSlowRunNotice(runId: string): Promise<void> {
    try {
      await lifecycle.emit({ runId: runId, input: {
        event: 'agent',
        data: {
          type: 'slow_running',
          detail: 'Still working — this turn is taking longer than usual.',
        },
      } });
    } catch (error) {
      const context: RunLifecycleInternalErrorContext = { source: 'slow-run-notice', runId, error };
      try {
        if (input.onInternalError) {
          input.onInternalError(context);
        } else {
          // eslint-disable-next-line no-console
          console.error(`[@jini-ai/daemon] internal error (slow-run-notice, runId=${runId})`, redactSecrets({ input: inspect(error) }, { redactPii: false }));
        }
      } catch (sinkError) {
        // Same containment reasoning as `handleInactivityTimeout`'s own catch below it.
        // eslint-disable-next-line no-console
        console.error(`[@jini-ai/daemon] internal error sink failed (slow-run-notice, runId=${runId})`, redactSecrets({ input: inspect(sinkError) }, { redactPii: false }));
      }
    }
  }

  /**
   * Restores one run into the in-memory index from its durable log. Returns what the caller must do
   * about it: `'skipped'` for a run already resident or with no usable log, otherwise whether the
   * restored run was already terminal.
   */
  async function rehydrateOne(runId: string): Promise<'skipped' | 'terminal' | 'non-terminal'> {
    if (runs.has(runId)) return 'skipped';
    const replay = await eventLog.replay({ runId: runId, afterCursor: null });
    if (replay.kind !== 'ok' || replay.entries.length === 0) return 'skipped';

    const { record, idempotencyKey, terminalAt } = rehydratedRunRecord(runId, replay.entries);
    runs.set(runId, record);
    if (idempotencyKey !== undefined) idempotencyIndex.set(idempotencyKey, runId);
    // `eventLog.listRunIds()` returns every run id the durable log has ever seen, with no bound of
    // its own — without this, a restart would re-populate `runs` with the daemon's entire terminal
    // run history on every boot, reproducing the same unbounded growth this module now guards
    // against at runtime.
    if (terminalAt === undefined) return 'non-terminal';
    trackTerminalRun(runId, record, terminalAt);
    return 'terminal';
  }

  const lifecycle: RunLifecycle = {
    async rehydrate(_args: Record<string, never>): Promise<void> {
      if (hydration) return hydration;
      hydration = (async () => {
        const rehydratedNonTerminalRunIds: string[] = [];
        for (const runId of await eventLog.listRunIds({  })) {
          if (await rehydrateOne(runId) === 'non-terminal') {
            rehydratedNonTerminalRunIds.push(runId);
          }
        }

        // A process restart cannot retain an in-memory child process or cancellation listener.
        // Persist an honest terminal outcome instead of advertising an orphaned run as still live.
        for (const runId of rehydratedNonTerminalRunIds) {
          await lifecycle.finish({ runId, status: 'failed', code: null, signal: null, resumable: true });
        }
      })();
      return hydration;
    },

    async start(requiredArgs: Pick<StartRunInput, "contextRef">, optionalArgs: Pick<StartRunInput, "agentId" | "idempotencyKey" | "runId" | "inactivityTimeoutMs"> = {}): Promise<StartRunResult> {
  const startInput: StartRunInput = { ...requiredArgs, ...optionalArgs };
      // Synchronous on purpose: `resolveIdempotentReplayRunId` does no I/O, and the common case
      // (no idempotencyKey, or a fresh one) must reach `runs.set()` below in the same synchronous
      // turn as this call — not after even one microtask tick — so a caller that races `finish()`
      // in immediately after `start()` (before ever awaiting it) still finds the record `finish()`
      // needs. Wrapping this check in its own `await`ed async function previously broke exactly
      // that: an `async function` always defers its continuation by a microtask even when its body
      // never itself awaits, which shifted `runs.set()` behind the racing `finish()` call.
      const existingRunId = resolveIdempotentReplayRunId({ idempotencyIndex: idempotencyIndex, idempotencyKey: startInput.idempotencyKey });
      if (existingRunId !== undefined) {
        const existing = requireRun(existingRunId);
        await existing.startPromise;
        return { run: toPublicStatus(existing), started: false };
      }

      const runId = startInput.runId ?? randomUUID();
      if (runs.has(runId)) {
        throw new Error(`RunLifecycle: run "${runId}" already exists`);
      }

      const record = buildNewRunRecord(startInput, runId, Date.now());
      runs.set(runId, record);
      registerIdempotencyKeyIfPresent({ idempotencyIndex: idempotencyIndex, idempotencyKey: startInput.idempotencyKey, runId: runId });

      await appendStartOrRollback(runId, record, startInput);

      armWatchdogIfConfigured({ record: record, timeoutMs: startInput.inactivityTimeoutMs, onTimeout: () => {
        void handleInactivityTimeout(runId);
      } });
      armSlowRunWatchdogIfConfigured({ record: record, timeoutMs: slowRunThresholdMs, onTimeout: () => {
        void handleSlowRunNotice(runId);
      } });

      return { run: toPublicStatus(record), started: true };
    },

    async get({ runId }: { readonly runId: string }): Promise<RunStatus | undefined> {
      await settlePendingStart(runs.get(runId));
      // Re-read rather than reusing the record above: a failed start deletes it (see `start()`'s
      // unwind), and reporting a run whose durable `'start'` entry does not exist would advertise a
      // run no restart could ever rehydrate.
      const record = runs.get(runId);
      return record ? toPublicStatus(record) : undefined;
    },

    async list(_requiredArgs: Record<string, never>, { contextRef }: { readonly contextRef?: string } = {}): Promise<readonly RunStatus[]> {
      await Promise.all(Array.from(runs.values(), settlePendingStart));
      const all = Array.from(runs.values());
      const filtered = contextRef === undefined ? all : all.filter((record) => record.contextRef === contextRef);
      return filtered.map(toPublicStatus);
    },

    async cancel(request: RunCancelRequest): Promise<RunStatus> {
      const record = requireRun(request.runId);
      await record.startPromise;
      if (record.finishPromise) {
        return record.finishPromise;
      }
      if (isTerminalRunState({ state: record.status.state })) {
        return toPublicStatus(record);
      }
      record.cancelRequested = true;
      record.lastCancelRequest = request;
      record.status.updatedAt = Date.now();
      for (const listener of record.cancelListeners) {
        listener(request);
      }
      return toPublicStatus(record);
    },

    /**
     * Registers a cancel-intent listener. If `cancel()` was already called
     * for this run before this subscription, the listener fires immediately
     * with the original request (mirrors `AbortSignal`'s `aborted`+`addEventListener`
     * pairing) — otherwise a driver that attaches after the cancel already
     * happened would silently never learn about it, since a plain
     * subscribe-for-future-events registry has no memory of past firings.
     */
    onCancelRequested({ runId, listener }: { readonly runId: string; readonly listener: (request: RunCancelRequest) => void }): Unsubscribe {
      const record = requireRun(runId);
      if (record.cancelRequested && record.lastCancelRequest) {
        listener(record.lastCancelRequest);
      }
      record.cancelListeners.add(listener);
      return () => record.cancelListeners.delete(listener);
    },

    async emit({ runId, input }: { readonly runId: string; readonly input: DriverEmittableInput }): Promise<RunProtocolEvent> {
      const record = requireRun(runId);
      await record.startPromise;
      if (record.finishPromise || isTerminalRunState({ state: record.status.state })) {
        throw new Error(
          `RunLifecycle: cannot emit "${input.event}" on terminal run "${runId}" — drivers must stop emitting once finish() has been called`,
        );
      }
      record.watchdog?.noteActivity({});
      // The crash watchdog above counts ANY output (the process is alive). The slow-run notice asks
      // a different question — "has the person seen anything new?" — so only `agent` events count.
      // A CLI's raw stdout/stderr (e.g. Claude Code's 30 s `tool_progress` heartbeats during a long
      // tool call) is not rendered, and letting it reset this window meant the notice could never
      // fire during exactly the long, silent tool calls it exists for.
      if (input.event === 'agent') record.slowRunWatchdog?.noteActivity({});
      return appendEvent(runId, record, input.event, input.data);
    },

    async finish(requiredArgs: Pick<FinishRunInput, "runId" | "status" | "code" | "signal" | "resumable">, optionalArgs: Pick<FinishRunInput, "sessionRef"> = {}): Promise<RunStatus> {
  const finishInput: FinishRunInput = { ...requiredArgs, ...optionalArgs };
      const record = requireRun(finishInput.runId);
      await record.startPromise;
      if (record.finishPromise) {
        return record.finishPromise;
      }
      if (isTerminalRunState({ state: record.status.state })) {
        return toPublicStatus(record);
      }
      const finishing = (async (): Promise<RunStatus> => {
        const endPayload: RunEndPayload = {
          code: finishInput.code,
          signal: finishInput.signal,
          status: TERMINAL_OUTCOME_TO_END_STATUS[finishInput.status],
          resumable: finishInput.resumable,
          ...(finishInput.sessionRef !== undefined ? { sessionRef: finishInput.sessionRef } : {}),
        };
        const endEntry = await eventLog.append({ runId: finishInput.runId, event: 'end', data: endPayload });

        // Commit the in-memory terminal transition only after its durable end entry exists. Until
        // then `finishPromise` reserves the transition and blocks emits/concurrent finishes.
        record.watchdog?.cancel({});
        record.slowRunWatchdog?.cancel({});
        record.status.state = finishInput.status;
        record.status.updatedAt = endEntry.recordedAt;
        record.status.endedAt = endEntry.recordedAt;
        record.resumable = finishInput.resumable;
        record.terminalEndEntry = endEntry;
        trackTerminalRun(finishInput.runId, record, endEntry.recordedAt);
        const endEvent = toRunEvent(finishInput.runId, endEntry);
        notifySubscribers(record, endEvent);

        resolveTerminalWaiters(record);
        return toPublicStatus(record);
      })();
      record.finishPromise = finishing;
      try {
        return await finishing;
      } finally {
        if (record.finishPromise === finishing) {
          record.finishPromise = undefined;
        }
      }
    },

    async resume({ runId }: { readonly runId: string }): Promise<ResumeRunResult> {
      const record = requireRun(runId);
      const eligible = isTerminalRunState({ state: record.status.state }) && record.resumable;
      if (!eligible) {
        return { run: toPublicStatus(record), resumed: false };
      }
      untrackTerminalRun(runId, record);
      const now = Date.now();
      record.status.state = 'running';
      record.status.updatedAt = now;
      record.status.endedAt = undefined;
      record.resumable = false;
      record.cancelRequested = false;
      record.lastCancelRequest = undefined;
      record.terminalEndEntry = undefined;
      // Mirrors `start()`'s own arm call: a resumed run gets exactly the same fresh slow-run window a
      // freshly-started one does. Without this, `finish()`'s `record.slowRunWatchdog?.cancel()` (which
      // never fires again on its own — the underlying timer is one-shot) left the notice permanently
      // dark for the rest of a resumed run's life, silently disabling a feature the run is otherwise
      // still eligible for. Suspensions left open when the run ended can never be resumed (resume is a
      // no-op on a terminal run), so they are dropped here or they would keep the notice dark forever.
      record.slowRunSuspensions = 0;
      armSlowRunWatchdogIfConfigured({ record: record, timeoutMs: slowRunThresholdMs, onTimeout: () => {
        void handleSlowRunNotice(runId);
      } });
      // No protocol event is emitted here: none of RunProtocolEvent's six
      // kinds represents "resumed" (extraction-plan scope decision — see
      // archived provenance ledger). The event log's cursor sequence continues
      // unbroken; only RunStatus.state changes.
      return { run: toPublicStatus(record), resumed: true };
    },

    suspendSlowRunNotice({ runId }: { readonly runId: string }): void {
      const record = runs.get(runId);
      if (!record || isTerminalRunState({ state: record.status.state })) return;
      record.slowRunSuspensions += 1;
      record.slowRunWatchdog?.cancel({});
    },

    resumeSlowRunNotice({ runId }: { readonly runId: string }): void {
      const record = runs.get(runId);
      if (!record || isTerminalRunState({ state: record.status.state })) return;
      // Re-arm only when the LAST open suspension closes (see `RunRecord.slowRunSuspensions`).
      if (record.slowRunSuspensions > 0) record.slowRunSuspensions -= 1;
      if (record.slowRunSuspensions > 0) return;
      // Suspension cancels permanently. Resuming must create a new window, never revive that handle.
      record.slowRunWatchdog?.cancel({});
      armSlowRunWatchdogIfConfigured({ record, timeoutMs: slowRunThresholdMs, onTimeout: () => {
        void handleSlowRunNotice(runId);
      } });
    },

    async waitForTerminal({ runId }: { readonly runId: string }, { signal }: { readonly signal?: AbortSignal } = {}): Promise<RunStatus> {
      const record = requireRun(runId);
      // Awaited (and *propagated*, unlike in `get`/`list`) before any waiter is registered. A run
      // whose durable start append rejects is unwound, and nothing ever calls `finish()` for it — so
      // a waiter parked inside that window would never be resolved by anyone. Failing the wait with
      // the same error that failed the start is the only honest terminal answer, and awaiting first
      // means `terminalWaiters` can only ever hold waiters for a run that really does exist.
      // The abort signal is observed during that wait too: a stalled start append must not strand
      // a caller that has already given up (a pre-aborted signal rejects at once).
      await abortable({ promise: record.startPromise }, { signal });
      if (isTerminalRunState({ state: record.status.state })) {
        return toPublicStatus(record);
      }
      return parkTerminalWaiter({ record }, { signal });
    },

    async stream({ runId, onEvent }: { readonly runId: string; readonly onEvent: (event: RunProtocolEvent) => void }, options: StreamOptions = {}
    ): Promise<StreamSubscribeResult> {
      const record = runs.get(runId);
      if (!record) {
        return { kind: 'unknown-run' };
      }
      await record.startPromise;
      // Subscribe before awaiting the durable replay. Any event appended while the replay query is
      // in flight is buffered, then delivered after the replay entries, so a reconnect cannot lose
      // the narrow replay→subscribe interval or observe the live event ahead of older history.
      let replaying = true;
      const bufferedLiveEvents: RunProtocolEvent[] = [];
      const subscriber = (event: RunProtocolEvent) => {
        if (replaying) bufferedLiveEvents.push(event);
        else onEvent(event);
      };
      record.subscribers.add(subscriber);
      try {
        const replay = await eventLog.replay({ runId: runId, afterCursor: options.afterCursor ?? null });
        if (replay.kind !== 'ok') {
          record.subscribers.delete(subscriber);
          return replay;
        }
        const deliveredEventIds = deliverReplayedEvents({ runId: runId, entries: replay.entries, onEvent: onEvent });
        deliverUndeliveredEvents({ events: bufferedLiveEvents, deliveredEventIds: deliveredEventIds, onEvent: onEvent });
        replaying = false;

        const terminal = isTerminalRunState({ state: record.status.state });
        if (terminal && record.terminalEndEntry) {
          deliverUndeliveredEvents({ events: [toRunEvent(runId, record.terminalEndEntry)], deliveredEventIds: deliveredEventIds, onEvent: onEvent });
        }

        return finishStreamSubscription({ record: record, subscriber: subscriber, terminal: terminal });
      } catch (error) {
        // Subscription is installed before durable replay to close the replay→live race. Any
        // replay I/O or consumer callback failure must therefore remove it before propagating.
        record.subscribers.delete(subscriber);
        throw error;
      }
    },
  };

  return lifecycle;
}
